"""Application configuration.

Every value can be overridden by environment variables prefixed with ``MPLAB_``.
Defaults are chosen for *Local Secure Mode*: loopback-only, offline, no external
AI, conservative resource limits.  Remote/team mode must be enabled explicitly.
"""

from __future__ import annotations

import os
from dataclasses import dataclass, field, fields
from pathlib import Path
from typing import Literal

TRUE_VALUES = {"1", "true", "yes", "on"}
FALSE_VALUES = {"0", "false", "no", "off"}


def _env(name: str, default: str) -> str:
    return os.environ.get(f"MPLAB_{name}", default)


def _env_bool(name: str, default: bool) -> bool:
    raw = os.environ.get(f"MPLAB_{name}")
    if raw is None:
        return default
    lowered = raw.strip().lower()
    if lowered in TRUE_VALUES:
        return True
    if lowered in FALSE_VALUES:
        return False
    raise ValueError(f"MPLAB_{name} must be a boolean, got {raw!r}")


def _env_int(name: str, default: int) -> int:
    raw = os.environ.get(f"MPLAB_{name}")
    if raw is None:
        return default
    try:
        return int(raw)
    except ValueError as exc:  # pragma: no cover - defensive
        raise ValueError(f"MPLAB_{name} must be an integer, got {raw!r}") from exc


def _env_list(name: str, default: list[str]) -> list[str]:
    raw = os.environ.get(f"MPLAB_{name}")
    if raw is None:
        return list(default)
    return [item.strip() for item in raw.split(",") if item.strip()]


Mode = Literal["local_secure", "team_remote"]


@dataclass(frozen=True)
class Limits:
    """Hard resource ceilings applied to untrusted input and analytics."""

    max_upload_bytes: int = 512 * 1024 * 1024
    max_capture_bytes: int = 512 * 1024 * 1024
    max_packets_per_capture: int = 2_000_000
    max_packet_bytes: int = 16 * 1024 * 1024
    max_tcp_sessions_per_capture: int = 20_000
    max_stream_bytes: int = 512 * 1024 * 1024
    max_messages_per_stream: int = 500_000
    max_json_body_bytes: int = 2 * 1024 * 1024
    max_string_field_chars: int = 4_096
    max_rows_per_page: int = 1_000
    default_rows_per_page: int = 100
    max_project_files: int = 64
    max_project_total_bytes: int = 4 * 1024 * 1024 * 1024

    # Archive (.mplab) import guard rails.
    max_archive_entries: int = 20_000
    max_archive_depth: int = 12
    max_archive_uncompressed_bytes: int = 4 * 1024 * 1024 * 1024
    max_archive_entry_bytes: int = 512 * 1024 * 1024
    max_archive_compression_ratio: int = 200

    # Analysis execution.
    analysis_timeout_seconds: int = 900
    max_concurrent_jobs: int = 4
    rate_limit_requests: int = 600
    rate_limit_window_seconds: int = 60

    # AI context ceiling (characters of untrusted content sent to a model).
    max_ai_context_chars: int = 24_000
    max_ai_output_chars: int = 20_000


@dataclass(frozen=True)
class Settings:
    mode: Mode = field(default_factory=lambda: _env("MODE", "local_secure"))  # type: ignore[arg-type]
    host: str = field(default_factory=lambda: _env("HOST", "127.0.0.1"))
    port: int = field(default_factory=lambda: _env_int("PORT", 8010))
    debug: bool = field(default_factory=lambda: _env_bool("DEBUG", False))

    data_dir: Path = field(
        default_factory=lambda: Path(_env("DATA_DIR", "./data")).expanduser().resolve()
    )
    # Where uploaded captures live.  Kept outside the frontend's public dir and
    # outside the directory the API server executes code from.
    storage_dir: Path | None = None
    secrets_dir: Path | None = None

    frontend_origins: list[str] = field(
        default_factory=lambda: _env_list(
            "FRONTEND_ORIGINS", ["http://127.0.0.1:3000", "http://localhost:3000"]
        )
    )
    allowed_hosts: list[str] = field(
        default_factory=lambda: _env_list(
            "ALLOWED_HOSTS",
            ["127.0.0.1", "localhost", "[::1]", "testserver", "0.0.0.0", "host.docker.internal"],
        )
    )

    # External AI is opt-in.  Local Ollama counts as "local" but is still a
    # separate network egress, so it also requires explicit opt-in.
    allow_external_ai: bool = field(default_factory=lambda: _env_bool("ALLOW_EXTERNAL_AI", False))
    ollama_url: str = field(default_factory=lambda: _env("OLLAMA_URL", "http://127.0.0.1:11434"))
    ollama_model: str = field(default_factory=lambda: _env("OLLAMA_MODEL", "llama3.1"))

    run_jobs_in_subprocess: bool = field(
        default_factory=lambda: _env_bool("RUN_JOBS_IN_SUBPROCESS", False)
    )
    job_subprocess_timeout: int = field(
        default_factory=lambda: _env_int("JOB_SUBPROCESS_TIMEOUT", 900)
    )

    auto_create_schema: bool = field(
        default_factory=lambda: _env_bool("AUTO_CREATE_SCHEMA", True)
    )

    limits: Limits = field(default_factory=Limits)

    def __post_init__(self) -> None:
        if self.mode not in ("local_secure", "team_remote"):
            raise ValueError("MPLAB_MODE must be 'local_secure' or 'team_remote'")
        storage = self.storage_dir or (self.data_dir / "storage")
        secrets = self.secrets_dir or (self.data_dir / "secrets")
        object.__setattr__(self, "storage_dir", storage)
        object.__setattr__(self, "secrets_dir", secrets)

    @property
    def database_url(self) -> str:
        explicit = os.environ.get("MPLAB_DATABASE_URL")
        if explicit:
            return explicit
        return f"sqlite+pysqlite:///{(self.data_dir / 'mplab.db').as_posix()}"

    @property
    def is_remote_mode(self) -> bool:
        return self.mode == "team_remote"

    def ensure_directories(self) -> None:
        for path in (self.data_dir, self.storage_dir, self.secrets_dir):
            if path is None:  # pragma: no cover - defensive
                continue
            path.mkdir(parents=True, exist_ok=True)

    def redacted_summary(self) -> dict[str, object]:
        out: dict[str, object] = {}
        for f in fields(self):
            if f.name == "limits":
                out[f.name] = {lf.name: getattr(self.limits, lf.name) for lf in fields(Limits)}
                continue
            value = getattr(self, f.name)
            if isinstance(value, Path):
                out[f.name] = value.as_posix()
            else:
                out[f.name] = value
        return out


_settings: Settings | None = None


def get_settings() -> Settings:
    global _settings
    if _settings is None:
        _settings = Settings()
    return _settings


def reset_settings() -> None:
    """Test hook: drop the cached settings so env changes take effect."""
    global _settings
    _settings = None


def describe_env() -> list[dict[str, str]]:
    """Return the environment keys the app reacts to (never their values)."""
    return [{"name": f"MPLAB_{f.name}", "type": f.type} for f in fields(Settings)]

"""Errors shared across the backend.

Every error carries a stable machine readable ``code`` plus a human message that
is safe to render in the UI: no stack traces, no absolute paths, no secrets.
"""

from __future__ import annotations

from typing import Any


class AppError(Exception):
    """Base class for expected, user-visible failures."""

    status_code = 400
    code = "app_error"

    def __init__(self, message: str, *, details: dict[str, Any] | None = None) -> None:
        super().__init__(message)
        self.message = message
        self.details = details or {}

    def to_payload(self) -> dict[str, Any]:
        return {"error": {"code": self.code, "message": self.message, "details": self.details}}


class ValidationFailed(AppError):
    status_code = 422
    code = "validation_failed"


class NotFound(AppError):
    status_code = 404
    code = "not_found"


class Conflict(AppError):
    status_code = 409
    code = "conflict"


class PayloadTooLarge(AppError):
    status_code = 413
    code = "payload_too_large"


class UnsupportedFormat(AppError):
    status_code = 415
    code = "unsupported_format"


class LimitExceeded(AppError):
    status_code = 422
    code = "limit_exceeded"


class SecurityViolation(AppError):
    """Rejected because of a defensive control (traversal, origin, quota...)."""

    status_code = 403
    code = "security_violation"


class RateLimited(AppError):
    status_code = 429
    code = "rate_limited"


class Canceled(AppError):
    status_code = 499
    code = "canceled"


class DependencyUnavailable(AppError):
    """An optional external dependency (tshark, ollama) is not installed."""

    status_code = 503
    code = "dependency_unavailable"

"""Defensive helpers: request guards, path safety, rate limiting.

These controls live in the backend process because the browser UI is not a
trust boundary (see docs/THREAT_MODEL.md).
"""

from __future__ import annotations

import hashlib
import ipaddress
import os
import re
import threading
import time
import unicodedata
from collections import deque
from dataclasses import dataclass
from pathlib import Path, PurePosixPath
from urllib.parse import urlsplit

from .errors import PayloadTooLarge, RateLimited, SecurityViolation

# --------------------------------------------------------------------------- #
# Host / Origin / DNS-rebinding protection
# --------------------------------------------------------------------------- #

_CONTROL_CHARS = re.compile(r"[\x00-\x1f\x7f]")


def _normalise_host(value: str) -> str:
    host = value.strip().lower()
    if host.startswith("[") and host.endswith("]"):
        return host
    return host


def extract_host(authority: str) -> str:
    """Strip the port from a Host header value."""
    authority = authority.strip()
    if authority.startswith("["):
        # IPv6 literal, possibly with port.
        end = authority.find("]")
        if end != -1:
            return authority[: end + 1]
    if ":" in authority:
        return authority.rsplit(":", 1)[0]
    return authority


def is_loopback_host(host: str) -> bool:
    host = _normalise_host(host)
    if host in {"localhost", "localhost.localdomain"}:
        return True
    try:
        return ipaddress.ip_address(host).is_loopback
    except ValueError:
        return False


def check_host_header(host_header: str | None, allowed: list[str]) -> None:
    """Reject requests whose Host header is not on the allowlist.

    Blocking unknown Host values defeats DNS-rebinding attacks, where an
    attacker-controlled name resolves to 127.0.0.1 and the browser then talks
    to the local API with a foreign Origin.
    """
    if not host_header:
        raise SecurityViolation("Missing Host header.")
    if _CONTROL_CHARS.search(host_header):
        raise SecurityViolation("Malformed Host header.")
    host = _normalise_host(extract_host(host_header))
    allowed_normalised = {_normalise_host(extract_host(a)) for a in allowed}
    if host in allowed_normalised:
        return
    raise SecurityViolation(f"Host header {host!r} is not allowed.")


def origin_matches(origin: str, allowed_origins: list[str]) -> bool:
    if not origin:
        return False
    parts = urlsplit(origin)
    if parts.scheme not in {"http", "https"}:
        return False
    normalised = f"{parts.scheme}://{parts.netloc}".lower()
    return normalised in {o.rstrip('/').lower() for o in allowed_origins}


def is_cross_origin(origin: str | None, referer: str | None, allowed_origins: list[str]) -> bool:
    """True when the request appears to originate from a page we do not serve."""
    candidates = [c for c in (origin, referer) if c]
    if not candidates:
        return False
    return any(not origin_matches(c, allowed_origins) for c in candidates)


def request_host_is_loopback(host_header: str | None) -> bool:
    if not host_header:
        return True
    return is_loopback_host(extract_host(host_header))


# --------------------------------------------------------------------------- #
# Filesystem safety
# --------------------------------------------------------------------------- #

_UNSAFE_NAME_CHARS = re.compile(r'[<>:"|?*\x00-\x1f\x7f]')
_WINDOWS_RESERVED = {
    "con", "prn", "aux", "nul",
    *(f"com{i}" for i in range(1, 10)),
    *(f"lpt{i}" for i in range(1, 10)),
}


def safe_display_filename(raw: str | None, *, fallback: str = "upload") -> str:
    """Turn an untrusted upload name into a display-safe string.

    The result is only ever used for display and for generating a *suggested*
    name; stored files always get random server-side names.
    """
    if not raw:
        return fallback
    # Unicode normalisation first so look-alike traversal names collapse.
    name = unicodedata.normalize("NFKC", raw)
    name = name.replace("\\", "/").split("/")[-1]
    name = _CONTROL_CHARS.sub("", name)
    name = _UNSAFE_NAME_CHARS.sub("_", name)
    name = name.strip().strip(".")
    name = name.lstrip("-")
    if not name or name in {".", ".."}:
        return fallback
    stem = name.split(".")[0].lower()
    if stem in _WINDOWS_RESERVED:
        name = f"_{name}"
    return name[:200]


def validate_relative_path(candidate: str) -> PurePosixPath:
    """Validate an archive member path before it is ever joined to a root.

    Rejects absolute paths, drive letters, UNC paths, ``..`` traversal, control
    characters and empty components.
    """
    if not candidate or not candidate.strip():
        raise SecurityViolation("Archive entry has an empty name.")
    if len(candidate) > 1024:
        raise SecurityViolation("Archive entry name is too long.")
    if _CONTROL_CHARS.search(candidate):
        raise SecurityViolation("Archive entry name contains control characters.")
    if candidate.startswith("/") or candidate.startswith("\\"):
        raise SecurityViolation("Archive entry uses an absolute path.")
    if re.match(r"^[A-Za-z]:", candidate):
        raise SecurityViolation("Archive entry uses a drive letter.")
    normalised = unicodedata.normalize("NFC", candidate.replace("\\", "/"))
    parts = [p for p in normalised.split("/") if p not in ("", ".")]
    if not parts:
        raise SecurityViolation("Archive entry resolves to an empty path.")
    if any(p == ".." for p in parts):
        raise SecurityViolation("Archive entry escapes the archive root.")
    safe = PurePosixPath(*parts)
    if safe.is_absolute():  # pragma: no cover - belt and braces
        raise SecurityViolation("Archive entry uses an absolute path.")
    return safe


def resolve_within(root: Path, *relative: str) -> Path:
    """Join ``relative`` under ``root`` and prove the result stays inside."""
    root_resolved = root.resolve()
    candidate = root_resolved
    for part in relative:
        part = part.replace("\\", "/")
        candidate = candidate / part
    # ``strict=False`` so we can also validate not-yet-created destinations.
    resolved = Path(os.path.normpath(str(candidate)))
    try:
        resolved.relative_to(root_resolved)
    except ValueError as exc:
        raise SecurityViolation("Resolved path escapes the managed storage root.") from exc
    return resolved


def assert_no_symlink(path: Path, stop_at: Path) -> None:
    """Refuse to read/write through a symlink chain inside managed storage."""
    stop = stop_at.resolve()
    current = Path(os.path.normpath(str(path)))
    while True:
        if current.exists() and current.is_symlink():
            raise SecurityViolation("Symlinks are not permitted in managed storage.")
        if current == stop or current.parent == current:
            return
        current = current.parent


def random_storage_name(prefix: str, suffix: str = "") -> str:
    token = os.urandom(16).hex()
    return f"{prefix}{token}{suffix}"


def sha256_file(path: Path, *, chunk: int = 1024 * 1024) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        while True:
            block = handle.read(chunk)
            if not block:
                break
            digest.update(block)
    return digest.hexdigest()


# --------------------------------------------------------------------------- #
# Rate limiting (in-process token bucket; documented as local-mode only)
# --------------------------------------------------------------------------- #


@dataclass
class _Bucket:
    window_start: float
    events: deque[float]


class SlidingWindowLimiter:
    """Simple in-memory sliding-window limiter keyed by client identity.

    Scope: single process, local mode.  Documented as *not* a distributed
    control; a remote deployment must front the API with a real limiter.
    """

    def __init__(self, limit: int, window_seconds: int) -> None:
        self.limit = max(1, limit)
        self.window = max(1, window_seconds)
        self._buckets: dict[str, _Bucket] = {}
        self._lock = threading.Lock()
        self._last_sweep = time.monotonic()

    def check(self, key: str, *, cost: int = 1) -> None:
        now = time.monotonic()
        with self._lock:
            self._sweep(now)
            bucket = self._buckets.get(key)
            if bucket is None or now - bucket.window_start >= self.window:
                bucket = _Bucket(window_start=now, events=deque())
                self._buckets[key] = bucket
            if len(bucket.events) + cost > self.limit:
                retry_after = max(1.0, self.window - (now - bucket.window_start))
                raise RateLimited(
                    "Too many requests for this client.",
                    details={"retry_after_seconds": round(retry_after, 2)},
                )
            for _ in range(cost):
                bucket.events.append(now)

    def _sweep(self, now: float) -> None:
        if now - self._last_sweep < max(5.0, self.window / 2):
            return
        self._last_sweep = now
        cutoff = now - self.window
        stale = [k for k, b in self._buckets.items() if b.window_start < cutoff]
        for key in stale:
            self._buckets.pop(key, None)


class ConcurrencyGate:
    """Bounds the number of simultaneously running analysis jobs."""

    def __init__(self, maximum: int) -> None:
        self.maximum = max(1, maximum)
        self._active = 0
        self._lock = threading.Lock()

    def acquire(self) -> None:
        with self._lock:
            if self._active >= self.maximum:
                raise RateLimited(
                    "Too many analysis jobs are already running.",
                    details={"maximum": self.maximum},
                )
            self._active += 1

    def release(self) -> None:
        with self._lock:
            self._active = max(0, self._active - 1)

    @property
    def active(self) -> int:
        return self._active


def enforce_body_size(content_length: str | None, maximum: int) -> None:
    if content_length is None:
        return
    try:
        length = int(content_length)
    except ValueError:
        raise SecurityViolation("Invalid Content-Length header.") from None
    if length < 0:
        raise SecurityViolation("Invalid Content-Length header.")
    if length > maximum:
        raise PayloadTooLarge(
            "Request body exceeds the configured limit.",
            details={"limit_bytes": maximum, "received_bytes": length},
        )


def clamp_page(size: int | None, *, default: int, maximum: int) -> int:
    if size is None:
        return default
    if size <= 0:
        raise SecurityViolation("Page size must be positive.")
    return min(size, maximum)

