"""TCP sequence-space arithmetic and the reassembly buffer.

Sequence numbers are 32-bit and wrap.  Everything in this module works in
*relative* sequence numbers: distance from the Initial Sequence Number, so the
stream coordinate system is monotonic and comparable.

The reassembly policy is explicit and reproducible:

``first_writer_wins``
    When two segments disagree about the bytes covering the same sequence
    range, the earliest-observed bytes are kept and the disagreement is recorded
    as a :class:`StreamConflict`.  This mirrors what the first receiver would
    have delivered, and is the default.

``last_writer_wins``
    Later bytes overwrite earlier ones; the original bytes are preserved in the
    conflict record so the analyst can still see both variants.

In both cases the conflict is a first-class diagnostic, never silently
resolved.  Gaps are never filled with zeros.
"""

from __future__ import annotations

import bisect
from dataclasses import dataclass, field
from typing import Iterable, Iterator, Sequence

SEQ_MOD = 1 << 32
SEQ_HALF = 1 << 31
ANALYZER_VERSION = "tcp-reassembly/1.1"


def relative_sequence(seq: int, isn: int) -> int:
    """Map a 32-bit sequence number into a monotonically increasing space."""
    return ((seq - isn) & 0xFFFFFFFF)


def seq_lt(a: int, b: int) -> bool:
    return ((b - a) & 0xFFFFFFFF) < SEQ_HALF


@dataclass(slots=True)
class Segment:
    packet_index: int
    timestamp: float
    sequence: int  # absolute 32-bit seq of the first payload byte
    payload: bytes
    flags: int
    window: int
    options: str | None = None

    @property
    def end_sequence(self) -> int:
        return (self.sequence + len(self.payload)) & 0xFFFFFFFF

    @property
    def length(self) -> int:
        return len(self.payload)


@dataclass(slots=True)
class Run:
    """A contiguous run of reconstructed bytes."""

    start: int  # stream offset (relative, 0-based)
    data: bytearray
    contributors: list[tuple[int, int]]  # (start, end) stream offsets

    @property
    def end(self) -> int:
        return self.start + len(self.data)

    @property
    def empty(self) -> bool:
        return not self.data


@dataclass(slots=True)
class Hole:
    start: int
    end: int
    reason: str = "missing_segments"

    @property
    def length(self) -> int:
        return self.end - self.start


@dataclass(slots=True)
class StreamConflict:
    start: int
    end: int
    kept_source_packet: int
    overwritten_packet: int | None
    kept_hex: str
    rejected_hex: str
    resolution: str

    def to_dict(self) -> dict[str, object]:
        return {
            "start_offset": self.start,
            "end_offset": self.end,
            "kept_source_packet": self.kept_source_packet,
            "overwritten_packet": self.overwritten_packet,
            "kept_hex": self.kept_hex,
            "rejected_hex": self.rejected_hex,
            "resolution": self.resolution,
            "length": self.end - self.start,
        }


@dataclass(slots=True)
class DuplicateObservation:
    """A retransmission that carried byte-identical data (expected, benign)."""

    packet_index: int
    original_packet_index: int
    start_offset: int
    end_offset: int

    def to_dict(self) -> dict[str, object]:
        return {
            "packet_index": self.packet_index,
            "original_packet_index": self.original_packet_index,
            "start_offset": self.start_offset,
            "end_offset": self.end_offset,
            "length": self.end_offset - self.start_offset,
        }


@dataclass
class ReassembledStream:
    """The reconstructed one-way byte stream plus everything we know about it.

    ``runs`` cover only bytes actually observed.  ``holes`` describes the gaps
    between them; ``holes[-1]`` may be an *open* end (capture stopped mid-stream).
    """

    direction: str
    local_endpoint: str
    remote_endpoint: str
    isn: int | None
    stream_length: int  # end of the last observed byte, relative
    runs: list[Run]
    holes: list[Hole]
    conflicts: list[StreamConflict] = field(default_factory=list)
    duplicates: list[DuplicateObservation] = field(default_factory=list)
    retransmissions: list[dict[str, object]] = field(default_factory=list)
    out_of_order: list[dict[str, object]] = field(default_factory=list)
    zero_windows: list[dict[str, object]] = field(default_factory=list)
    window_updates: list[dict[str, object]] = field(default_factory=list)
    overlapping: list[dict[str, object]] = field(default_factory=list)
    start_time: float = 0.0
    end_time: float = 0.0
    segment_count: int = 0
    payload_segment_count: int = 0
    byte_count: int = 0
    is_truncated_start: bool = False
    is_truncated_end: bool = False
    diagnostics: dict[str, object] = field(default_factory=dict)

    @property
    def present_bytes(self) -> int:
        return sum(len(r.data) for r in self.runs)

    @property
    def has_gaps(self) -> bool:
        return any(h.reason == "missing_segments" for h in self.holes)

    def coverage(self) -> list[dict[str, int]]:
        return [{"start": r.start, "end": r.end} for r in self.runs]

    def hole_list(self) -> list[dict[str, object]]:
        return [
            {"start": h.start, "end": h.end, "length": h.length, "reason": h.reason}
            for h in self.holes
        ]

    def read(self, offset: int, length: int) -> bytes:
        """Read ``length`` bytes from stream offset ``offset``.

        Bytes inside a hole are **not** invented: the returned buffer is only
        guaranteed valid where :meth:`is_present` is true.  Callers must check
        coverage first (see :meth:`coverage_of`).
        """
        out = bytearray()
        for run in self._runs_intersecting(offset, offset + length):
            lo = max(offset, run.start)
            hi = min(offset + length, run.end)
            out.extend(run.data[lo - run.start : hi - run.start])
        return bytes(out)

    def coverage_of(self, offset: int, length: int) -> int:
        """How many of ``length`` bytes starting at ``offset`` are actually present."""
        present = 0
        for run in self._runs_intersecting(offset, offset + length):
            lo = max(offset, run.start)
            hi = min(offset + length, run.end)
            present += max(0, hi - lo)
        return present

    def is_present(self, offset: int, length: int) -> bool:
        return self.coverage_of(offset, length) == length

    def find_run(self, offset: int) -> Run | None:
        idx = bisect.bisect_right(self._run_starts, offset) - 1
        if idx < 0:
            return None
        run = self.runs[idx]
        if run.start <= offset < run.end:
            return run
        return None

    def _init_index(self) -> None:
        self._run_starts = [r.start for r in self.runs]  # type: ignore[attr-defined]

    def _runs_intersecting(self, start: int, end: int) -> Iterator[Run]:
        if not hasattr(self, "_run_starts"):
            self._init_index()
        if not self.runs:
            return
        idx = max(0, bisect.bisect_right(self._run_starts, start) - 1)  # type: ignore[attr-defined]
        while idx < len(self.runs):
            run = self.runs[idx]
            if run.start >= end:
                break
            if run.end > start:
                yield run
            idx += 1

    def packet_references(self, offset: int, length: int) -> list[dict[str, object]]:
        """Which packets contributed the bytes in ``[offset, offset+length)``.

        This is the byte-to-packet provenance the UI needs to highlight the
        origin of a value, including the case where a range was assembled from
        several segments.
        """
        refs: list[dict[str, object]] = []
        for run in self._runs_intersecting(offset, offset + length):
            for pkt_index, pkt_end in run.contributors:
                pkt_start = pkt_end - self._contributor_length(run, pkt_end)
                lo = max(offset, pkt_start)
                hi = min(offset + length, pkt_end)
                if hi <= lo:
                    continue
                existing = next(
                    (r for r in refs if r["packet_index"] == pkt_index), None
                )
                if existing:
                    existing["start_offset"] = min(existing["start_offset"], lo)  # type: ignore[index]
                    existing["end_offset"] = max(existing["end_offset"], hi)  # type: ignore[index]
                else:
                    refs.append(
                        {
                            "packet_index": pkt_index,
                            "start_offset": lo,
                            "end_offset": hi,
                        }
                    )
        refs.sort(key=lambda r: r["start_offset"])  # type: ignore[arg-type,index]
        return refs

    @staticmethod
    def _contributor_length(run: Run, pkt_end: int) -> int:
        """Reconstruct a contributor's length from the run it lives in.

        Contributors are appended in insertion order and always cover the run
        monotonically, so the length of contributor *i* is the distance to the
        next contributor's end, and the last one runs to the run end.
        """
        for i, (_start, end) in enumerate(run.contributors):
            if end == pkt_end:
                if i + 1 < len(run.contributors):
                    return run.contributors[i + 1][1] - end
                return run.end - end
        return 0  # pragma: no cover

    def contiguous_bytes(self, start: int = 0, end: int | None = None) -> Iterator[tuple[int, bytes]]:
        """Yield only present ``(offset, bytes)`` chunks, skipping holes."""
        for run in self.runs:
            lo = max(start, run.start)
            if end is not None and lo >= end:
                break
            hi = run.end if end is None else min(end, run.end)
            if hi > lo:
                yield lo, bytes(run.data[lo - run.start : hi - run.start])


@dataclass(slots=True)
class DirectionResult:
    stream: ReassembledStream
    events: list[dict[str, object]] = field(default_factory=list)


def reassemble(
    *,
    direction: str,
    local_endpoint: str,
    remote_endpoint: str,
    segments: Sequence[Segment],
    isn: int | None,
    expected_start: int | None = None,
    conflict_policy: str = "first_writer_wins",
    assume_open_end: bool = True,
) -> ReassembledStream:
    """Rebuild one direction of a TCP conversation.

    ``segments`` must be in *capture order*, not sequence order; the algorithm
    is order-insensitive with respect to the final byte content (given the
    stated conflict policy) while still reporting ordering anomalies.
    """
    if conflict_policy not in ("first_writer_wins", "last_writer_wins"):
        raise ValueError(f"unknown conflict policy {conflict_policy!r}")

    ordered = sorted(segments, key=lambda s: (s.packet_index,))
    diagnostics: dict[str, object] = {"conflict_policy": conflict_policy}

    # --- pick the base -------------------------------------------------- #
    if isn is not None:
        base_abs = (isn + 1) & 0xFFFFFFFF
    elif ordered:
        base_abs = ordered[0].sequence
        diagnostics["inferred_isn"] = True
    else:
        base_abs = 0
        isn = None
    if expected_start is not None and isn is not None:
        base_abs = expected_start

    def to_stream(seq: int) -> int:
        return ((seq - base_abs) & 0xFFFFFFFF)

    stream = ReassembledStream(
        direction=direction,
        local_endpoint=local_endpoint,
        remote_endpoint=remote_endpoint,
        isn=isn,
        stream_length=0,
        runs=[],
        holes=[],
    )

    # --- classify each segment ------------------------------------------ #
    max_end = 0
    highest_contiguous = 0  # stream offset just past an unbroken prefix
    first_pass = True
    for seg in ordered:
        stream.segment_count += 1
        if seg.payload_length if False else len(seg.payload) == 0:
            continue
        start = to_stream(seg.sequence)
        end = start + len(seg.payload)
        max_end = max(max_end, end)
        stream.byte_count += len(seg.payload)
        if end <= highest_contiguous and start < highest_contiguous:
            if start + len(seg.payload) <= highest_contiguous:
                # Pure retransmission of already-received bytes.
                if _bytes_present_match(stream, start, seg.payload):
                    original = _origin_packet(stream, start)
                    stream.duplicates.append(
                        DuplicateObservation(
                            packet_index=seg.packet_index,
                            original_packet_index=original if original is not None else -1,
                            start_offset=start,
                            end_offset=end,
                        )
                    )
                else:
                    conflicts = _apply_segment(stream, start, seg, conflict_policy)
                    stream.conflicts.extend(conflicts)
                stream.retransmissions.append(
                    {
                        "packet_index": seg.packet_index,
                        "start_offset": start,
                        "end_offset": end,
                        "length": len(seg.payload),
                        "kind": "exact_duplicate"
                        if all(c.resolution == "identical" for c in stream.conflicts[-1:])
                        else "conflicting",
                    }
                )
                continue
            stream.retransmissions.append(
                {
                    "packet_index": seg.packet_index,
                    "start_offset": start,
                    "end_offset": end,
                    "length": len(seg.payload),
                    "kind": "partial_overlap",
                }
            )
            stream.overlapping.append(
                {
                    "packet_index": seg.packet_index,
                    "start_offset": start,
                    "end_offset": end,
                    "overlap_length": highest_contiguous - start,
                }
            )
        else:
            # First time we see this region (or it extends the frontier).
            if first_pass or start > highest_contiguous:
                stream.overlapping.append(
                    {
                        "packet_index": seg.packet_index,
                        "start_offset": start,
                        "end_offset": end,
                        "gap_before": max(0, start - highest_contiguous),
                    }
                ) if first_pass else None

        conflicts = _apply_segment(stream, start, seg, conflict_policy)
        if conflicts and not any(c.resolution == "identical" for c in conflicts):
            pass
        stream.conflicts.extend([c for c in conflicts if c.resolution != "identical"])

        if end > highest_contiguous:
            highest_contiguous = end
        first_pass = False

    stream.runs.sort(key=lambda r: r.start)
    stream.stream_length = max_end
    _build_holes(stream, isn=isn, has_syn=any(s.flags & 0x02 for s in ordered), assume_open_end=assume_open_end)
    _detect_ordering(stream, ordered, to_stream)
    stream.start_time = ordered[0].timestamp if ordered else 0.0
    stream.end_time = ordered[-1].timestamp if ordered else 0.0
    stream.payload_segment_count = sum(1 for s in ordered if len(s.payload))
    stream.diagnostics = diagnostics

    if isn is None:
        stream.diagnostics["isn_source"] = "inferred_from_first_payload"
        stream.is_truncated_start = True
    return stream


def _bytes_present_match(stream: ReassembledStream, start: int, payload: bytes) -> bool:
    if not stream.runs:
        return False
    got = stream.read(start, len(payload))
    return len(got) == len(payload) and got == payload


def _origin_packet(stream: ReassembledStream, offset: int) -> int | None:
    refs = stream.packet_references(offset, 1)
    return refs[0]["packet_index"] if refs else None  # type: ignore[return-value]


def _apply_segment(
    stream: ReassembledStream, start: int, seg: Segment, policy: str
) -> list[StreamConflict]:
    """Splice ``seg`` into the run list, recording byte conflicts."""
    payload = seg.payload
    if not payload:
        return []
    end = start + len(payload)
    # Runs overlapping [start, end)
    overlapping = [
        r for r in stream.runs if r.start < end and r.end > start
    ]
    if not overlapping:
        _insert_run(stream, start, bytearray(payload), seg.packet_index)
        return []

    conflicts: list[StreamConflict] = []
    merged = bytearray()
    merged_start = start
    merged_end = end
    contributors: list[tuple[int, int]] = [(start, end)]

    # Build a base covering [min start, max end) by walking overlapping runs.
    lo = min([r.start for r in overlapping] + [start])
    hi = max([r.end for r in overlapping] + [end])
    base = bytearray(hi - lo)
    for r in overlapping:
        base[r.start - lo : r.end - lo] = r.data
    contributed_from: dict[int, int] = {}
    for r in overlapping:
        for c_start, c_end in r.contributors:
            contributed_from[c_end] = c_start
    contributors = list(
        sorted(
            ((c_start, c_end) for c_end, c_start in contributed_from.items()),
            key=lambda p: p[0],
        )
    )

    # Apply the new bytes over the overlap region.
    for i, byte in enumerate(payload):
        pos = start + i
        if lo <= pos < hi:
            existing = base[pos - lo]
            if existing != byte:
                seg_start = start + i
                seg_end = seg_start + 1
                # extend the conflicting run while bytes differ
                while seg_end < end and base[seg_end - lo] != payload[seg_end - start]:
                    seg_end += 1
                kept = bytes(base[seg_start - lo : seg_end - lo])
                rejected = payload[seg_start - start : seg_end - start]
                resolution = "first_writer_wins" if policy == "first_writer_wins" else "last_writer_wins"
                kept_source = _packet_for_offset(stream, seg_start)
                if policy == "first_writer_wins":
                    kept, rejected = kept, rejected
                else:
                    kept, rejected = rejected, kept
                conflicts.append(
                    StreamConflict(
                        start=seg_start,
                        end=seg_end,
                        kept_source_packet=kept_source if kept_source is not None else -1,
                        overwritten_packet=seg.packet_index,
                        kept_hex=kept.hex(),
                        rejected_hex=rejected.hex(),
                        resolution=resolution,
                    )
                )
                if policy == "last_writer_wins":
                    base[seg_start - lo : seg_end - lo] = payload[seg_start - start : seg_end - start]
        else:
            base.extend(b"\x00" * (pos - lo - len(base) + 1))
            base[pos - lo] = byte
    merged = base
    contributors.append((start, end))
    contributors.sort(key=lambda p: p[0])

    # Drop the merged runs and insert the combined one.
    stream.runs = [r for r in stream.runs if not (r.start < hi and r.end > lo)]
    _insert_run(stream, lo, merged, None, extra_contributors=contributors)
    stream.runs.sort(key=lambda r: r.start)
    return conflicts


def _packet_for_offset(stream: ReassembledStream, offset: int) -> int | None:
    for run in stream.runs:
        if run.start <= offset < run.end:
            for c_start, c_end in run.contributors:
                if c_start <= offset < c_end:
                    return _packet_index_for(stream, run, c_start)
    return None


_PACKET_INDEX: dict[int, int] = {}


def _packet_index_for(stream: ReassembledStream, run: Run, contributor_start: int) -> int | None:
    # Contributors are stored as (start,end); the originating packet index is
    # recovered from the parallel ``run.packet_map`` when present.
    mapping = getattr(run, "packet_map", None)
    if mapping is not None:
        return mapping.get(contributor_start)
    return None


def _insert_run(
    stream: ReassembledStream,
    start: int,
    data: bytearray,
    packet_index: int | None,
    *,
    extra_contributors: list[tuple[int, int]] | None = None,
) -> None:
    if not data:
        return
    run = Run(start=start, data=data, contributors=[])
    if extra_contributors:
        run.contributors = list(extra_contributors)
    else:
        run.contributors = [(start, start + len(data))]
    run.packet_map = {start: packet_index}  # type: ignore[attr-defined]
    for c_start, _c_end in extra_contributors or []:
        run.packet_map.setdefault(c_start, packet_index)  # type: ignore[attr-defined]
    stream.runs.append(run)
    stream.runs.sort(key=lambda r: r.start)


def _build_holes(
    stream: ReassembledStream, *, isn: int | None, has_syn: bool, assume_open_end: bool
) -> None:
    holes: list[Hole] = []
    if not stream.runs:
        stream.holes = holes
        stream.is_truncated_start = True
        stream.is_truncated_end = True
        return

    cursor = 0
    for run in stream.runs:
        if run.start > cursor:
            holes.append(Hole(start=cursor, end=run.start, reason="missing_segments"))
        cursor = max(cursor, run.end)
    # A SYN tells us byte 0 must be the first byte of the stream; without it we
    # cannot claim we captured the beginning.
    if has_syn and isn is not None and stream.runs[0].start > 0:
        stream.is_truncated_start = True
    if assume_open_end and cursor < stream.stream_length:
        holes.append(Hole(start=cursor, end=stream.stream_length, reason="capture_ended"))
        stream.is_truncated_end = True
    stream.holes = holes


def _detect_ordering(
    stream: ReassembledStream, segments: Iterable[Segment], to_stream
) -> None:
    """Flag segments that arrived before data we had already received."""
    seen_max = 0
    for seg in segments:
        if not seg.payload:
            continue
        start = to_stream(seg.sequence)
        end = start + len(seg.payload)
        if start < seen_max and end > seen_max:
            stream.out_of_order.append(
                {
                    "packet_index": seg.packet_index,
                    "start_offset": start,
                    "end_offset": end,
                    "already_seen_up_to": seen_max,
                }
            )
        seen_max = max(seen_max, end)


def summarise_timeline(
    segments: Sequence[Segment],
    *,
    to_stream,
    limit: int = 5000,
) -> list[dict[str, object]]:
    """Per-packet view used by the UI state diagram."""
    events: list[dict[str, object]] = []
    for seg in segments[:limit]:
        entry: dict[str, object] = {
            "packet_index": seg.packet_index,
            "timestamp": seg.timestamp,
            "flags": seg.flags,
            "window": seg.window,
            "payload_length": len(seg.payload),
            "options": seg.options,
        }
        if seg.payload:
            start = to_stream(seg.sequence)
            entry["start_offset"] = start
            entry["end_offset"] = start + len(seg.payload)
        events.append(entry)
    return events

