"""Shared application context and FastAPI dependencies."""

from __future__ import annotations

from functools import lru_cache
from typing import Annotated

from fastapi import Depends, Request
from sqlalchemy import Engine
from sqlalchemy.orm import Session, sessionmaker

from ..core.config import Settings
from ..core.errors import NotFound, ValidationFailed
from ..core.security import ConcurrencyGate, SlidingWindowLimiter
from ..models import Capture, Project
from ..services.project_service import AuditLog, JobService, ProjectService
from ..services.storage import ProjectStorage


class AppContext:
    """Long-lived objects bound to the running application."""

    def __init__(
        self,
        *,
        settings: Settings,
        engine: Engine,
        limiter: SlidingWindowLimiter,
        job_gate: ConcurrencyGate,
    ) -> None:
        self.settings = settings
        self.engine = engine
        self.limiter = limiter
        self.job_gate = job_gate
        self.session_factory = sessionmaker(
            bind=engine, autoflush=False, expire_on_commit=False, future=True
        )
        self.storage = ProjectStorage(settings.storage_dir)  # type: ignore[arg-type]

    def session(self) -> Session:
        return self.session_factory()


def get_context(request: Request) -> AppContext:
    return request.app.state.context  # type: ignore[no-any-return]


def get_session(request: Request) -> Session:
    """Request-scoped database session."""
    context = get_context(request)
    session = context.session()
    try:
        yield session
    finally:
        session.close()


def get_storage(request: Request) -> ProjectStorage:
    return get_context(request).storage


def get_limits(request: Request):
    return get_context(request).settings.limits


def get_settings_dep(request: Request) -> Settings:
    return get_context(request).settings


SessionDep = Annotated[Session, Depends(get_session)]
ContextDep = Annotated[AppContext, Depends(get_context)]
StorageDep = Annotated[ProjectStorage, Depends(get_storage)]
LimitsDep = Annotated[object, Depends(get_limits)]


# --------------------------------------------------------------------------- #
# Object-level authorisation helpers
# --------------------------------------------------------------------------- #


def load_project(session: Session, project_id: str) -> Project:
    """Load a project, validating the identifier shape first.

    Every endpoint that accepts an identifier resolves it through here, so a
    caller cannot reach an object by guessing an id that belongs elsewhere.
    """
    _validate_id(project_id, "project_id")
    project = session.get(Project, project_id)
    if project is None:
        raise NotFound(f"Project {project_id!r} does not exist.")
    return project


def load_capture(session: Session, capture_id: str) -> Capture:
    _validate_id(capture_id, "capture_id")
    capture = session.get(Capture, capture_id)
    if capture is None:
        raise NotFound(f"Capture {capture_id!r} does not exist.")
    return capture


def require_project_of_capture(session: Session, capture_id: str, project_id: str | None) -> Capture:
    capture = load_capture(session, capture_id)
    if project_id is not None and capture.project_id != project_id:
        raise NotFound(
            f"Capture {capture_id!r} does not belong to project {project_id!r}.",
            details={"capture_project_id": capture.project_id},
        )
    return capture


def _validate_id(value: str, field: str) -> None:
    if not isinstance(value, str) or not value:
        raise ValidationFailed(f"{field} must be a non-empty string.")
    if len(value) > 64 or not all(ch.isalnum() for ch in value):
        raise ValidationFailed(f"{field} contains characters that are not valid in an identifier.")


def audit(session: Session) -> AuditLog:
    return AuditLog(session)


def jobs(session: Session, limits) -> JobService:
    return JobService(session, limits)


def project_service(session: Session, storage: ProjectStorage, limits) -> ProjectService:
    return ProjectService(session, storage, limits)


ProjectServiceDep = Annotated[ProjectService, Depends(project_service)]
StorageServiceDep = Annotated[JobService, Depends(jobs)]


@lru_cache(maxsize=1)
def _noop() -> None:  # pragma: no cover
    return None

"""Project lifecycle endpoints."""

from __future__ import annotations

from typing import Annotated

from fastapi import APIRouter, Depends, Response, status
from sqlalchemy import func, select

from ...core.errors import NotFound
from ...models import (
    Capture,
    Hypothesis,
    Interpretation,
    Message,
    Packet,
    Stream,
    TcpSession,
    ValidationResult,
    ValidationRun,
)
from ...schemas import (
    ExportProjectRequest,
    HypothesisOut,
    InterpretationOut,
    ProjectCreate,
    ProjectMetrics,
    ProjectOut,
    ProjectSummaryOut,
    ValidationRunOut,
)
from ..context import SessionDep, StorageDep, load_project

router = APIRouter()


@router.get("/projects", response_model=list[ProjectSummaryOut])
def list_projects(session: SessionDep, storage: StorageDep) -> list[ProjectSummaryOut]:
    from ..context import project_service
    from ...core.config import get_settings

    service = project_service(session, storage, get_settings().limits)
    return [
        ProjectSummaryOut(**summary.__dict__) for summary in service.list()
    ]


@router.post("/projects", response_model=ProjectOut, status_code=status.HTTP_201_CREATED)
def create_project(payload: ProjectCreate, session: SessionDep, storage: StorageDep) -> Project:
    from ..context import project_service
    from ...core.config import get_settings

    service = project_service(session, storage, get_settings().limits)
    project = service.create(
        name=payload.name, description=payload.description, settings=payload.settings
    )
    return project


@router.get("/projects/{project_id}", response_model=ProjectOut)
def get_project(project_id: str, session: SessionDep) -> Project:
    return load_project(session, project_id)


@router.delete("/projects/{project_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_project(project_id: str, session: SessionDep, storage: StorageDep) -> Response:
    from ..context import project_service
    from ...core.config import get_settings

    service = project_service(session, storage, get_settings().limits)
    service.delete(project_id)
    return Response(status_code=status.HTTP_204_NO_CONTENT)


@router.get("/projects/{project_id}/metrics", response_model=ProjectMetrics)
def project_metrics(project_id: str, session: SessionDep) -> ProjectMetrics:
    """Live counters.

    Every number here is computed from the current project state.  Nothing is
    cached, seeded or estimated, so an empty project honestly reports zeros.
    """
    project = load_project(session, project_id)
    captures = session.execute(
        select(Capture).where(Capture.project_id == project_id)
    ).scalars().all()
    capture_ids = [c.id for c in captures]

    def count(model, *filters):
        if not capture_ids:
            return 0
        return int(
            session.scalar(
                select(func.count()).select_from(model).where(*filters)
            )
            or 0
        )

    packets = count(Packet, Packet.capture_id.in_(capture_ids)) if capture_ids else 0
    sessions = count(TcpSession, TcpSession.project_id == project_id)
    streams = (
        int(
            session.scalar(
                select(func.count(Stream.id))
                .join(TcpSession, TcpSession.id == Stream.session_id)
                .where(TcpSession.project_id == project_id)
            )
            or 0
        )
    )
    messages = (
        int(
            session.scalar(
                select(func.count(Message.id))
                .join(Stream, Stream.id == Message.stream_id)
                .join(TcpSession, TcpSession.id == Stream.session_id)
                .where(TcpSession.project_id == project_id)
            )
            or 0
        )
    )
    hypotheses = count(Hypothesis, Hypothesis.project_id == project_id)
    interpretations = count(Interpretation, Interpretation.project_id == project_id)
    runs = count(ValidationRun, ValidationRun.project_id == project_id)
    counterexamples = (
        int(
            session.scalar(
                select(func.count(ValidationResult.id))
                .join(ValidationRun, ValidationRun.id == ValidationResult.validation_run_id)
                .where(
                    ValidationRun.project_id == project_id,
                    ValidationResult.outcome == "failed",
                )
            )
            or 0
        )
    )
    problem_sessions = (
        int(
            session.scalar(
                select(func.count(TcpSession.id)).where(
                    TcpSession.project_id == project_id,
                    TcpSession.completeness_status != "complete",
                )
            )
            or 0
        )
    )
    versions: dict[str, str] = {}
    for session_row in session.execute(
        select(TcpSession.analyzer_version).where(TcpSession.project_id == project_id).distinct()
    ).scalars():
        if session_row:
            versions.setdefault("tcp_reassembly", session_row)
    for run_version in session.execute(
        select(ValidationRun.analyzer_version)
        .where(ValidationRun.project_id == project_id)
        .distinct()
    ).scalars():
        if run_version:
            versions.setdefault("validation", run_version)

    return ProjectMetrics(
        project_id=project_id,
        captures=len(captures),
        packets=packets,
        tcp_sessions=sessions,
        streams=streams,
        messages=messages,
        hypotheses=hypotheses,
        interpretations=interpretations,
        validation_runs=runs,
        counterexamples=counterexamples,
        sessions_with_reconstruction_problems=problem_sessions,
        bytes_stored=sum(c.file_size for c in captures),
        analyst_versions=versions,
    )


@router.get("/projects/{project_id}/hypotheses", response_model=list[HypothesisOut])
def list_hypotheses(project_id: str, session: SessionDep) -> list[Hypothesis]:
    load_project(session, project_id)
    return list(
        session.execute(
            select(Hypothesis)
            .where(Hypothesis.project_id == project_id)
            .order_by(Hypothesis.updated_at.desc())
        )
        .scalars()
        .all()
    )


@router.get("/projects/{project_id}/interpretations", response_model=list[InterpretationOut])
def list_interpretations(project_id: str, session: SessionDep) -> list[Interpretation]:
    load_project(session, project_id)
    return list(
        session.execute(
            select(Interpretation)
            .where(Interpretation.project_id == project_id)
            .order_by(Interpretation.created_at.desc())
        )
        .scalars()
