_ = Annotated

"""Structural diff between two captures.

Comparing by packet number is useless once the behaviour changes, so sessions
are matched on a *feature vector* (endpoints, direction, stream sizes, timing
shape and message-length profile) and then compared at the message level.

A difference from the baseline is reported as a difference, not as an anomaly:
"the capture changed" and "the change is suspicious" are separate claims.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Sequence

DIFF_VERSION = "capture-diff/1.1"


@dataclass
class SessionSignature:
    endpoint_a: str
    endpoint_b: str
    packets: int
    bytes_a_to_b: int
    bytes_b_to_a: int
    duration: float
    message_lengths_a_to_b: tuple[int, ...]
    message_lengths_b_to_a: tuple[int, ...]

    def to_dict(self) -> dict[str, Any]:
        return {
            "endpoint_a": self.endpoint_a,
            "endpoint_b": self.endpoint_b,
            "packets": self.packets,
            "bytes_a_to_b": self.bytes_a_to_b,
            "bytes_b_to_a": self.bytes_b_to_a,
            "duration": round(self.duration, 6),
            "message_count_a_to_b": len(self.message_lengths_a_to_b),
            "message_count_b_to_a": len(self.message_lengths_b_to_a),
            "distinct_lengths_a_to_b": sorted(set(self.message_lengths_a_to_b)),
            "distinct_lengths_b_to_a": sorted(set(self.message_lengths_b_to_a)),
        }


@dataclass
class SessionMatch:
    base: SessionSignature | None
    compare: SessionSignature | None
    score: float
    reasons: list[str] = field(default_factory=list)
    base_id: str | None = None
    compare_id: str | None = None

    @property
    def status(self) -> str:
        if self.base is None:
            return "added"
        if self.compare is None:
            return "removed"
        return "changed" if self.score < 0.999 else "unchanged"


def match_sessions(
    base: Sequence[tuple[str, SessionSignature]],
    compare: Sequence[tuple[str, SessionSignature]],
    *,
    threshold: float = 0.55,
) -> list[SessionMatch]:
    """Greedy best-match pairing on a normalised similarity score."""
    scored: list[tuple[float, int, int]] = []
    for i, (_, a) in enumerate(base):
        for j, (_, b) in enumerate(compare):
            score = similarity(a, b)
            if score >= threshold:
                scored.append((score, i, j))
    scored.sort(key=lambda t: (-t[0], t[1], t[2]))

    used_a: set[int] = set()
    used_b: set[int] = set()
    matches: list[SessionMatch] = []
    for score, i, j in scored:
        if i in used_a or j in used_b:
            continue
        used_a.add(i)
        used_b.add(j)
        a_id, a = base[i]
        b_id, b = compare[j]
        matches.append(
            SessionMatch(
                base=a,
                compare=b,
                score=round(score, 4),
                reasons=_match_reasons(a, b),
                base_id=a_id,
                compare_id=b_id,
            )
        )
    for i, (session_id, signature) in enumerate(base):
        if i not in used_a:
            matches.append(SessionMatch(base=signature, compare=None, score=0.0, base_id=session_id))
    for j, (session_id, signature) in enumerate(compare):
        if j not in used_b:
            matches.append(
                SessionMatch(base=None, compare=signature, score=0.0, compare_id=session_id)
            )
    matches.sort(key=lambda m: (m.status, m.compare_id or m.base_id or ""))
    return matches


def similarity(a: SessionSignature, b: SessionSignature) -> float:
    """Weighted similarity in 0..1.

    Endpoints dominate because they are the only truly stable identity; the
    other terms are shape features that survive packet renumbering.
    """
    if a.endpoint_a == b.endpoint_a and a.endpoint_b == b.endpoint_b:
        endpoint_score = 1.0
    elif {a.endpoint_a, a.endpoint_b} == {b.endpoint_a, b.endpoint_b}:
        endpoint_score = 0.95  # roles swapped
    else:
        endpoint_score = 0.0
    size_score = _ratio(a.bytes_a_to_b + a.bytes_b_to_a, b.bytes_a_to_b + b.bytes_b_to_a)
    shape_score = _length_profile_similarity(
        a.message_lengths_a_to_b + a.message_lengths_b_to_a,
        b.message_lengths_a_to_b + b.message_lengths_b_to_a,
    )
    packet_score = _ratio(a.packets, b.packets)
    return round(
        0.45 * endpoint_score + 0.2 * size_score + 0.25 * shape_score + 0.1 * packet_score, 4
    )


def _ratio(a: int, b: int) -> float:
    if a == b:
        return 1.0
    if a == 0 or b == 0:
        return 0.0
    return round(min(a, b) / max(a, b), 4)


def _length_profile_similarity(a: Sequence[int], b: Sequence[int]) -> float:
    if not a and not b:
        return 1.0
    if not a or not b:
        return 0.0
    common = len(set(a) & set(b))
    return round(2 * common / (len(set(a)) + len(set(b))), 4)


def _match_reasons(a: SessionSignature, b: SessionSignature) -> list[str]:
    reasons: list[str] = []
    if a.endpoint_a == b.endpoint_a and a.endpoint_b == b.endpoint_b:
        reasons.append("endpoints match exactly")
    elif {a.endpoint_a, a.endpoint_b} == {b.endpoint_a, b.endpoint_b}:
        reasons.append("same endpoint pair with client/server roles swapped")
    if a.bytes_a_to_b != b.bytes_a_to_b:
        reasons.append(f"client->server bytes {a.bytes_a_to_b} vs {b.bytes_b_to_a}")
    if a.bytes_b_to_a != b.bytes_b_to_a:
        reasons.append(f"server->client bytes {a.bytes_b_to_a} vs {b.bytes_b_to_a}")
    la = set(a.message_lengths_a_to_b + a.message_lengths_b_to_a)
    lb = set(b.message_lengths_a_to_b + b.message_lengths_b_to_a)
    if la != lb:
        reasons.append(f"message length sets differ: only in base {sorted(la - lb)}, only in compare {sorted(lb - la)}")
    return reasons


@dataclass
class ByteDelta:
    base_offset: int
    compare_offset: int
    base_hex: str
    compare_hex: str
    changed_offsets: list[int]

    def to_dict(self) -> dict[str, Any]:
        return {
            "base_offset": self.base_offset,
            "compare_offset": self.compare_offset,
            "base_hex": self.base_hex,
            "compare_hex": self.compare_hex,
            "changed_offsets": self.changed_offsets,
            "changed_count": len(self.changed_offsets),
        }


def diff_bytes(base: bytes, compare: bytes, *, max_bytes: int) -> ByteDelta:
    limit = min(len(base), len(compare), max_bytes)
    changed = [i for i in range(limit) if base[i] != compare[i]]
    return ByteDelta(
        base_offset=0,
        compare_offset=0,
        base_hex=base[:max_bytes].hex(),
        compare_hex=compare[:max_bytes].hex(),
        changed_offsets=changed[:4096],
    )


def endpoint_delta(
    base_endpoints: set[str], compare_endpoints: set[str]
) -> dict[str, list[str]]:
    return {
        "added": sorted(compare_endpoints - base_endpoints),
        "removed": sorted(base_endpoints - compare_endpoints),
        "common": sorted(base_endpoints & compare_endpoints),
    }


def heatmap(
    base: Sequence[tuple[str, SessionSignature]],
    compare: Sequence[tuple[str, SessionSignature]],
) -> list[dict[str, Any]]:
    """Flatten session matches into a UI-ready heat map."""
    out: list[dict[str, Any]] = []
    for match in match_sessions(base, compare):
        row: dict[str, Any] = {
            "status": match.status,
            "similarity": match.score,
            "base_session_id": match.base_id,
            "compare_session_id": match.compare_id,
            "reasons": match.reasons,
            "endpoints": (
                match.compare.endpoint_a if match.compare else match.base.endpoint_a  # type: ignore[union-attr]
            ),
        }
        if match.base and match.compare:
            row["byte_delta"] = (
                (match.compare.bytes_a_to_b + match.compare.bytes_b_to_a)
                - (match.base.bytes_a_to_b + match.base.bytes_b_to_a)
            )
            row["packet_delta"] = match.compare.packets - match.base.packets
            row["message_type_changes"] = {
                "only_in_base": sorted(
                    set(match.base.message_lengths_a_to_b)
                    - set(match.compare.message_lengths_a_to_b)
                ),
                "only_in_compare": sorted(
                    set(match.compare.message_lengths_a_to_b)
                    - set(match.base.message_lengths_a_to_b)
                ),
            }
        out.append(row)
    return out


def format_report(matches: list[dict[str, Any]]) -> str:
    lines = ["Capture comparison heat map", "=" * 26]
    for row in matches:
        lines.append(
            f"[{row['status'].upper():9s}] similarity={row['similarity']:.2f} "
            f"{row['endpoints']}"
        )
        for reason in row["reasons"]:
            lines.append(f"    - {reason}")
    lines.append("")
    lines.append(
        "A difference from the baseline is not, by itself, an indication of "
        "anything suspicious."
    )
    return "\n".join(lines)

"""Network interaction graph and centrality metrics."""

from __future__ import annotations

from collections import defaultdict
from dataclasses import dataclass, field
from typing import Any, Iterable

GRAPH_VERSION = "network-graph/1.1"
MAX_NODES = 2000


@dataclass
class Node:
    id: str
    kind: str  # "ip" | "endpoint"
    label: str
    bytes_in: int = 0
    bytes_out: int = 0
    connections: int = 0
    peers: set[str] = field(default_factory=set)
    degree: int = 0
    degree_centrality: float = 0.0
    betweenness: float | None = None
    protocols: set[str] = field(default_factory=set)
    sessions: list[str] = field(default_factory=list)

    def to_dict(self) -> dict[str, Any]:
        return {
            "id": self.id,
            "kind": self.kind,
            "label": self.label,
            "bytes_in": self.bytes_in,
            "bytes_out": self.bytes_out,
            "bytes_total": self.bytes_in + self.bytes_out,
            "connections": self.connections,
            "unique_peers": len(self.peers),
            "degree": self.degree,
            "degree_centrality": round(self.degree_centrality, 6),
            "betweenness": (
                round(self.betweenness, 6) if self.betweenness is not None else None
            ),
            "protocols": sorted(self.protocols),
            "session_ids": self.sessions[:64],
        }


@dataclass
class Edge:
    source: str
    target: str
    bytes_a_to_b: int
    bytes_b_to_a: int
    packets: int
    sessions: list[str] = field(default_factory=list)
    protocols: set[str] = field(default_factory=set)
    confirmed: bool = True

    @property
    def total_bytes(self) -> int:
        return self.bytes_a_to_b + self.bytes_b_to_a

    def to_dict(self) -> dict[str, Any]:
        return {
            "source": self.source,
            "target": self.target,
            "bytes_a_to_b": self.bytes_a_to_b,
            "bytes_b_to_a": self.bytes_b_to_a,
            "bytes_total": self.total_bytes,
            "packets": self.packets,
            "session_ids": self.sessions[:64],
            "protocols": sorted(self.protocols),
            "link_status": "confirmed" if self.confirmed else "assumed",
        }


@dataclass
class Graph:
    nodes: dict[str, Node]
    edges: list[Edge]
    analyzer_version: str = GRAPH_VERSION
    warnings: list[str] = field(default_factory=list)

    def to_dict(self) -> dict[str, Any]:
        return {
            "analyzer_version": self.analyzer_version,
            "node_count": len(self.nodes),
            "edge_count": len(self.edges),
            "nodes": [n.to_dict() for n in sorted(self.nodes.values(), key=lambda n: -n.bytes_in - n.bytes_out)],
            "edges": [e.to_dict() for e in self.edges],
            "warnings": self.warnings,
            "interpretation_note": (
                "Degree and betweenness centrality describe how connected a node is "
                "within this capture. A high-centrality node is a candidate for "
                "further investigation, not a C2 server, and centrality alone says "
                "nothing about intent."
            ),
        }


def build_graph(
    sessions: Iterable[Any],
    *,
    node_kind: str = "ip",
    min_bytes: int = 0,
    protocol_filter: str | None = None,
    compute_betweenness: bool = True,
    max_betweenness_nodes: int = 300,
) -> Graph:
    """Build an interaction graph from analysed sessions.

    ``sessions`` are ORM :class:`TcpSession` rows (optionally with their
    streams).  Edge width reflects real observed bytes; there is no synthetic
    traffic.
    """
    nodes: dict[str, Node] = {}
    edges: dict[tuple[str, str], Edge] = {}
    warnings: list[str] = []

    for session in sessions:
        summary = (session.diagnostics or {}).get("summary", {})
        endpoint_a = session.endpoint_a
        endpoint_b = session.endpoint_b
        streams = getattr(session, "streams", []) or []
        protocol = "unknown"
        for stream in streams:
            if stream.protocol_label and stream.protocol_label != "unknown_binary":
                protocol = stream.protocol_label
                break
        if protocol_filter and protocol != protocol_filter:
            continue

        a_ip, a_port = _split(endpoint_a)
        b_ip, b_port = _split(endpoint_b)
        if node_kind == "endpoint":
            source, target = endpoint_a, endpoint_b
        else:
            source, target = a_ip, b_ip
        for identifier in (source, target):
            if identifier not in nodes:
                nodes[identifier] = Node(id=identifier, kind=node_kind, label=identifier)

        key = tuple(sorted((source, target)))
        edge = edges.get(key)
        if edge is None:
            edge = Edge(source=key[0], target=key[1], bytes_a_to_b=0, bytes_b_to_a=0, packets=0)
            edges[key] = edge
        forward = source == endpoint_a
        a_to_b = int(summary.get("bytes_a_to_b", 0) or 0)
        b_to_a = int(summary.get("bytes_b_to_a", 0) or 0)
        if forward:
            edge.bytes_a_to_b += a_to_b
            edge.bytes_b_to_a += b_to_a
        else:
            edge.bytes_a_to_b += b_to_a
            edge.bytes_b_to_a += a_to_b
        edge.packets += int(summary.get("packet_count", 0) or 0)
        edge.sessions.append(session.id)
        edge.protocols.add(protocol)
        edge.confirmed = edge.confirmed and session.role_confidence == "syn_observed"

        nodes[source].bytes_out += a_to_b if forward else b_to_a
        nodes[source].bytes_in += b_to_a if forward else a_to_b
        nodes[target].bytes_in += a_to_b if forward else b_to_a
        nodes[target].bytes_out += b_to_a if forward else a_to_b
        nodes[source].peers.add(target)
        nodes[target].peers.add(source)
        nodes[source].sessions.append(session.id)
        nodes[target].sessions.append(session.id)
        nodes[source].protocols.add(protocol)
        nodes[target].protocols.add(protocol)

    kept_edges = [e for e in edges.values() if e.total_bytes >= min_bytes]
    kept_nodes = {e.source for e in kept_edges} | {e.target for e in kept_edges}
    filtered_nodes = {k: v for k, v in nodes.items() if k in kept_nodes}
    if len(filtered_nodes) > MAX_NODES:
        warnings.append(
            f"The graph has {len(filtered_nodes)} nodes, above the {MAX_NODES} display "
            "limit. Raise the traffic filter to narrow it."
        )
        ranked = sorted(
            filtered_nodes.items(), key=lambda kv: -(kv[1].bytes_in + kv[1].bytes_out)
        )[:MAX_NODES]
        filtered_nodes = dict(ranked)
        warnings.append(
            f"Displaying the {MAX_NODES} highest-traffic nodes; centrality is "
            "computed on the full filtered graph, not on this truncated view."
        )

    for node in filtered_nodes.values():
        node.degree = len(node.peers)
    n = len(filtered_nodes)
    if n > 1:
        for node in filtered_nodes.values():
            node.degree_centrality = node.degree / (n - 1)

    graph = Graph(nodes=filtered_nodes, edges=kept_edges, warnings=warnings)
    if compute_betweenness:
        if n > max_betweenness_nodes:
            graph.warnings.append(
                f"Betweenness centrality was not computed: {n} nodes exceed the "
                f"{max_betweenness_nodes}-node budget. Degree centrality is still "
                "available."
            )
        else:
            _betweenness(graph)
    return graph


def _split(endpoint: str) -> tuple[str, int]:
    host, _, port = endpoint.rpartition(":")
    try:
        return host, int(port)
    except ValueError:
        return endpoint, 0


def _betweenness(graph: Graph) -> None:
    """Brandes' algorithm on the unweighted graph."""
    import heapq

    nodes = list(graph.nodes)
    index = {n: i for i, n in enumerate(nodes)}
    adjacency: dict[int, set[int]] = defaultdict(set)
    for edge in graph.edges:
        s = index.get(edge.source)
        t = index.get(edge.target)
        if s is None or t is None or s == t:
            continue
        adjacency[s].add(t)
        adjacency[t].add(s)

    for node in nodes:
        node.betweenness = 0.0

    for source in adjacency:
        stack: list[int] = []
        predecessors: dict[int, list[int]] = {v: [] for v in adjacency}
        sigma = {v: 0.0 for v in adjacency}
        distance = {v: -1 for v in adjacency}
        sigma[source] = 1.0
        distance[source] = 0
        queue = [(0, source)]
        while queue:
            dist, v = heapq.heappop(queue)
            if dist > distance[v]:
                continue
            stack.append(v)
            for w in adjacency[v]:
                if distance[w] < 0:
                    distance[w] = dist + 1
                    heapq.heappush(queue, (distance[w], w))
                if distance[w] == dist + 1:
                    sigma[w] += sigma[v]
                    predecessors[w].append(v)
        delta = {v: 0.0 for v in adjacency}
        while stack:
            w = stack.pop()
            for v in predecessors[w]:
                if sigma[w]:
                    delta[v] += (sigma[v] / sigma[w]) * (1 + delta[w])
            if w != source:
                nodes[w].betweenness = (nodes[w].betweenness or 0.0) + delta[w]

    count = len(adjacency)
    if count > 2:
        for node in nodes:
            if node.betweenness is not None:
                node.betweenness /= ((count - 1) * (count - 2))


def rank_nodes(graph: Graph, limit: int = 20) -> list[dict[str, Any]]:
    """Rank by centrality, explicitly labelled as a triage aid."""
    ordered = sorted(
        graph.nodes.values(),
        key=lambda n: (-(n.betweenness or 0.0), -n.degree, -n.bytes_in - n.bytes_out),
    )[:limit]
    out = []
    for rank, node in enumerate(ordered, start=1):
        out.append(
            {
                "rank": rank,
                "node": node.to_dict(),
                "label": (
                    "Candidate for further review: high betweenness means many "
                    "observed paths pass through this host, not that it is a "
                    "command-and-control endpoint."
                ),
            }
        )
    return out

"""Anomaly detection with Isolation Forest.

Everything here is deliberately careful about wording:

* the score is a *relative* outlier measure, not a probability of compromise;
* features that cannot be computed from the current capture are excluded rather
  than imputed with zeros;
* the seed and parameters are stored so a score can be reproduced.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Sequence

ANOMALY_VERSION = "anomaly-detection/1.1"
MIN_TRAINING_SAMPLES = 50


@dataclass
class FeatureSet:
    names: list[str]
    rows: list[list[float]]
    entity_ids: list[str]
    entity_types: list[str]
    skipped: dict[str, str] = field(default_factory=dict)

    def __len__(self) -> int:
        return len(self.rows)


def message_features(record: dict[str, Any]) -> dict[str, float]:
    """Features for one message.

    Only values that are genuinely present are returned.  A missing feature is
    omitted so the model never learns from an imputed zero.
    """
    features = record.get("features") or {}
    out: dict[str, float] = {}
    if "length" in features:
        out["length"] = float(features["length"])
    if "entropy" in features:
        out["entropy"] = float(features["entropy"])
    if "unique_bytes" in features:
        out["unique_bytes"] = float(features["unique_bytes"])
    if "zero_ratio" in features:
        out["zero_ratio"] = float(features["zero_ratio"])
    if "printable_ratio" in features:
        out["printable_ratio"] = float(features["printable_ratio"])
    if "repeating_score" in features:
        out["repeating_score"] = float(features["repeating_score"])
    out["is_response"] = 1.0 if record.get("direction") == "b2a" else 0.0
    gap = record.get("inter_message_gap")
    if gap is not None:
        out["inter_message_gap"] = float(gap)
    if record.get("diagnostic_count") is not None:
        out["diagnostic_count"] = float(record["diagnostic_count"])
    return out


def session_features(record: dict[str, Any]) -> dict[str, float]:
    out: dict[str, float] = {}
    for key in (
        "message_count",
        "bytes_total",
        "mean_message_length",
        "stddev_message_length",
        "requests_per_second",
        "unique_peers",
        "retransmissions",
        "duration",
    ):
        if key in record and record[key] is not None:
            out[key] = float(record[key])
    return out


def build_matrix(
    records: Sequence[dict[str, Any]], extractor, *, limit: int = 50_000
) -> FeatureSet:
    kept: list[dict[str, float]] = []
    ids: list[str] = []
    types: list[str] = []
    names: set[str] = set()
    for record in records[:limit]:
        features = extractor(record)
        if not features:
            continue
        kept.append(features)
        ids.append(str(record.get("id")))
        types.append(str(record.get("entity_type", "unknown")))
        names.update(features)
    ordered = sorted(names)
    matrix = [[float(row.get(name, 0.0)) for name in ordered] for row in kept]
    # Rows that missed a feature are re-derived as partial: we drop them rather
    # than pretending the missing feature was zero.
    complete = [
        row
        for row, features in zip(matrix, kept)
        if all(name in features for name in ordered)
    ]
    skipped = {}
    if len(complete) != len(kept):
        skipped["incomplete_features"] = (
            f"{len(kept) - len(complete)} records lacked at least one feature and were "
            "excluded rather than imputed"
        )
    return FeatureSet(
        names=ordered,
        rows=complete,
        entity_ids=[i for i, (row, f) in enumerate(zip(kept, kept)) if all(n in f for n in ordered)],
        entity_types=types[: len(complete)],
        skipped=skipped,
    )


@dataclass
class TrainedModel:
    blob: bytes
    feature_names: list[str]
    params: dict[str, Any]
    summary: dict[str, Any]
    seed: int
    version: str = ANOMALY_VERSION


def train_isolation_forest(
    dataset: FeatureSet, *, contamination: float, n_estimators: int, seed: int
) -> TrainedModel:
    import pickle

    import numpy as np
    from sklearn.ensemble import IsolationForest

    if len(dataset) < MIN_TRAINING_SAMPLES:
        raise ValueError(
            f"At least {MIN_TRAINING_SAMPLES} samples are needed to train a stable "
            f"model; only {len(dataset)} were available."
        )
    matrix = np.asarray(dataset.rows, dtype=float)
    model = IsolationForest(
        n_estimators=n_estimators,
        contamination=contamination,
        random_state=seed,
        n_jobs=1,
    )
    model.fit(matrix)
    inlier_scores = -model.score_samples(matrix)
    summary = {
        "sample_count": int(matrix.shape[0]),
        "feature_count": int(matrix.shape[1]),
        "feature_names": dataset.feature_names,
        "contamination": contamination,
        "n_estimators": n_estimators,
        "seed": seed,
        "score_min": float(np.min(inlier_scores)),
        "score_max": float(np.max(inlier_scores)),
        "score_mean": float(np.mean(inlier_scores)),
        "score_std": float(np.std(inlier_scores)),
        "expected_outlier_fraction": float(contamination),
        "skipped": dataset.skipped,
        "interpretation": (
            "Scores are relative outlier measures within this baseline corpus. A "
            "higher score means 'less typical than the training data'. It is not a "
            "probability of compromise and carries no severity ranking."
        ),
        "warnings": _warnings(dataset, matrix),
    }
    return TrainedModel(
        blob=pickle.dumps(model, protocol=pickle.HIGHEST_PROTOCOL),
        feature_names=dataset.feature_names,
        params={
            "contamination": contamination,
            "n_estimators": n_estimators,
            "seed": seed,
            "algorithm": "isolation_forest",
            "sklearn_version": _sklearn_version(),
        },
        summary=summary,
        seed=seed,
    )


def score(model_blob: bytes, dataset: FeatureSet, *, limit: int = 2000) -> list[dict[str, Any]]:
    import pickle

    import numpy as np

    model = pickle.loads(model_blob)  # noqa: S301 - our own pickle, written by us
    if not dataset.rows:
        return []
    matrix = np.asarray(dataset.rows, dtype=float)
    scores = -model.score_samples(matrix)
    predictions = model.predict(matrix)
    rows: list[dict[str, Any]] = []
    for index, entity_id in enumerate(dataset.entity_ids[: len(matrix)]):
        rows.append(
            {
                "entity_id": entity_id,
                "entity_type": dataset.entity_types[index] if index < len(dataset.entity_types) else "unknown",
                "score": float(scores[index]),
                "classification": "outlier" if predictions[index] == -1 else "inlier",
            }
        )
    rows.sort(key=lambda r: r["score"], reverse=True)
    return rows[:limit]


def explain(entity_features: dict[str, float], dataset_mean: dict[str, float]) -> list[dict[str, Any]]:
    """Which features pushed an entity away from the baseline average."""
    out = []
    for name, value in entity_features.items():
        mean = dataset_mean.get(name)
        if mean is None:
            continue
        delta = float(value) - float(mean)
        scale = abs(float(mean)) or 1.0
        out.append(
            {
                "feature": name,
                "value": float(value),
                "baseline_mean": float(mean),
                "delta": round(delta, 4),
                "relative_delta": round(delta / scale, 4),
            }
        )
    out.sort(key=lambda r: abs(r["relative_delta"]), reverse=True)
    return out


def _warnings(dataset: FeatureSet, matrix) -> list[str]:
    import numpy as np

    warnings: list[str] = []
    if matrix.shape[0] < 500:
        warnings.append(
            f"Only {matrix.shape[0]} training samples were available. Isolation Forest "
            "is reliable from roughly 500 samples upward; treat these scores as noisy."
        )
    constant = [
        name
        for index, name in enumerate(dataset.feature_names)
        if float(np.std(matrix[:, index])) == 0.0
    ]
    if constant:
        warnings.append(
            f"These features were constant across the baseline corpus and carry no "
            f"information: {constant}."
        )
    return warnings


def _sklearn_version() -> str:
    try:
        import sklearn

        return sklearn.__version__
    except Exception:  # pragma: no cover - defensive
        return "unknown"


def sklearn_available() -> bool:
    try:
        import sklearn  # noqa: F401

        return True
    except ImportError:
        return False

