@router.get("/export")
def export_events(session: SessionDep, limit: Annotated[int, Query(ge=1, le=10_000)] = 1000) -> Response:
    import json

    rows = (
        session.execute(select(AuditEventRow).order_by(AuditEventRow.created_at.asc()).limit(limit))
