def _mark_previous_stale(self, project_id: str, current_id: str) -> None:
        """Previous runs used a different rule version, so they are stale."""
        stale_checksums = (
            self.db.execute(
                select(ValidationRun.id).where(
                    ValidationRun.project_id == project_id,
                    ValidationRun.stale.is_(False),
                )
            )
            .scalars()
            .all()
        )
        if not stale_checksums:
            return
        interpretation_ids = {
            rid
            for rid in self.db.execute(
                select(ValidationRun.interpretation_id).where(
                    ValidationRun.id.in_(stale_checksums)
                )
            ).scalars()
        }
        affected = [
            i.id for i in self.db.execute(
                select(Interpretation.id).where(Interpretation.id.in_(interpretation_ids))
            ).scalars() if i != current_id
        ]
        if affected:
            self.db.execute(
                update(ValidationRun)
                .where(ValidationRun.interpretation_id.in_(affected))
                .values(stale=True)
            )

def _detect_dns_tcp(stream: ReassembledStream) -> Detection | None:
    head = _head(stream)
    if len(head) < 12:
        return None
    txid = int.from_bytes(head[0:2], "big")
    flags = int.from_bytes(head[2:4], "big")
    if flags & 0x8000:
        return None  # response, not a query
    qdcount = int.from_bytes(head[4:6], "big")
    qtype = None
    offset = 12
    labels = 0
    while offset < len(head) and head[offset] != 0 and labels < 64:
        labels += 1
        offset += 1 + head[offset]
    if offset + 4 <= len(head):
        qtype = int.from_bytes(head[offset : offset + 2], "big")
    if qdcount < 1:
        return None
    signals = [
        f"header parses as a DNS query (transaction id 0x{txid:04x})",
        f"QDCOUNT={qdcount} question section(s)",
    ]
    failed: list[str] = []
    if qtype in (1, 2, 5, 12, 15, 16, 28, 33):
        signals.append(f"QTYPE={qtype} is a recognised query type")
    else:
        failed.append(f"QTYPE={qtype} is not a standard DNS query type")
    if qtype is not None and not _plausible_qname(head, 12):
        failed.append("question name does not look like a valid domain name")
    return Detection(
        protocol="dns_tcp",
        confidence=0.8 if not failed else 0.5,
        signals=signals,
        failed_checks=failed,
        evidence_offsets=[0],
    )

