           bg-surface-raised px-2.5 py-1 text-2xs font-medium text-text
           transition-colors hover:bg-line hover:border-accent-dim
           focus:outline-none focus-visible:ring-1 focus-visible:ring-accent
           disabled:opacity-40 disabled:pointer-events-none;
  }

  .btn-primary {
    @apply border-accent-dim bg-accent-faint text-accent hover:bg-accent-dim/40;
  }

  .btn-danger {
    @apply border-status-bad/40 text-status-bad hover:bg-status-bad/15;
  }

  .input {
    @apply w-full rounded-sm border border-line-strong bg-surface-sunken px-2 py-1
           text-2xs text-text placeholder:text-text-faint
           focus:outline-none focus:border-accent-dim;
  }

  .tag {
    @apply inline-flex items-center gap-1 rounded-sm border px-1.5 py-0.5
           text-2xs font-medium whitespace-nowrap;
  }

  .data-table {
    @apply w-full text-2xs font-mono;
  }

  .data-table th {
    @apply sticky top-0 z-10 bg-surface-raised px-2 py-1.5 text-left
           font-semibold text-text-muted uppercase tracking-wider
           border-b border-line whitespace-nowrap;
  }

  .data-table td {
    @apply px-2 py-1 border-b border-line/60 whitespace-nowrap text-text;
  }

  .data-table tbody tr:hover td {
