// --------------------------------------------------------------------------
// Transport
// --------------------------------------------------------------------------

async function request<T>(
  path: string,
  schema: z.ZodType<T>,
  init?: RequestInit,
): Promise<T> {
  let response: Response;
  try {
    response = await fetch(`${API_BASE}${path}`, {
      ...init,
      cache: "no-store",
      headers: {
        Accept: "application/json",
        ...(init?.body && !(init.body instanceof FormData)
          ? { "Content-Type": "application/json" }
          : {}),
        ...init?.headers,
      },
    });
  } catch (cause) {
    throw new ApiError(
      0,
      "backend_unreachable",
      `The backend at ${API_BASE} did not respond. Is it running?`,
      String(cause),
    );
  }

  const text = await response.text();
  let payload: unknown = null;
  if (text) {
    try {
      payload = JSON.parse(text);
    } catch {
      payload = null;
    }
  }

  if (!response.ok) {
    const errorBody = (payload ?? {}) as {
      error?: { code?: string; message?: string; details?: unknown };
      detail?: unknown;
    };
    throw new ApiError(
      response.status,
      errorBody.error?.code ?? "http_error",
      errorBody.error?.message ??
        (typeof errorBody.detail === "string"
          ? errorBody.detail
          : `Request failed with status ${response.status}.`),
      errorBody.error?.details ?? errorBody.detail ?? null,
    );
  }

  const parsed = schema.safeParse(payload);
  if (!parsed.success) {
    throw new ApiError(
      response.status,
      "schema_mismatch",
      "The backend returned data that does not match the expected shape.",
      parsed.error.issues.slice(0, 6),
    );
  }
  return parsed.data;
}

const json = (body: unknown): RequestInit => ({
  method: "POST",
  body: JSON.stringify(body),
});

