// --------------------------------------------------------------------------
// Formatting
// --------------------------------------------------------------------------

export function formatBytes(bytes: number): string {
  if (!Number.isFinite(bytes)) return "-";
  if (bytes < 1024) return `${bytes} B`;
  const units = ["KiB", "MiB", "GiB", "TiB"];
  let value = bytes / 1024;
  let index = 0;
  while (value >= 1024 && index < units.length - 1) {
    value /= 1024;
    index += 1;
  }
  return `${value.toFixed(value >= 100 ? 0 : 1)} ${units[index]}`;
}

export function formatNumber(value: number): string {
  return new Intl.NumberFormat("en-US").format(value);
}

export function formatTimestamp(epochSeconds: number): string {
  if (!epochSeconds) return "-";
  const date = new Date(epochSeconds * 1000);
  return date.toISOString().replace("T", " ").replace(".000Z", "Z");
}

export function formatDuration(seconds: number): string {
  if (!Number.isFinite(seconds) || seconds < 0) return "-";
  if (seconds < 1) return `${(seconds * 1000).toFixed(1)} ms`;
  if (seconds < 60) return `${seconds.toFixed(3)} s`;
  const minutes = Math.floor(seconds / 60);
  return `${minutes}m ${(seconds % 60).toFixed(0)}s`;
}

export function formatPercent(value: number, digits = 1): string {
  if (!Number.isFinite(value)) return "-";
  return `${(value * 100).toFixed(digits)}%`;
}

// --------------------------------------------------------------------------
// Status presentation
//
// Status is never conveyed by colour alone: every badge carries a text label,
// which is an accessibility requirement and also keeps the UI readable for
// colour-blind users.
// --------------------------------------------------------------------------

export type StatusTone = "ok" | "warn" | "bad" | "info" | "unknown" | "neutral";

const TONE_CLASSES: Record<StatusTone, string> = {
  ok: "border-status-ok/40 text-status-ok bg-status-ok/10",
  warn: "border-status-warn/40 text-status-warn bg-status-warn/10",
  bad: "border-status-bad/40 text-status-bad bg-status-bad/10",
  info: "border-status-info/40 text-status-info bg-status-info/10",
  unknown: "border-status-unknown/40 text-status-unknown bg-status-unknown/10",
  neutral: "border-line-strong text-text-muted bg-surface-raised",
};

export function toneClasses(tone: StatusTone): string {
  return TONE_CLASSES[tone];
}

export function completenessTone(status: string): StatusTone {
  switch (status) {
    case "complete":
      return "ok";
    case "open_at_capture_end":
      return "info";
    case "truncated_start":
    case "truncated_end":
    case "partial":
      return "warn";
    case "reset":
      return "bad";
    default:
      return "unknown";
  }
}

export function verdictTone(verdict: string): StatusTone {
  switch (verdict) {
    case "consistent_with_corpus":
      return "ok";
    case "partially_consistent":
      return "warn";
    case "contradicted":
      return "bad";
    case "no_data":
    case "canceled":
      return "unknown";
    default:
      return "neutral";
  }
}

export function roleTone(confidence: string): StatusTone {
  switch (confidence) {
    case "syn_observed":
      return "ok";
    case "heuristic_first_payload":
      return "warn";
    default:
      return "unknown";
  }
}

export function hypothesisTone(status: string): StatusTone {
  switch (status) {
    case "supported":
      return "ok";
    case "contradicted":
      return "bad";
    case "testing":
    case "proposed":
    case "revised":
      return "info";
    case "rejected":
      return "neutral";
    default:
      return "unknown";
  }
}

export function checkTone(verdict: string): StatusTone {
  switch (verdict) {
    case "pass":
      return "ok";
    case "fail":
      return "bad";
    case "unknown":
      return "warn";
    default:
      return "neutral";
  }
}

// --------------------------------------------------------------------------
// Hex helpers
// --------------------------------------------------------------------------

export function hexToBytes(hex: string): Uint8Array {
  const clean = hex.replace(/[^0-9a-fA-F]/g, "");
  const out = new Uint8Array(Math.floor(clean.length / 2));
  for (let i = 0; i < out.length; i += 1) {
    out[i] = parseInt(clean.slice(i * 2, i * 2 + 2), 16);
  }
  return out;
}

export function bytesToHex(bytes: Uint8Array): string {
  return Array.from(bytes, (b) => b.toString(16).padStart(2, "0")).join("");
}

export function asciiPreview(bytes: Uint8Array): string {
  let out = "";
  for (const byte of bytes) {
    out += byte >= 0x20 && byte < 0x7f ? String.fromCharCode(byte) : ".";
  }
  return out;
}

/** Rows are ``[offset, cells, ascii]``; gaps are rendered explicitly. */
export interface HexRow {
  offset: number;
  cells: string[];
  ascii: string;
  isGap: boolean;
}

export function toHexRows(
  lines: { offset: number; hex: string[]; ascii: string[]; length: number }[],
): HexRow[] {
  return lines.map((line) => ({
    offset: line.offset,
    cells: line.hex,
    ascii: line.ascii[0] ?? "",
    isGap: line.hex.includes("GAP"),
  }));
}

"use client";

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from "react";

import { api, ApiError } from "@/lib/api";

interface WorkspaceState {
  projectId: string | null;
  projectName: string | null;
  captureId: string | null;
  sessionId: string | null;
  streamId: string | null;
  messageId: string | null;
  backendOnline: boolean;
  backendError: string | null;
  selectProject: (id: string, name: string) => void;
  selectCapture: (id: string | null) => void;
  selectSession: (id: string | null) => void;
  selectStream: (id: string | null) => void;
  selectMessage: (id: string | null) => void;
  refreshHealth: () => Promise<void>;
  /** Bumped whenever a mutation invalidates the current view. */
  revision: number;
  invalidate: () => void;
}

const WorkspaceContext = createContext<WorkspaceState | null>(null);

const STORAGE_KEY = "mplab.workspace";

interface Persisted {
  projectId: string | null;
  projectName: string | null;
}

function loadPersisted(): Persisted {
  if (typeof window === "undefined") {
    return { projectId: null, projectName: null };
  }
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return { projectId: null, projectName: null };
    const parsed = JSON.parse(raw) as Partial<Persisted>;
    if (typeof parsed.projectId !== "string" || !/^[A-Za-z0-9]{1,64}$/.test(parsed.projectId)) {
      return { projectId: null, projectName: null };
    }
    return {
      projectId: parsed.projectId,
      projectName: typeof parsed.projectName === "string" ? parsed.projectName : null,
    };
  } catch {
    return { projectId: null, projectName: null };
  }
}

export function WorkspaceProvider({ children }: { children: ReactNode }) {
  const [state, setState] = useState<Omit<WorkspaceState, "selectProject" | "selectCapture" | "selectSession" | "selectStream" | "selectMessage" | "refreshHealth">>(() => {
    const persisted = loadPersisted();
    return {
      ...persisted,
      captureId: null,
      sessionId: null,
      streamId: null,
      messageId: null,
      backendOnline: false,
      backendError: null,
      revision: 0,
    };
  });

  useEffect(() => {
    if (!state.projectId) return;
    try {
      window.localStorage.setItem(
        STORAGE_KEY,
        JSON.stringify({ projectId: state.projectId, projectName: state.projectName }),
      );
    } catch {
      /* storage unavailable; the app still works, the selection is just not sticky */
    }
  }, [state.projectId, state.projectName]);

  const refreshHealth = useCallback(async () => {
    try {
      await api.health();
      setState((s) => ({ ...s, backendOnline: true, backendError: null }));
    } catch (error) {
      setState((s) => ({
        ...s,
        backendOnline: false,
        backendError:
          error instanceof ApiError ? error.message : "Backend unreachable.",
      }));
    }
  }, []);

  useEffect(() => {
    void refreshHealth();
    const timer = window.setInterval(() => void refreshHealth(), 15000);
    return () => window.clearInterval(timer);
  }, [refreshHealth]);

  const value = useMemo<WorkspaceState>(
    () => ({
      ...state,
      selectProject: (id, name) =>
        setState((s) => ({
          ...s,
          projectId: id,
          projectName: name,
          captureId: null,
          sessionId: null,
          streamId: null,
          messageId: null,
        })),
      selectCapture: (id) =>
        setState((s) => ({ ...s, captureId: id, sessionId: null, streamId: null, messageId: null })),
      selectSession: (id) =>
        setState((s) => ({ ...s, sessionId: id, streamId: null, messageId: null })),
      selectStream: (id) => setState((s) => ({ ...s, streamId: id, messageId: null })),
      selectMessage: (id) => setState((s) => ({ ...s, messageId: id })),
      refreshHealth,
      invalidate: () => setState((s) => ({ ...s, revision: s.revision + 1 })),
    }),
    [state, refreshHealth],
  );

  return (
    <WorkspaceContext.Provider value={value}>{children}</WorkspaceContext.Provider>
  );
}

export function useWorkspace(): WorkspaceState {
  const context = useContext(WorkspaceContext);
  if (!context) {
    throw new Error("useWorkspace must be used inside a WorkspaceProvider");
  }
  return context;
}

/** Convenience: the selected project id, or null. */
export function useProjectId(): string | null {
  return useWorkspace().projectId;
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";

import { ApiError } from "@/lib/api";

export type LoadState = "idle" | "loading" | "ready" | "error";

export interface AsyncResult<T> {
  state: LoadState;
  data: T | null;
  error: string | null;
  reload: () => void;
  setData: (value: T | null) => void;
}

/**
 * Fetch-on-mount with cancellation and an explicit refresh handle.
 *
 * Errors are surfaced verbatim: the API already returns safe, user-facing
 * messages, so nothing is swallowed here.
 */
export function useAsync<T>(
  loader: () => Promise<T>,
  deps: unknown[],
  options: { enabled?: boolean } = {},
): AsyncResult<T> {
  const enabled = options.enabled ?? true;
  const [state, setState] = useState<LoadState>(enabled ? "loading" : "idle");
  const [data, setData] = useState<T | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [nonce, setNonce] = useState(0);
  const active = useRef(true);
  const loaderRef = useRef(loader);
  loaderRef.current = loader;

  useEffect(() => {
    active.current = true;
    return () => {
      active.current = false;
    };
  }, []);

  useEffect(() => {
    if (!enabled) {
      setState("idle");
      return;
    }
    setState("loading");
    setError(null);
    loaderRef
      .current()
      .then((value) => {
        if (!active.current) return;
        setData(value);
        setState("ready");
      })
      .catch((cause: unknown) => {
        if (!active.current) return;
        setError(cause instanceof ApiError ? cause.message : String(cause));
        setState("error");
      });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [...deps, enabled, nonce]);

  const reload = useCallback(() => setNonce((n) => n + 1), []);
  return { state, data, error, reload, setData };
}

/** Track an in-flight mutation with progress and typed errors. */
export function useAction() {
  const [pending, setPending] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);

  const run = useCallback(
    async <T,>(fn: () => Promise<T>, successMessage?: string): Promise<T | null> => {
      setPending(true);
      setError(null);
      setNotice(null);
      try {
        const value = await fn();
        if (successMessage) setNotice(successMessage);
        return value;
      } catch (cause) {
        setError(cause instanceof ApiError ? cause.message : String(cause));
        return null;
      } finally {
        setPending(false);
      }
    },
    [],
  );

  const clear = useCallback(() => {
    setError(null);
    setNotice(null);
  }, []);

  return { pending, error, notice, run, clear, setError };
}

/** Poll a job until it reaches a terminal state. */
export function useJobPoller(jobId: string | null) {
  const [job, setJob] = useState<Record<string, unknown> | null>(null);
  const timer = useRef<number | null>(null);

  useEffect(() => {
    if (!jobId) {
      setJob(null);
      return;
    }
    let cancelled = false;
    const poll = async () => {
      try {
        const { api } = await import("@/lib/api");
        const value = await api.job(jobId);
        if (cancelled) return;
        setJob(value);
        if (["succeeded", "failed", "canceled"].includes(String(value.status))) {
          return;
        }
      } catch {
        /* a transient poll failure is not fatal; the next tick retries */
      }
      if (!cancelled) {
        timer.current = window.setTimeout(poll, 900);
      }
    };
    void poll();
    return () => {
      cancelled = true;
      if (timer.current) window.clearTimeout(timer.current);
    };
  }, [jobId]);

  return job;
}

"use client";

import type { ReactNode } from "react";

import { cn, toneClasses, type StatusTone } from "@/lib/format";

// --------------------------------------------------------------------------
// Primitives shared by every tool panel.
// --------------------------------------------------------------------------

export function Panel({
  title,
  actions,
  children,
  className,
  bodyClassName,
}: {
  title?: ReactNode;
  actions?: ReactNode;
  children: ReactNode;
  className?: string;
  bodyClassName?: string;
}) {
  return (
    <section className={cn("panel flex min-h-0 flex-col", className)}>
      {(title || actions) && (
        <header className="panel-header shrink-0">
          <h2 className="panel-title">{title}</h2>
          <div className="flex items-center gap-2">{actions}</div>
        </header>
      )}
      <div className={cn("min-h-0 flex-1 overflow-auto", bodyClassName)}>{children}</div>
    </section>
  );
}

export function Badge({
  tone = "neutral",
  children,
  title,
}: {
  tone?: StatusTone;
  children: ReactNode;
  title?: string;
}) {
  return (
    <span className={cn("tag", toneClasses(tone))} title={title}>
      {children}
    </span>
  );
}

export function EmptyState({
  title,
  description,
  action,
}: {
  title: string;
  description?: string;
  action?: ReactNode;
}) {
  return (
    <div className="flex h-full min-h-[160px] flex-col items-center justify-center gap-2 p-6 text-center">
      <p className="text-sm font-medium text-text">{title}</p>
      {description && <p className="max-w-md text-xs text-text-muted">{description}</p>}
      {action && <div className="mt-2">{action}</div>}
    </div>
  );
}

export function ErrorState({ message, onRetry }: { message: string; onRetry?: () => void }) {
  return (
    <div
      className="m-3 rounded-sm border border-status-bad/40 bg-status-bad/5 p-3"
      role="alert"
    >
      <p className="text-2xs font-semibold uppercase tracking-wider text-status-bad">
        Request failed
      </p>
      <p className="mt-1 font-mono text-2xs text-text">{message}</p>
      {onRetry && (
        <button type="button" className="btn mt-2" onClick={onRetry}>
          Retry
        </button>
      )}
    </div>
  );
}

export function Loading({ label = "Loading" }: { label?: string }) {
  return (
    <div className="flex h-full min-h-[120px] items-center justify-center gap-2 p-4">
      <span className="h-3 w-3 animate-spin rounded-full border border-line-strong border-t-accent" />
      <span className="text-2xs uppercase tracking-widest text-text-faint">{label}</span>
    </div>
  );
}

export function Skeleton({ rows = 6 }: { rows?: number }) {
  return (
    <div className="space-y-1.5 p-3" aria-hidden>
      {Array.from({ length: rows }, (_, index) => (
        <div
          key={index}
          className="h-3 animate-pulse rounded-sm bg-surface-raised"
          style={{ width: `${95 - (index % 4) * 12}%` }}
        />
      ))}
    </div>
  );
}

/**
 * A claim that needs a caveat always gets one rendered next to it.
 * This is the product's core promise: no conclusion without its limits.
 */
export function Caveat({ children, tone = "neutral" }: { children: ReactNode; tone?: StatusTone }) {
  return (
    <p
      className={cn(
        "border-l-2 py-1 pl-2 text-2xs leading-relaxed text-text-muted",
        tone === "warn" && "border-status-warn text-status-warn",
        tone === "bad" && "border-status-bad text-status-bad",
        tone === "info" && "border-status-info text-status-info",
      )}
    >
      {children}
    </p>
  );
}

export function Metric({
  label,
  value,
  hint,
  tone,
}: {
  label: string;
  value: ReactNode;
  hint?: string;
  tone?: StatusTone;
}) {
  return (
    <div className="rounded-sm border border-line bg-surface-raised px-2.5 py-2">
      <p className="text-2xs uppercase tracking-wider text-text-faint">{label}</p>
      <p
        className={cn(
          "mt-0.5 font-mono text-base leading-tight",
          tone === "ok" && "text-status-ok",
          tone === "warn" && "text-status-warn",
          tone === "bad" && "text-status-bad",
          !tone && "text-text",
        )}
      >
        {value}
      </p>
      {hint && <p className="mt-0.5 text-2xs text-text-faint">{hint}</p>}
    </div>
  );
}

export function ConfirmButton({
  label,
  confirmLabel,
  onConfirm,
  tone = "btn-danger",
  disabled,
}: {
  label: string;
  confirmLabel: string;
  onConfirm: () => void;
  tone?: string;
  disabled?: boolean;
}) {
  return (
    <span className="inline-flex items-center gap-1">
      <button
        type="button"
        className={cn("btn", tone)}
        disabled={disabled || undefined}
        onClick={onConfirm}
      >
        {label}
      </button>
    </span>
  );
}

