"use client";

import { useMemo, useState } from "react";

import { cn, toHexRows } from "@/lib/format";

export interface Hole {
  start: number;
  end: number;
  length: number;
  reason: string;
}

interface HexViewerProps {
  lines: {
    offset: number;
    hex: string[];
    ascii: string[];
    length: number;
  }[];
  /** Absolute stream offsets to highlight (e.g. the selected message). */
  highlightRange?: { start: number; end: number } | null;
  holes?: Hole[];
  onOffsetClick?: (offset: number) => void;
  dense?: boolean;
}

/**
 * Hex + ASCII view.
 *
 * Missing bytes are rendered as an explicit `GAP` marker rather than as zeros:
 * the viewer must never imply that bytes exist where the capture lost them.
 */
export function HexViewer({
  lines,
  highlightRange,
  holes = [],
  onOffsetClick,
  dense = false,
}: HexViewerProps) {
  const rows = useMemo(() => toHexRows(lines), [lines]);
  const [selected, setSelected] = useState<number | null>(null);

  const inHighlight = (offset: number): boolean => {
    if (!highlightRange) return false;
    return offset >= highlightRange.start && offset < highlightRange.end;
  };

  const isGap = (offset: number): boolean =>
    holes.some((hole) => offset >= hole.start && offset < hole.end);

  if (rows.length === 0) {
    return (
      <p className="p-3 text-2xs text-text-faint">
        No bytes to display at this offset.
      </p>
    );
  }

  return (
    <div className={cn("hexdump overflow-x-auto", dense && "text-[10px] leading-4")}>
      <table className="w-full border-collapse">
        <tbody>
          {rows.map((row) => (
            <tr key={row.offset} className="align-top">
              <td className="hex-offset whitespace-nowrap pr-3">
                <button
                  type="button"
                  className="hover:text-accent"
                  onClick={() => {
                    setSelected(row.offset);
                    onOffsetClick?.(row.offset);
                  }}
                  title={
                    selected === row.offset
                      ? "Copied offset shown in the toolbar"
                      : "Select this row"
                  }
                >
                  {row.offset.toString(16).padStart(8, "0")}
                </button>
              </td>
              <td className="whitespace-pre">
                {row.cells.map((cell, index) => {
                  const absolute = row.offset + index;
                  if (cell === "GAP") {
                    return (
                      <span key={index} className="hex-byte hex-byte-gap" title="Bytes missing from the capture">
                        GAP
                      </span>
                    );
                  }
                  const gapped = isGap(absolute);
                  return (
                    <span
                      key={index}
                      className={cn(
                        "hex-byte",
                        inHighlight(absolute) && "hex-byte-highlight",
                        gapped && "hex-byte-gap",
                      )}
                      title={`offset ${absolute} (0x${cell})`}
                    >
                      {cell}
                    </span>
                  );
                })}
              </td>
              <td className="whitespace-pre pl-3 text-text-muted">{row.ascii}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

/** Side-by-side comparison with per-offset change highlighting. */
export function HexComparison({
  rows,
  labels,
}: {
  rows: {
    offset: number;
    values: (number | null)[];
    changed: boolean;
    present_count: number;
  }[];
  labels: string[];
}) {
  const [onlyDifferences, setOnlyDifferences] = useState(false);
  const visible = onlyDifferences ? rows.filter((row) => row.changed) : rows;
  const changedCount = rows.filter((row) => row.changed).length;

  return (
    <div className="flex min-h-0 flex-col">
      <div className="flex items-center justify-between border-b border-line px-3 py-1.5">
        <span className="text-2xs text-text-muted">
          {changedCount} of {rows.length} offsets differ
        </span>
        <label className="flex items-center gap-1.5 text-2xs text-text-muted">
          <input
            type="checkbox"
            checked={onlyDifferences}
            onChange={(event) => setOnlyDifferences(event.target.checked)}
          />
          only differing offsets
        </label>
      </div>
      <div className="min-h-0 flex-1 overflow-auto">
        <table className="data-table">
          <thead>
            <tr>
              <th>Offset</th>
              {labels.map((label, index) => (
                <th key={index} className="text-right">
                  {label}
                </th>
              ))}
              <th>State</th>
            </tr>
          </thead>
          <tbody>
            {visible.map((row) => (
              <tr key={row.offset} className={row.changed ? "bg-status-warn/5" : undefined}>
                <td className="text-text-faint">{row.offset}</td>
                {row.values.map((value, index) => (
                  <td
                    key={index}
                    className={cn(
                      "text-right",
                      value === null
                        ? "text-text-faint italic"
                        : row.changed
                          ? "text-status-warn"
                          : "text-text",
                    )}
                    title={
                      value === null
                        ? "absent: this message is shorter than this offset (not zero)"
                        : undefined
                    }
                  >
                    {value === null ? "— absent —" : `0x${value.toString(16).padStart(2, "0")}`}
                  </td>
                ))}
                <td>
                  {row.changed ? (
                    <span className="text-status-warn">
                      {row.present_count < row.values.length ? "differs / absent" : "differs"}
                    </span>
                  ) : (
                    <span className="text-text-faint">identical</span>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";

import { Badge, EmptyState, Panel } from "@/components/ui";
import { useAsync, useAction } from "@/hooks/use-async";
import { useWorkspace } from "@/hooks/use-workspace";
import { api } from "@/lib/api";
import { cn, formatBytes, formatTimestamp } from "@/lib/format";

/** Project selector + creation form. Persisted in the workspace context. */
export function ProjectPicker() {
  const workspace = useWorkspace();
  const projects = useAsync(() => api.listProjects(), [workspace.revision]);
  const action = useAction();
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");

  const create = async () => {
    if (!name.trim()) return;
    const created = await action.run(
      () => api.createProject(name.trim(), description.trim()),
      `Project "${name.trim()}" created.`,
    );
    if (created) {
      workspace.selectProject(created.id, created.name);
      workspace.invalidate();
      setName("");
      setDescription("");
      projects.reload();
    }
  };

  const adopt = (id: string) => {
    const project = projects.data?.find((p) => p.id === id);
    if (project) {
      workspace.selectProject(project.id, project.name);
      workspace.invalidate();
    }
  };

  return (
    <Panel
      title="Investigation project"
      actions={
        projects.state === "loading" ? (
          <span className="text-2xs text-text-faint">loading…</span>
        ) : (
          <button type="button" className="btn" onClick={projects.reload}>
            Refresh
          </button>
        )
      }
    >
      <div className="p-3">
        {projects.state === "error" && (
          <p className="mb-3 rounded-sm border border-status-bad/40 bg-status-bad/5 p-2 font-mono text-2xs text-status-bad">
            {projects.error}
          </p>
        )}

        {projects.data && projects.data.length === 0 && (
          <EmptyState
            title="No projects yet"
            description="Create an investigation project, then import a PCAP capture to begin."
          />
        )}

        <ul className="space-y-1">
          {(projects.data ?? []).map((project) => {
            const active = project.id === workspace.projectId;
            return (
              <li key={project.id}>
                <button
                  type="button"
                  onClick={() => adopt(project.id)}
                  aria-current={active ? "true" : undefined}
                  className={cn(
                    "flex w-full items-center justify-between gap-3 rounded-sm border px-2.5 py-2 text-left transition-colors",
                    active
                      ? "border-accent-dim bg-accent-faint"
                      : "border-line bg-surface-raised hover:border-line-strong",
                  )}
                >
                  <span className="min-w-0">
                    <span
                      className={cn(
                        "block truncate text-xs font-medium",
                        active ? "text-accent" : "text-text",
                      )}
                    >
                      {project.name}
                    </span>
                    <span className="mt-0.5 block font-mono text-2xs text-text-faint">
                      {project.capture_count} capture(s) · {project.message_count} message(s) ·{" "}
                      {project.hypothesis_count} hypothesis/hypotheses
                    </span>
                  </span>
                  {active && <Badge tone="info">current</Badge>}
                </button>
              </li>
            );
          })}
        </ul>

        <div className="mt-4 border-t border-line pt-3">
          <p className="mb-2 text-2xs uppercase tracking-wider text-text-faint">
            New project
          </p>
          <input
            className="input"
            placeholder="Project name"
            value={name}
            maxLength={200}
            onChange={(event) => setName(event.target.value)}
          />
          <textarea
            className="input mt-1.5 h-16 resize-y"
            placeholder="What is the investigation trying to establish?"
            value={description}
            maxLength={20000}
            onChange={(event) => setDescription(event.target.value)}
          />
          <button
            type="button"
            className="btn btn-primary mt-2"
            disabled={!name.trim() || action.pending}
            onClick={create}
          >
            {action.pending ? "Creating…" : "Create project"}
          </button>
          {action.notice && (
            <p className="mt-2 text-2xs text-status-ok">{action.notice}</p>
          )}
          {action.error && <p className="mt-2 text-2xs text-status-bad">{action.error}</p>}
        </div>
      </div>
    </Panel>
  );
}

/** Capture selector, scoped to the current project. */
export function CapturePicker({ onSelect }: { onSelect?: (id: string) => void }) {
  const workspace = useWorkspace();
  const [busy, setBusy] = useState(false);
  const fileInput = useRef<HTMLInputElement>(null);

  const sessions = useAsync(
    async () => {
      if (!workspace.captureId) return null;
      return api.listSessions(workspace.captureId);
    },
    [workspace.captureId, workspace.revision],
  );

  const capture = useAsync(
    async () => {
      if (!workspace.captureId) return null;
      return api.getCapture(workspace.captureId);
    },
    [workspace.captureId, workspace.revision],
  );

  const importFile = async (file: File) => {
    if (!workspace.projectId) return;
    setBusy(true);
    try {
      const imported = await api.importCapture(workspace.projectId, file, file.name);
      workspace.selectCapture(imported.id);
      workspace.invalidate();
      onSelect?.(imported.id);
    } catch (error) {
      window.alert(
        error instanceof Error
          ? error.message
          : "The capture could not be imported. See the Security Center for the active limits.",
      );
    } finally {
      setBusy(false);
    }
  };

  return (
    <Panel title="Selected capture">
      <div className="space-y-2 p-3">
        {!workspace.captureId && (
          <EmptyState
            title="No capture selected"
            description="Import a PCAP or PCAPNG file to start. The original bytes are stored immutably and hashed."
            action={
              <button
                type="button"
                className="btn btn-primary"
                disabled={!workspace.projectId || busy}
                onClick={() => fileInput.current?.click()}
              >
                {busy ? "Importing…" : "Import PCAP"}
              </button>
            }
          />
        )}

        <input
          ref={fileInput}
          type="file"
          accept=".pcap,.pcapng,.cap"
          className="hidden"
          onChange={(event) => {
            const file = event.target.files?.[0];
            if (file) void importFile(file);
            event.target.value = "";
          }}
        />

        {workspace.captureId && capture.data && (
          <div className="space-y-1.5 font-mono text-2xs">
            <Row label="name" value={capture.data.name} />
            <Row label="format" value={capture.data.format} />
            <Row label="size" value={formatBytes(capture.data.file_size)} />
            <Row label="sha256" value={`${capture.data.sha256.slice(0, 32)}…`} />
            <Row label="imported" value={formatTimestamp(Date.parse(capture.data.imported_at) / 1000)} />
            <Row label="analysis" value={capture.data.analysis_status} />
          </div>
        )}

        {sessions.data && (
          <p className="border-t border-line pt-2 text-2xs text-text-muted">
            {sessions.data.total} TCP session(s) in this capture.
          </p>
        )}

        {workspace.captureId && (
          <button
            type="button"
            className="btn w-full"
            disabled={!workspace.projectId || busy}
            onClick={() => fileInput.current?.click()}
          >
            Import another capture
          </button>
        )}
      </div>
    </Panel>
  );
}

function Row({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex gap-2">
      <span className="w-20 shrink-0 text-text-faint">{label}</span>
      <span className="min-w-0 break-all text-text">{value}</span>
    </div>
  );
}

"use client";

import Link from "next/link";
import { useSearchParams } from "next/navigation";
import { useEffect } from "react";

import { CapturePicker, ProjectPicker } from "@/components/pickers";
import {
  Badge,
  Caveat,
  EmptyState,
  ErrorState,
  Metric,
