                  <div className="space-y-2 p-3">
                    <div className="flex items-center gap-2">
                      <Badge tone={integrity.data.all_match ? "ok" : "bad"}>
                        {integrity.data.all_match
                          ? "all captures match their recorded hashes"
                          : "hash mismatch detected"}
