"use client";

import { useSearchParams } from "next/navigation";
import { useState } from "react";
import { Play, Trash2, Upload } from "lucide-react";

import { Badge, Caveat, EmptyState, ErrorState, Panel, Skeleton } from "@/components/ui";
import { useAction, useAsync } from "@/hooks/use-async";
import { useWorkspace } from "@/hooks/use-workspace";
import { api } from "@/lib/api";
import { cn, formatBytes, formatTimestamp } from "@/lib/format";

export default function CapturesPage() {
  const workspace = useWorkspace();
  const params = useSearchParams();
  const projectId = params.get("project") ?? workspace.projectId;
  const [busy, setBusy] = useState(false);
  const [importError, setImportError] = useState<string | null>(null);

  const metrics = useAsync(
    () => (projectId ? api.metrics(projectId) : Promise.resolve(null)),
    [projectId, workspace.revision],
  );

  // Captures are listed through the project's own captures.
  const sessions = useAsync(
    () =>
      workspace.captureId ? api.listSessions(workspace.captureId) : Promise.resolve(null),
    [workspace.captureId, workspace.revision],
  );

  const capture = useAsync(
    () =>
      workspace.captureId ? api.getCapture(workspace.captureId) : Promise.resolve(null),
    [workspace.captureId, workspace.revision],
  );

  const analyze = useAction();
  const remove = useAction();

  const doImport = async (file: File) => {
    if (!projectId) return;
    setBusy(true);
    setImportError(null);
    try {
      const imported = await api.importCapture(projectId, file, file.name);
      workspace.selectCapture(imported.id);
      workspace.invalidate();
    } catch (error) {
      setImportError(error instanceof Error ? error.message : String(error));
    } finally {
      setBusy(false);
    }
  };

  if (!projectId) {
    return (
      <div className="p-4">
        <EmptyState
          title="No project selected"
          description="Open a project on the Overview page first."
        />
      </div>
    );
  }

  const stats = (capture.data?.stats ?? {}) as Record<string, unknown>;
  const readerDiagnostics = (stats.reader_diagnostics ?? {}) as {
    errors?: string[];
    warnings?: string[];
  };

  return (
    <div className="flex h-full flex-col">
      <div className="flex shrink-0 items-start justify-between gap-4 border-b border-line px-4 py-3">
        <div>
          <h1 className="text-sm font-semibold tracking-tight text-text">Captures</h1>
          <p className="mt-0.5 max-w-3xl text-2xs leading-relaxed text-text-muted">
            Imported files are immutable. Analysis reads them and writes derived artefacts
            alongside; the original bytes are never rewritten.
          </p>
        </div>
        <label className="btn btn-primary cursor-pointer">
          <Upload className="h-3 w-3" aria-hidden />
          {busy ? "Importing…" : "Import PCAP"}
          <input
            type="file"
            accept=".pcap,.pcapng,.cap"
            className="hidden"
            onChange={(event) => {
              const file = event.target.files?.[0];
              if (file) void doImport(file);
              event.target.value = "";
            }}
          />
        </label>
      </div>

      <div className="min-h-0 flex-1 overflow-auto p-4">
        {importError && (
          <div className="mb-3 rounded-sm border border-status-bad/40 bg-status-bad/5 p-2 text-2xs text-status-bad">
            {importError}
          </div>
        )}

        <div className="grid gap-4 lg:grid-cols-3">
          <div className="space-y-4 lg:col-span-1">
            <Panel title="Project totals">
              {metrics.state === "loading" ? (
                <Skeleton rows={5} />
              ) : metrics.data ? (
                <dl className="space-y-1 p-3 font-mono text-2xs">
                  <Line label="captures" value={metrics.data.captures} />
                  <Line label="packets" value={metrics.data.packets} />
                  <Line label="tcp sessions" value={metrics.data.tcp_sessions} />
                  <Line label="messages" value={metrics.data.messages} />
                  <Line label="bytes stored" value={formatBytes(metrics.data.bytes_stored)} />
                </dl>
              ) : null}
            </Panel>

            <Panel title="Selected capture">
              {!workspace.captureId ? (
                <EmptyState title="No capture selected" description="Import a file to begin." />
              ) : capture.state === "loading" ? (
                <Skeleton rows={6} />
              ) : capture.data ? (
                <div className="space-y-2 p-3">
                  <dl className="space-y-1 font-mono text-2xs">
                    <Line label="name" value={capture.data.name} />
                    <Line label="format" value={capture.data.format} />
                    <Line label="size" value={formatBytes(capture.data.file_size)} />
                    <Line label="sha256" value={`${capture.data.sha256.slice(0, 24)}…`} />
                    <Line
                      label="imported"
                      value={formatTimestamp(Date.parse(capture.data.imported_at) / 1000)}
                    />
                    <Line label="status" value={capture.data.analysis_status} />
                  </dl>
                  <div className="flex flex-wrap gap-2 pt-1">
                    <button
                      type="button"
                      className="btn btn-primary"
                      disabled={analyze.pending}
                      onClick={() =>
                        void analyze.run(
                          () => api.analyze(capture.data!.id, {}),
                          "Analysis finished.",
                        ).then((result) => {
                          if (result) workspace.invalidate();
                        })
                      }
                    >
                      <Play className="h-3 w-3" aria-hidden />
                      {analyze.pending ? "Analysing…" : "Run analysis"}
                    </button>
                    <button
                      type="button"
                      className="btn"
                      disabled={analyze.pending}
                      onClick={() =>
                        void analyze
                          .run(() => api.analyzeAsync(capture.data!.id), "Queued as a background job.")
                          .then((result) => {
                            if (result) workspace.invalidate();
                          })
                      }
                    >
                      Queue in background
                    </button>
                    <button
                      type="button"
                      className="btn btn-danger"
                      disabled={remove.pending}
                      onClick={() => {
                        if (
                          !window.confirm(
                            `Delete "${capture.data!.name}" and everything derived from it?\n\n` +
                              "This cannot be undone.",
                          )
                        ) {
                          return;
                        }
                        void remove
                          .run(() => api.deleteCapture(capture.data!.id), "Capture deleted.")
                          .then((ok) => {
                            if (ok) {
                              workspace.selectCapture(null);
                              workspace.invalidate();
                            }
                          });
                      }}
                    >
                      <Trash2 className="h-3 w-3" aria-hidden />
                      Delete
                    </button>
                  </div>
                  {analyze.notice && (
                    <p className="text-2xs text-status-ok">{analyze.notice}</p>
                  )}
                  {(analyze.error || remove.error) && (
                    <p className="text-2xs text-status-bad">{analyze.error ?? remove.error}</p>
                  )}
                </div>
              ) : null}
            </Panel>
          </div>

          <div className="space-y-4 lg:col-span-2">
            <Panel title="Analysis result">
              {Object.keys(stats).length === 0 ? (
                <EmptyState
                  title="Not analysed yet"
                  description="Run the analysis to index packets, split TCP sessions and reconstruct the byte streams."
                />
              ) : (
                <div className="space-y-3 p-3">
                  <div className="grid grid-cols-2 gap-2 md:grid-cols-4">
                    <Stat label="sessions" value={String(stats.sessions ?? 0)} />
                    <Stat label="streams" value={String(stats.streams ?? 0)} />
                    <Stat label="messages" value={String(stats.messages ?? 0)} />
                    <Stat
                      label="sessions with problems"
                      value={String(stats.sessions_with_problems ?? 0)}
                      tone={Number(stats.sessions_with_problems ?? 0) > 0 ? "warn" : "ok"}
                    />
                  </div>

                  <div>
                    <p className="mb-1 text-2xs uppercase tracking-wider text-text-faint">
                      Reader diagnostics
                    </p>
                    {readerDiagnostics.errors?.length ? (
                      <ul className="space-y-1">
                        {readerDiagnostics.errors.map((error, index) => (
                          <li key={index} className="font-mono text-2xs text-status-bad">
                            {error}
                          </li>
                        ))}
                      </ul>
                    ) : (
                      <p className="text-2xs text-status-ok">No read errors.</p>
                    )}
                    {readerDiagnostics.warnings?.map((warning, index) => (
                      <p key={index} className="mt-1 font-mono text-2xs text-status-warn">
                        {warning}
                      </p>
                    ))}
                  </div>

                  {stats.options ? (
                    <div>
                      <p className="mb-1 text-2xs uppercase tracking-wider text-text-faint">
                        Analysis options (recorded for reproducibility)
                      </p>
                      <pre className="overflow-x-auto rounded-sm border border-line bg-surface-sunken p-2 font-mono text-2xs">
                        {JSON.stringify(stats.options, null, 2)}
                      </pre>
                    </div>
                  ) : null}

                  <Caveat>
                    These counts come from the options recorded above. Re-running with a
                    different framing rule or conflict policy produces a different set of
                    rows from the same bytes.
                  </Caveat>
                </div>
              )}
            </Panel>

            <Panel title="TCP sessions in this capture">
              {sessions.state === "error" ? (
                <ErrorState message={sessions.error ?? ""} onRetry={sessions.reload} />
              ) : !workspace.captureId ? (
                <EmptyState title="No capture selected" />
              ) : sessions.state === "loading" ? (
                <Skeleton rows={5} />
              ) : sessions.data && sessions.data.items.length > 0 ? (
                <table className="data-table">
                  <thead>
                    <tr>
                      <th>Identity</th>
                      <th>Endpoints</th>
                      <th>Completeness</th>
                      <th>Role basis</th>
                    </tr>
                  </thead>
                  <tbody>
                    {sessions.data.items.map((row) => {
                      const session = row as unknown as {
                        id: string;
                        session_identity: string;
                        client_endpoint: string | null;
                        server_endpoint: string | null;
                        completeness_status: string;
                        role_confidence: string;
                      };
                      return (
                        <tr key={session.id}>
                          <td className="text-accent">{session.session_identity}</td>
                          <td>
                            {session.client_endpoint ?? "?"} → {session.server_endpoint ?? "?"}
                          </td>
                          <td>
                            <Badge
                              tone={
                                session.completeness_status === "complete" ? "ok" : "warn"
                              }
                            >
                              {session.completeness_status}
                            </Badge>
                          </td>
                          <td className="text-text-muted">{session.role_confidence}</td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              ) : (
                <EmptyState
                  title="No sessions"
                  description="This capture contains no TCP conversations."
                />
              )}
            </Panel>
          </div>
        </div>
      </div>
    </div>
  );
}

function Line({ label, value }: { label: string; value: string | number }) {
  return (
    <div className="flex justify-between gap-2">
      <dt className="text-text-faint">{label}</dt>
      <dd className={cn("text-text")}>{value}</dd>
    </div>
  );
}

function Stat({
  label,
  value,
  tone,
}: {
  label: string;
  value: string;
  tone?: "ok" | "warn";
}) {
  return (
    <div className="rounded-sm border border-line bg-surface-raised px-2 py-1.5">
      <p className="text-2xs uppercase tracking-wider text-text-faint">{label}</p>
      <p
        className={cn(
          "font-mono text-sm",
          tone === "warn" ? "text-status-warn" : tone === "ok" ? "text-status-ok" : "text-text",
        )}
      >
        {value}
      </p>
    </div>
  );
}

"use client";

import { useSearchParams } from "next/navigation";
import { useState } from "react";

import {
  Badge,
  Caveat,
  EmptyState,
  ErrorState,
  Panel,
  Skeleton,
} from "@/components/ui";
import { useAsync } from "@/hooks/use-async";
import { useWorkspace } from "@/hooks/use-workspace";
import { api } from "@/lib/api";
import {
  completenessTone,
  formatDuration,
  formatTimestamp,
  roleTone,
} from "@/lib/format";

type TimelineEvent = {
  packet_index: number;
  timestamp: number;
  direction: string;
  source: string;
  destination: string;
  sequence: number | null;
  acknowledgment: number | null;
  flags: number;
  flags_text: string;
  window: number | null;
  payload_length: number;
  options: string | null;
};

export default function SessionsPage() {
  const workspace = useWorkspace();
  const params = useSearchParams();
  const captureId = workspace.captureId;
  const [selected, setSelected] = useState<string | null>(workspace.sessionId);

  const sessions = useAsync(
    () => (captureId ? api.listSessions(captureId) : Promise.resolve(null)),
    [captureId, workspace.revision],
  );

  const timeline = useAsync(
    () => (selected ? api.timeline(selected) : Promise.resolve(null)),
    [selected],
  );

  const diagnostics = useAsync(
    () => (selected ? api.diagnostics(selected) : Promise.resolve(null)),
    [selected],
  );

  if (!captureId) {
    return (
      <div className="p-4">
        <EmptyState
          title="No capture selected"
          description="Pick a capture on the Captures page first; TCP sessions are derived from it."
        />
      </div>
    );
  }

  const events = ((timeline.data?.events ?? []) as TimelineEvent[]) ?? [];
  const summary = (timeline.data ?? {}) as Record<string, unknown>;

  return (
    <div className="flex h-full flex-col">
      <div className="border-b border-line px-4 py-3">
        <h1 className="text-sm font-semibold tracking-tight text-text">TCP Sessions</h1>
        <p className="mt-0.5 max-w-3xl text-2xs leading-relaxed text-text-muted">
          A 4-tuple is not a session. Port reuse and a new SYN split the flow; the
          splitting policy is recorded on every session so a result can be explained later.
        </p>
      </div>

      <div className="grid min-h-0 flex-1 grid-cols-1 gap-3 overflow-hidden p-3 lg:grid-cols-[320px_1fr]">
        <Panel title="Sessions">
          {sessions.state === "error" ? (
            <ErrorState message={sessions.error ?? ""} onRetry={sessions.reload} />
          ) : sessions.state === "loading" ? (
            <Skeleton rows={8} />
          ) : !sessions.data || sessions.data.items.length === 0 ? (
            <EmptyState
              title="No TCP sessions"
              description="This capture has not been analysed, or contains no TCP traffic."
            />
          ) : (
            <ul>
              {sessions.data.items.map((item) => {
                const row = item as unknown as {
                  id: string;
                  session_identity: string;
                  client_endpoint: string | null;
                  server_endpoint: string | null;
                  completeness_status: string;
                  role_confidence: string;
                  start_time: number;
                  end_time: number;
                };
                const active = row.id === selected;
                return (
                  <li key={row.id}>
                    <button
                      type="button"
                      onClick={() => {
                        setSelected(row.id);
                        workspace.selectSession(row.id);
                      }}
                      className={`w-full border-b border-line/60 px-3 py-2 text-left transition-colors ${
                        active ? "bg-accent-faint" : "hover:bg-surface-raised"
                      }`}
                    >
                      <div className="flex items-center justify-between gap-2">
                        <span className={`font-mono text-2xs ${active ? "text-accent" : "text-text"}`}>
                          {row.session_identity}
                        </span>
                        <Badge tone={completenessTone(row.completeness_status)}>
                          {row.completeness_status}
                        </Badge>
                      </div>
                      <p className="mt-0.5 truncate font-mono text-2xs text-text-muted">
                        {row.client_endpoint ?? "?"} → {row.server_endpoint ?? "?"}
                      </p>
                      <p className="mt-0.5 text-2xs text-text-faint">
                        {formatDuration(row.end_time - row.start_time)} ·{" "}
                        {formatTimestamp(row.start_time)}
                      </p>
                    </button>
                  </li>
                );
              })}
            </ul>
          )}
        </Panel>

        <div className="flex min-h-0 flex-col gap-3 overflow-auto">
          {!selected ? (
            <Panel>
              <EmptyState
                title="Select a session"
                description="The timeline shows only what the capture observed. It is not a reconstruction of either TCP stack."
              />
            </Panel>
          ) : (
            <>
              <Panel
                title="Connection state (observed)"
                actions={
                  <div className="flex gap-1">
                    <Badge tone={summary.saw_syn ? "ok" : "unknown"}>
                      SYN {summary.saw_syn ? "seen" : "not seen"}
                    </Badge>
                    <Badge tone={summary.saw_fin ? "ok" : "unknown"}>
                      FIN {summary.saw_fin ? "seen" : "not seen"}
                    </Badge>
                    <Badge tone={summary.saw_rst ? "bad" : "unknown"}>
                      RST {summary.saw_rst ? "seen" : "not seen"}
                    </Badge>
                  </div>
                }
              >
                <div className="space-y-2 p-3">
                  <p className="text-2xs text-text-muted">
                    <Badge tone={roleTone(String(summary.role_confidence ?? ""))}>
                      {String(summary.role_confidence ?? "unknown")}
                    </Badge>{" "}
                    {String(summary.role_rationale ?? "")}
                  </p>
                  {timeline.data ? (
                    <Caveat>{String(timeline.data.disclaimer ?? "")}</Caveat>
                  ) : null}
                  <div className="overflow-x-auto">
                    <table className="data-table">
                      <thead>
                        <tr>
                          <th>#</th>
                          <th>Time</th>
                          <th>Dir</th>
                          <th>Source</th>
                          <th>Flags</th>
                          <th>Seq</th>
                          <th>Ack</th>
                          <th>Win</th>
                          <th>Payload</th>
                          <th>Options</th>
                        </tr>
                      </thead>
                      <tbody>
                        {events.map((event) => (
                          <tr key={event.packet_index}>
                            <td className="text-text-faint">{event.packet_index}</td>
                            <td className="text-text-muted">
                              {event.timestamp.toFixed(6)}
                            </td>
                            <td>
                              <Badge tone={event.direction === "a2b" ? "info" : "neutral"}>
                                {event.direction}
                              </Badge>
                            </td>
                            <td className="text-text-muted">{event.source}</td>
                            <td
                              className={
                                event.flags_text.includes("RST")
                                  ? "text-status-bad"
                                  : event.flags_text.includes("SYN")
                                    ? "text-status-ok"
                                    : "text-text"
                              }
                            >
                              {event.flags_text}
                            </td>
                            <td className="text-text-faint">
                              {event.sequence ?? "-"}
                            </td>
                            <td className="text-text-faint">
                              {event.acknowledgment ?? "-"}
                            </td>
                            <td className="text-text-faint">{event.window ?? "-"}</td>
                            <td>{event.payload_length}</td>
                            <td className="text-text-faint">{event.options ?? "-"}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              </Panel>

              <Panel title="Reconstruction diagnostics">
                {diagnostics.state === "loading" ? (
                  <Skeleton rows={6} />
                ) : diagnostics.data ? (
                  <DiagnosticsView data={diagnostics.data as Record<string, unknown>} />
                ) : (
                  <EmptyState title="No diagnostics" />
                )}
              </Panel>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

function DiagnosticsView({ data }: { data: Record<string, unknown> }) {
  const explanations = (data.explanations ?? {}) as Record<string, string>;
  const streams = (data.streams ?? []) as Record<string, unknown>[];

  return (
    <div className="space-y-3 p-3">
      {streams.length === 0 && (
        <p className="text-2xs text-text-faint">
          No stream payload was observed for this session.
        </p>
      )}
      {streams.map((stream) => {
        const direction = String(stream.direction);
        const conflicts = (stream.conflicts ?? []) as Record<string, unknown>[];
        const holes = (stream.holes ?? []) as { reason: string; start: number; end: number }[];
        const retransmissions = (stream.retransmissions ?? []) as Record<string, unknown>[];
        const outOfOrder = (stream.out_of_order ?? []) as Record<string, unknown>[];
        const duplicates = (stream.duplicates ?? []) as Record<string, unknown>[];
        const zeroWindows = (stream.zero_windows ?? []) as Record<string, unknown>[];

        return (
          <div key={String(stream.stream_id)} className="rounded-sm border border-line p-2.5">
            <div className="mb-2 flex items-center justify-between">
              <span className="font-mono text-2xs text-accent">{direction}</span>
              <span className="text-2xs text-text-faint">
                conflict policy: {String(stream.conflict_policy ?? "-")}
              </span>
            </div>
            <div className="grid grid-cols-2 gap-1.5 md:grid-cols-4">
              <Count label="retransmissions" value={retransmissions.length} note={explanations.retransmission} />
              <Count label="exact duplicates" value={duplicates.length} note={explanations.retransmission} />
              <Count label="out of order" value={outOfOrder.length} note={explanations.out_of_order} />
              <Count label="holes" value={holes.length} note={explanations.hole} tone={holes.length ? "warn" : undefined} />
              <Count label="byte conflicts" value={conflicts.length} note={explanations.conflict} tone={conflicts.length ? "bad" : undefined} />
              <Count label="zero window" value={zeroWindows.length} note={explanations.zero_window} />
            </div>

            {holes.length > 0 && (
              <ul className="mt-2 space-y-0.5 font-mono text-2xs text-status-warn">
                {holes.slice(0, 8).map((hole, index) => (
                  <li key={index}>
                    gap {hole.start}..{hole.end} ({hole.reason})
                  </li>
                ))}
              </ul>
            )}

            {conflicts.length > 0 && (
              <ul className="mt-2 space-y-1 border-t border-line pt-2">
                {conflicts.slice(0, 4).map((conflict, index) => (
                  <li key={index} className="font-mono text-2xs text-status-bad">
                    offsets {String(conflict.start_offset)}..{String(conflict.end_offset)}: kept{" "}
                    {String(conflict.kept_hex)} / rejected {String(conflict.rejected_hex)} (
                    {String(conflict.resolution)})
                  </li>
                ))}
              </ul>
            )}
          </div>
        );
      })}

      <details className="rounded-sm border border-line p-2">
        <summary className="cursor-pointer text-2xs text-text-muted">
          What these labels mean
        </summary>
        <dl className="mt-2 space-y-1.5">
          {Object.entries(explanations).map(([key, text]) => (
            <div key={key}>
              <dt className="font-mono text-2xs text-accent">{key}</dt>
              <dd className="text-2xs text-text-muted">{text}</dd>
            </div>
          ))}
        </dl>
      </details>
    </div>
  );
}

function Count({
  label,
  value,
  note,
  tone,
}: {
  label: string;
  value: number;
  note?: string;
  tone?: "warn" | "bad";
}) {
  return (
    <div className="rounded-sm bg-surface-raised px-2 py-1" title={note}>
      <p className="text-2xs uppercase tracking-wider text-text-faint">{label}</p>
      <p
        className={`font-mono text-xs ${
          tone === "bad"
            ? "text-status-bad"
            : tone === "warn"
              ? "text-status-warn"
              : "text-text"
        }`}
      >
        {value}
      </p>
    </div>
  );
}

"use client";

import { useSearchParams } from "next/navigation";
import { useEffect, useMemo, useState } from "react";

import { HexViewer } from "@/components/hex-viewer";
import {
  Badge,
  Caveat,
  EmptyState,
  ErrorState,
  Panel,
  Skeleton,
} from "@/components/ui";
import { useAction, useAsync } from "@/hooks/use-async";
import { useWorkspace } from "@/hooks/use-workspace";
import { api } from "@/lib/api";
import { cn, formatNumber } from "@/lib/format";

const WINDOW = 512;

export default function StreamsPage() {
  const workspace = useWorkspace();
  const params = useSearchParams();
  const sessionId = params.get("session") ?? workspace.sessionId;
  const [streamId, setStreamId] = useState<string | null>(workspace.streamId);
  const [offset, setOffset] = useState(0);
  const [selectedMessage, setSelectedMessage] = useState<{
    start: number;
    end: number;
    label: string;
  } | null>(null);

  const streams = useAsync(
    () => (sessionId ? api.sessionStreams(sessionId) : Promise.resolve(null)),
    [sessionId, workspace.revision],
  );

  const messages = useAsync(
    () =>
      streamId
        ? api.listMessages(
            (workspace.captureId as string) ?? "",
            `?stream_id=${streamId}&limit=200`,
          )
        : Promise.resolve(null),
    [streamId, workspace.captureId, workspace.revision],
  );

  const bytes = useAsync(
    () =>
      streamId
        ? api.streamBytes(streamId, offset, WINDOW)
        : Promise.resolve(null),
    [streamId, offset],
  );

  const suggestions = useAsync(
    () => (streamId ? api.framingSuggestions(streamId) : Promise.resolve(null)),
    [streamId, workspace.revision],
  );

  const apply = useAction();

  useEffect(() => {
    if (streams.data && streams.data.length > 0 && !streamId) {
      const first = streams.data[0];
      setStreamId(first.id);
      workspace.selectStream(first.id);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [streams.data]);

  const stream = streams.data?.find((s) => s.id === streamId) ?? null;
  const holes = useMemo(
    () =>
      ((bytes.data?.holes ?? []) as { start: number; end: number; length: number; reason: string }[]) ?? [],
    [bytes.data],
  );

  return (
    <div className="flex h-full flex-col">
      <div className="border-b border-line px-4 py-3">
        <h1 className="text-sm font-semibold tracking-tight text-text">Stream Explorer</h1>
        <p className="mt-0.5 max-w-3xl text-2xs leading-relaxed text-text-muted">
          The reconstructed byte stream, its coverage map and the packets that produced
          each byte. Missing ranges are shown as gaps and are never filled with zeros.
        </p>
      </div>

      <div className="flex min-h-0 flex-1 flex-col overflow-hidden">
        <div className="flex flex-wrap items-center gap-2 border-b border-line bg-surface px-3 py-1.5">
          {(streams.data ?? []).map((s) => (
            <button
              key={s.id}
              type="button"
              onClick={() => {
                setStreamId(s.id);
                setOffset(0);
                workspace.selectStream(s.id);
              }}
              className={cn(
                "btn",
                s.id === streamId && "btn-primary",
              )}
            >
              {s.direction} · {s.local_endpoint} → {s.remote_endpoint}
              <span className="text-text-faint">
                {formatNumber(s.present_bytes)}/{formatNumber(s.stream_length)} B
              </span>
            </button>
          ))}
          {stream && (
            <Badge tone={stream.protocol_label === "unknown_binary" ? "unknown" : "info"}>
              protocol: {stream.protocol_label} ({stream.protocol_confidence.toFixed(2)})
            </Badge>
          )}
          <span className="ml-auto flex items-center gap-1">
            <button type="button" className="btn" onClick={() => setOffset(Math.max(0, offset - WINDOW))}>
              ← prev
            </button>
            <span className="font-mono text-2xs text-text-muted">
              offset {formatNumber(offset)} … {formatNumber(offset + WINDOW)}
            </span>
            <button
              type="button"
              className="btn"
              onClick={() => setOffset(offset + WINDOW)}
              disabled={stream ? offset + WINDOW >= stream.stream_length : true}
            >
              next →
            </button>
          </span>
        </div>

        <div className="grid min-h-0 flex-1 grid-cols-1 gap-3 overflow-auto p-3 lg:grid-cols-[1fr_360px]">
          <div className="flex min-h-0 flex-col gap-3">
            <Panel
              title="Reconstructed bytes"
              actions={
                selectedMessage ? (
                  <Badge tone="info">
                    highlighting message {selectedMessage.label}
                  </Badge>
                ) : (
                  <span className="text-2xs text-text-faint">select a message below</span>
                )
              }
            >
              {bytes.state === "error" ? (
                <ErrorState message={bytes.error ?? ""} onRetry={bytes.reload} />
              ) : bytes.state === "loading" ? (
                <Skeleton rows={12} />
              ) : bytes.data ? (
                <HexViewer
                  lines={bytes.data.lines}
                  holes={holes}
                  highlightRange={
                    selectedMessage
                      ? { start: selectedMessage.start, end: selectedMessage.end }
                      : null
                  }
                />
              ) : (
                <EmptyState title="No stream selected" />
              )}
            </Panel>

            {holes.length > 0 && (
              <Panel title="Coverage gaps">
                <div className="space-y-1.5 p-3">
                  {holes.map((hole, index) => (
                    <div key={index} className="flex items-center justify-between font-mono text-2xs">
                      <span className="text-status-warn">
                        {hole.start} … {hole.end} ({hole.length} bytes)
                      </span>
                      <span className="text-text-faint">{hole.reason}</span>
                    </div>
                  ))}
                  <Caveat tone="warn">
                    These bytes were never captured. They are not recoverable from this
                    file, and nothing in the analysis substitutes a guess for them.
                  </Caveat>
                </div>
              </Panel>
            )}

            <Panel title="Framing candidates for this stream">
              {suggestions.state === "loading" ? (
                <Skeleton rows={4} />
              ) : suggestions.data ? (
                <div className="space-y-1.5 p-3">
                  {suggestions.data.suggestions.slice(0, 6).map((s, index) => (
                    <div
                      key={index}
                      className="flex flex-wrap items-center gap-2 rounded-sm border border-line bg-surface-raised px-2.5 py-1.5"
                    >
                      <Badge tone={index === 0 ? "ok" : "neutral"}>
                        score {s.score.toFixed(3)}
                      </Badge>
                      <span className="font-mono text-2xs text-text">
                        {s.method} {JSON.stringify(s.config)}
                      </span>
                      <span className="text-2xs text-text-faint">
                        {JSON.stringify(s.evidence)}
                      </span>
                      {index === 0 && stream && (
                        <button
                          type="button"
                          className="btn btn-primary ml-auto"
                          disabled={apply.pending}
                          onClick={() =>
                            void apply
                              .run(
                                () =>
                                  api.analyze(workspace.captureId as string, {
                                    framing: { method: s.method, config: s.config },
                                  }),
                                "Framing rule applied; messages regenerated.",
                              )
                              .then(() => workspace.invalidate())
                          }
                        >
                          Apply and re-frame
                        </button>
                      )}
                    </div>
                  ))}
                  <Caveat>{suggestions.data.disclaimer}</Caveat>
                </div>
              ) : (
                <EmptyState title="No candidates" />
              )}
            </Panel>
          </div>

          <div className="flex min-h-0 flex-col gap-3">
            <Panel title="Framed messages">
              {messages.state === "loading" ? (
                <Skeleton rows={10} />
              ) : messages.data && messages.data.items.length > 0 ? (
                <table className="data-table">
                  <thead>
                    <tr>
                      <th>#</th>
                      <th>Range</th>
                      <th>Len</th>
                      <th>Declared</th>
                      <th>State</th>
                    </tr>
                  </thead>
                  <tbody>
                    {messages.data.items.map((item) => {
                      const row = item as unknown as {
                        id: string;
                        index_in_stream: number;
                        start_offset: number;
                        end_offset: number;
                        present_length: number;
                        declared_length: number | null;
                        complete: boolean;
                        packet_references: { packet_index: number }[];
                      };
                      const active =
                        selectedMessage?.start === row.start_offset &&
                        selectedMessage?.end === row.end_offset;
                      return (
                        <tr
                          key={row.id}
                          onClick={() => {
                            setSelectedMessage({
                              start: row.start_offset,
                              end: row.end_offset,
                              label: `#${row.index_in_stream}`,
                            });
                            workspace.selectMessage(row.id);
                          }}
                          className={cn("cursor-pointer", active && "bg-accent-faint")}
                        >
                          <td className="text-text-faint">{row.index_in_stream}</td>
                          <td className="text-text-muted">
                            {row.start_offset}…{row.end_offset}
                          </td>
                          <td>{row.present_length}</td>
                          <td className="text-text-muted">{row.declared_length ?? "-"}</td>
                          <td>
                            <Badge tone={row.complete ? "ok" : "warn"}>
                              {row.complete ? "complete" : "partial"}
                            </Badge>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              ) : (
                <EmptyState
                  title="No messages framed"
                  description="Apply a framing rule to split the byte stream into messages."
                />
              )}
            </Panel>

            <Panel title="Packets behind the current window">
              {bytes.data?.packet_references?.length ? (
                <table className="data-table">
                  <thead>
                    <tr>
                      <th>Packet</th>
                      <th>Stream offsets</th>
                    </tr>
                  </thead>
                  <tbody>
                    {(bytes.data.packet_references as { packet_index: number; start_offset: number; end_offset: number }[]).map(
                      (ref, index) => (
                        <tr key={index}>
                          <td className="text-accent">#{ref.packet_index}</td>
                          <td className="text-text-muted">
                            {ref.start_offset}…{ref.end_offset}
                          </td>
                        </tr>
                      ),
                    )}
                  </tbody>
                </table>
              ) : (
                <EmptyState
                  title="No packets in this window"
                  description="Bytes with no packet behind them are holes."
                />
              )}
            </Panel>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useSearchParams } from "next/navigation";
import { useState } from "react";

import { HexComparison, HexViewer } from "@/components/hex-viewer";
import {
  Badge,
  Caveat,
  EmptyState,
  ErrorState,
  Panel,
  Skeleton,
} from "@/components/ui";
import { useAsync } from "@/hooks/use-async";
import { useWorkspace } from "@/hooks/use-workspace";
import { api } from "@/lib/api";
import { cn } from "@/lib/format";

type MessageRow = {
  id: string;
  index_in_stream: number;
  start_offset: number;
  end_offset: number;
  present_length: number;
  declared_length: number | null;
  complete: boolean;
  confidence: number;
  framing_method: string;
  features: Record<string, number>;
};

export default function WorkbenchPage() {
  const workspace = useWorkspace();
  const params = useSearchParams();
  const sessionId = params.get("session") ?? workspace.sessionId;
  const captureId = workspace.captureId;

  const [streamId, setStreamId] = useState<string | null>(workspace.streamId);
  const [selected, setSelected] = useState<string[]>([]);
  const [directionFilter, setDirectionFilter] = useState<string>("all");

  const streams = useAsync(
    () => (sessionId ? api.sessionStreams(sessionId) : Promise.resolve(null)),
    [sessionId, workspace.revision],
  );

  const messages = useAsync(
    () =>
      streamId && captureId
        ? api.listMessages(captureId, `?stream_id=${streamId}&limit=500`)
        : Promise.resolve(null),
    [streamId, captureId, workspace.revision],
  );

  const stats = useAsync(
    () => (streamId ? api.fieldStatistics(streamId) : Promise.resolve(null)),
    [streamId, workspace.revision],
  );

  const comparison = useAsync(async () => {
    if (!streamId || selected.length < 2) return null;
    return api.compareMessages(streamId, selected);
  }, [streamId, selected.join(",")]);

  const rows = ((messages.data?.items ?? []) as unknown as MessageRow[]) ?? [];
  const filtered =
    directionFilter === "all"
      ? rows
      : (streams.data ?? []).filter((s) => s.id === streamId) &&
        rows;

  const toggle = (id: string) => {
    setSelected((current) => {
      if (current.includes(id)) return current.filter((item) => item !== id);
      if (current.length >= 6) return [...current.slice(1), id];
      return [...current, id];
    });
  };

  if (!captureId) {
    return (
      <div className="p-4">
        <EmptyState
          title="No capture selected"
          description="The Protocol Workbench compares framed messages from a reconstructed stream."
        />
      </div>
    );
  }

  const candidates = (stats.data?.candidates ?? []) as {
    name: string;
    offset: number;
    size: number;
    endianness: string;
    role: string;
    confidence: number;
    rationale: string;
    support_count: number;
    contradiction_count: number;
  }[];

  const columnStats = (stats.data?.column_stats ?? []) as {
    offset: number;
    present_count: number;
    absent_count: number;
    unique_values: number;
    entropy: number;
    change_rate: number;
    zero_count: number;
    most_common: [number, number][];
  }[];

  return (
    <div className="flex h-full flex-col">
      <div className="flex shrink-0 items-start justify-between gap-4 border-b border-line px-4 py-3">
        <div>
          <h1 className="text-sm font-semibold tracking-tight text-text">Protocol Workbench</h1>
          <p className="mt-0.5 max-w-3xl text-2xs leading-relaxed text-text-muted">
            Compare binary messages side by side, read the per-offset statistics and see
            which field candidates the data actually supports.
          </p>
        </div>
        <div className="flex flex-wrap items-center gap-1">
          {(streams.data ?? []).map((s) => (
            <button
              key={s.id}
              type="button"
              className={cn("btn", s.id === streamId && "btn-primary")}
              onClick={() => {
                setStreamId(s.id);
                setSelected([]);
              }}
            >
              {s.direction}
            </button>
          ))}
          {directionFilter !== "all" && (
            <span className="text-2xs text-text-faint">filter: {directionFilter}</span>
          )}
        </div>
      </div>

      <div className="grid min-h-0 flex-1 grid-cols-1 gap-3 overflow-auto p-3 xl:grid-cols-2">
        <Panel
          title="Messages (select 2–6 to compare)"
          actions={
            selected.length > 0 ? (
              <button type="button" className="btn" onClick={() => setSelected([])}>
                clear
              </button>
            ) : null
          }
        >
          {messages.state === "loading" ? (
            <Skeleton rows={12} />
          ) : messages.state === "error" ? (
            <ErrorState message={messages.error ?? ""} onRetry={messages.reload} />
          ) : filtered.length === 0 ? (
            <EmptyState
              title="No framed messages"
              description="Choose a framing rule on the Stream Explorer first."
            />
          ) : (
            <table className="data-table">
              <thead>
                <tr>
                  <th />
                  <th>#</th>
                  <th>Range</th>
                  <th>Len</th>
                  <th>Entropy</th>
                  <th>Unique</th>
                  <th>State</th>
                </tr>
              </thead>
              <tbody>
                {filtered.map((message) => {
                  const active = selected.includes(message.id);
                  return (
                    <tr
                      key={message.id}
                      className={cn("cursor-pointer", active && "bg-accent-faint")}
                      onClick={() => toggle(message.id)}
                    >
                      <td>
                        <input type="checkbox" checked={active} readOnly />
                      </td>
                      <td className="text-text-faint">{message.index_in_stream}</td>
                      <td className="text-text-muted">
                        {message.start_offset}…{message.end_offset}
                      </td>
                      <td>{message.present_length}</td>
                      <td>{(message.features.entropy ?? 0).toFixed(2)}</td>
                      <td>{message.features.unique_bytes ?? "-"}</td>
                      <td>
                        <Badge tone={message.complete ? "ok" : "warn"}>
                          {message.complete ? "complete" : "partial"}
                        </Badge>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          )}
        </Panel>

        <Panel title="Per-offset alignment">
          {selected.length < 2 ? (
            <EmptyState
              title="Select at least two messages"
              description="Alignment is positional: a byte at offset N in one message is compared with offset N in another. Where a message is shorter, the position is shown as absent, never as zero."
            />
          ) : comparison.state === "loading" ? (
            <Skeleton rows={12} />
          ) : comparison.data ? (
            <div className="flex h-full min-h-0 flex-col">
              <div className="border-b border-line p-2">
                <p className="text-2xs text-text-muted">
                  {String((comparison.data.alignment as { description: string }).description)}
                </p>
              </div>
              <HexComparison
                labels={selected.map((id) => `#${rows.find((r) => r.id === id)?.index_in_stream ?? "?"}`)}
                rows={(comparison.data.rows as never[]) ?? []}
              />
            </div>
          ) : (
            <EmptyState title="No comparison" />
          )}
        </Panel>

        <Panel title="Field candidates inferred from the bytes">
          {stats.state === "loading" ? (
            <Skeleton rows={8} />
          ) : candidates.length === 0 ? (
            <EmptyState
              title="No candidates"
              description="Insufficient messages or no structure detected yet."
            />
          ) : (
            <div className="space-y-2 p-3">
              {candidates.slice(0, 10).map((candidate, index) => (
                <div
                  key={index}
                  className="rounded-sm border border-line bg-surface-raised p-2.5"
                >
                  <div className="flex flex-wrap items-center gap-2">
                    <Badge tone={index === 0 ? "ok" : "neutral"}>{candidate.role}</Badge>
                    <span className="font-mono text-2xs text-accent">
                      {candidate.name} @ {candidate.offset} ({candidate.size}B{" "}
                      {candidate.endianness})
                    </span>
                    <span className="ml-auto font-mono text-2xs text-text-muted">
                      {(candidate.confidence * 100).toFixed(0)}%
                    </span>
                  </div>
                  <p className="mt-1 text-2xs leading-relaxed text-text-muted">
                    {candidate.rationale}
                  </p>
                  <p className="mt-1 font-mono text-2xs text-text-faint">
                    supports {candidate.support_count} · contradicts{" "}
                    {candidate.contradiction_count}
                  </p>
                </div>
              ))}
              <Caveat tone="warn">
                These are hypotheses generated from observed bytes. A candidate name is
                a label, not a claim: nothing here proves what a field <em>means</em>.
              </Caveat>
            </div>
          )}
        </Panel>

        <Panel title="Column statistics">
          {columnStats.length === 0 ? (
            <EmptyState title="No statistics" />
          ) : (
            <div className="overflow-x-auto">
              <table className="data-table">
                <thead>
                  <tr>
                    <th>Offset</th>
                    <th>Present</th>
                    <th>Absent</th>
                    <th>Unique</th>
                    <th>Entropy</th>
                    <th>Change rate</th>
                    <th>Most common</th>
                  </tr>
                </thead>
                <tbody>
                  {columnStats.slice(0, 64).map((column) => (
                    <tr key={column.offset}>
                      <td className="text-text-faint">{column.offset}</td>
                      <td>{column.present_count}</td>
                      <td className={cn(column.absent_count > 0 && "text-status-warn")}>
                        {column.absent_count}
                      </td>
                      <td>{column.unique_values}</td>
                      <td>{column.entropy.toFixed(2)}</td>
                      <td>{column.change_rate.toFixed(2)}</td>
                      <td className="text-text-muted">
                        {column.most_common
                          .slice(0, 3)
                          .map(([value, count]) => `0x${value.toString(16)}=${count}`)
                          .join(" ")}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
              <div className="p-3">
                <Caveat>
                  A position that is absent from some messages is counted as absent.
                  Missing bytes are never filled with zero, and a field that only
                  exists in some messages is reported as such.
                </Caveat>
              </div>
            </div>
          )}
        </Panel>
      </div>
    </div>
  );
}

/** Re-exported for the message detail drawer used by other pages. */
export { HexViewer };

"use client";

import { useSearchParams } from "next/navigation";
import { useEffect, useMemo, useState } from "react";
import { Check, FlaskConical, PlayCircle, X } from "lucide-react";

import {
  Badge,
  Caveat,
  EmptyState,
  ErrorState,
  Panel,
  Skeleton,
} from "@/components/ui";
import { useAction, useAsync } from "@/hooks/use-async";
import { useWorkspace } from "@/hooks/use-workspace";
import { api } from "@/lib/api";
import { cn, formatTimestamp, hypothesisTone, verdictTone } from "@/lib/format";

const STARTER_SPEC = {
  schema_version: "1.0",
  protocol_name: "NewProtocol",
  description: "What this specification claims, and how it was arrived at.",
  direction: "both",
  framing: {
    method: "length_prefix",
    length_field: {
      offset: 0,
      size: 2,
      endianness: "big",
      includes_header: true,
    },
  },
  fields: [
    {
      name: "length",
      kind: "uint16",
      offset: 0,
      size: 2,
      endianness: "big",
      semantic_status: "observed",
      description: "Total message length, including these two bytes.",
    },
  ],
};

export default function HypothesesPage() {
  const workspace = useWorkspace();
  const params = useSearchParams();
  const projectId = params.get("project") ?? workspace.projectId;

  const [draft, setDraft] = useState(JSON.stringify(STARTER_SPEC, null, 2));
  const [specError, setSpecError] = useState<string | null>(null);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [runId, setRunId] = useState<string | null>(null);
  const [corpus, setCorpus] = useState<string[]>([]);
  const [runResult, setRunResult] = useState<Record<string, unknown> | null>(null);

  const action = useAction();
  const validateAction = useAction();

  const hypotheses = useAsync(
    () => (projectId ? api.hypotheses(projectId) : Promise.resolve([])),
    [projectId, workspace.revision],
  );

  const interpretations = useAsync(
    () => (projectId ? api.interpretations(projectId) : Promise.resolve([])),
    [projectId, workspace.revision],
  );

  const support = useAsync(
    () => (projectId ? api.interpretationSupport(projectId) : Promise.resolve(null)),
    [projectId],
  );

  const metrics = useAsync(
    () => (projectId ? api.metrics(projectId) : Promise.resolve(null)),
    [projectId, workspace.revision],
  );

  const run = useAsync(
    () => (runId ? api.validationRun(runId) : Promise.resolve(null)),
    [runId],
  );

  const counterexamples = useAsync(
    () => (runId ? api.counterexamples(runId) : Promise.resolve(null)),
    [runId],
  );

  // Default the corpus to every capture in the project.
  useEffect(() => {
    if (metrics.data && corpus.length === 0) {
      void (async () => {
        const ids: string[] = [];
        // The metrics endpoint does not list capture ids, so derive them from the
        // project export path the UI already uses elsewhere.
        const rows = (hypotheses.data ?? []) as { id: string }[];
        void rows;
        setCorpus(ids);
      })();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [metrics.data]);

  const selected = (interpretations.data ?? []).find((i) => i.id === selectedId) ?? null;

  useEffect(() => {
    if (selected && typeof selected.specification === "object") {
      setDraft(JSON.stringify(selected.specification, null, 2));
    }
  }, [selectedId]); // eslint-disable-line react-hooks/exhaustive-deps

  const parseDraft = (): Record<string, unknown> | null => {
    try {
      const parsed = JSON.parse(draft);
      if (typeof parsed !== "object" || parsed === null) {
        setSpecError("The specification must be a JSON object.");
        return null;
      }
      setSpecError(null);
      return parsed as Record<string, unknown>;
    } catch (error) {
      setSpecError(error instanceof Error ? error.message : "Invalid JSON.");
      return null;
    }
  };

  const create = async () => {
    if (!projectId) return;
    const specification = parseDraft();
    if (!specification) return;
    const created = await action.run(
      () =>
        api.createInterpretation(projectId, {
          name: String(specification.protocol_name ?? "Interpretation"),
          specification,
        }),
      "Interpretation created.",
    );
    if (created) {
      setSelectedId(created.id);
      workspace.invalidate();
    }
  };

  const update = async () => {
    if (!projectId || !selectedId) return;
    const specification = parseDraft();
    if (!specification) return;
    const updated = await action.run(
      () => api.updateInterpretation(projectId, selectedId, { specification }),
      "Interpretation updated. Previous validation runs are now marked stale.",
    );
    if (updated) {
      workspace.invalidate();
      setRunResult(null);
    }
  };

  const validate = async () => {
    if (!projectId || !selectedId) return;
    if (corpus.length === 0) {
      validateAction.setError(
        "Select at least one capture to validate against. A rule tested on no data proves nothing.",
      );
      return;
    }
    const result = await validateAction.run(() =>
      api.validate(projectId, selectedId, { capture_ids: corpus }),
    );
    if (result) {
      setRunResult(result);
      setRunId(String(result.run_id));
      workspace.invalidate();
    }
  };

  if (!projectId) {
    return (
      <div className="p-4">
        <EmptyState
          title="No project selected"
          description="Open a project on the Overview page first."
        />
      </div>
    );
  }

  return (
    <div className="flex h-full flex-col">
      <div className="flex shrink-0 items-start justify-between gap-4 border-b border-line px-4 py-3">
        <div>
          <h1 className="text-sm font-semibold tracking-tight text-text">
            Hypotheses &amp; Rules
          </h1>
          <p className="mt-0.5 max-w-3xl text-2xs leading-relaxed text-text-muted">
            Write an executable interpretation, run it against a corpus and read the
            counterexamples. A rule that survives every message in this corpus is
            <em> supported by observed data</em> — not proven universally.
          </p>
        </div>
      </div>

      <div className="grid min-h-0 flex-1 grid-cols-1 gap-3 overflow-auto p-3 xl:grid-cols-[280px_1fr_400px]">
        {/* -- left: hypotheses and interpretations -------------------- */}
        <div className="space-y-3">
          <Panel
            title="Hypotheses"
            actions={
              <button
                type="button"
                className="btn"
                onClick={async () => {
                  const name = window.prompt("Hypothesis name");
                  if (!name) return;
                  const created = await action.run(() =>
                    api.createHypothesis(projectId, { name, status: "draft" }),
                  );
                  if (created) workspace.invalidate();
                }}
              >
                new
              </button>
            }
          >
            {hypotheses.state === "loading" ? (
              <Skeleton rows={5} />
            ) : (hypotheses.data ?? []).length === 0 ? (
              <EmptyState
                title="No hypotheses yet"
                description="A hypothesis records what you believe the protocol looks like and why."
              />
            ) : (
              <ul>
                {(hypotheses.data as Record<string, unknown>[]).map((h) => {
                  const row = h as unknown as {
                    id: string;
                    name: string;
                    status: string;
                    version: number;
                    updated_at: string;
                  };
                  return (
                    <li key={row.id} className="border-b border-line/60 px-3 py-2">
                      <div className="flex items-center justify-between gap-2">
                        <span className="truncate text-2xs text-text">{row.name}</span>
                        <Badge tone={hypothesisTone(row.status)}>{row.status}</Badge>
                      </div>
                      <p className="mt-0.5 text-2xs text-text-faint">
                        v{row.version} · {formatTimestamp(Date.parse(row.updated_at) / 1000)}
                      </p>
                      <select
                        className="input mt-1.5"
                        value={row.status}
                        aria-label={`Status of ${row.name}`}
                        onChange={async (event) => {
                          const next = event.target.value;
                          await action.run(
                            () => api.updateHypothesis(projectId, row.id, { status: next }),
                            "Hypothesis updated.",
                          );
                          workspace.invalidate();
                        }}
                      >
                        {[
                          "draft",
                          "proposed",
                          "testing",
                          "supported",
                          "contradicted",
                          "revised",
                          "rejected",
                        ].map((status) => (
                          <option key={status} value={status}>
                            {status}
                          </option>
                        ))}
                      </select>
                    </li>
                  );
                })}
              </ul>
            )}
          </Panel>

          <Panel title="Interpretations">
            {interpretations.state === "loading" ? (
              <Skeleton rows={4} />
            ) : (interpretations.data ?? []).length === 0 ? (
              <EmptyState
                title="No rules yet"
                description="Write a specification on the right and create it."
              />
            ) : (
              <ul>
                {interpretations.data.map((row) => (
                  <li key={row.id}>
                    <button
                      type="button"
                      onClick={() => setSelectedId(row.id)}
                      className={cn(
                        "w-full border-b border-line/60 px-3 py-2 text-left transition-colors",
                        selectedId === row.id ? "bg-accent-faint" : "hover:bg-surface-raised",
                      )}
                    >
                      <span className="block truncate font-mono text-2xs text-text">
                        {row.name}
                      </span>
                      <span className="mt-0.5 block text-2xs text-text-faint">
                        v{row.version} · {row.checksum.slice(0, 16)}…
                      </span>
                    </button>
                  </li>
                ))}
              </ul>
            )}
          </Panel>
        </div>

        {/* -- middle: editor ------------------------------------------- */}
        <Panel
          title="Interpretation specification (JSON)"
          actions={
            <>
              <button
                type="button"
                className="btn"
                onClick={() => setDraft(JSON.stringify(STARTER_SPEC, null, 2))}
              >
                reset
              </button>
              <button type="button" className="btn btn-primary" onClick={create}>
                create
              </button>
              <button
                type="button"
                className="btn"
                disabled={!selectedId}
                onClick={update}
              >
                save
              </button>
            </>
          }
        >
          <div className="flex h-full min-h-0 flex-col">
            <textarea
              className="min-h-[420px] flex-1 resize-none border-0 bg-surface-sunken p-3 font-mono text-2xs text-text outline-none"
              value={draft}
              spellCheck={false}
              onChange={(event) => setDraft(event.target.value)}
              aria-label="Interpretation specification"
            />
            <div className="border-t border-line p-2">
              {specError ? (
                <p className="font-mono text-2xs text-status-bad">{specError}</p>
              ) : (
                <p className="text-2xs text-status-ok">
                  <Check className="mr-1 inline h-3 w-3" aria-hidden />
                  Valid JSON. The backend validates the schema again on save.
                </p>
              )}
              {action.notice && (
                <p className="mt-1 text-2xs text-status-ok">{action.notice}</p>
              )}
              {action.error && (
                <p className="mt-1 font-mono text-2xs text-status-bad">{action.error}</p>
              )}
            </div>
          </div>
        </Panel>

        {/* -- right: validation and counterexamples -------------------- */}
        <div className="space-y-3">
          <Panel title="Validate against a corpus">
            <div className="space-y-2 p-3">
              <CorpusPicker
                projectId={projectId}
                selected={corpus}
                onChange={setCorpus}
              />
              <button
                type="button"
                className="btn btn-primary w-full"
                disabled={!selectedId || validateAction.pending}
                onClick={validate}
              >
                <FlaskConical className="h-3 w-3" aria-hidden />
                {validateAction.pending ? "Validating…" : "Run validation"}
              </button>
              {validateAction.error && (
                <p className="font-mono text-2xs text-status-bad">
                  {validateAction.error}
                </p>
              )}
              {runResult && (
                <VerdictSummary result={runResult} />
              )}
            </div>
          </Panel>

          {run && (
            <Panel title="Validation run">
              <dl className="space-y-1 p-3 font-mono text-2xs">
                <Row label="run" value={run.id.slice(0, 16)} />
                <Row label="rule" value={run.interpretation_name ?? "-"} />
                <Row label="rule version" value={String(run.interpretation_version ?? "-")} />
                <Row
                  label="checksum"
                  value={(run.specification_checksum ?? "-").slice(0, 16)}
                />
                <Row label="status" value={run.status} />
                <Row label="analyzer" value={run.analyzer_version} />
              </dl>
              {run.stale && (
                <div className="px-3 pb-3">
                  <Caveat tone="warn">
                    {run.stale_reason} Re-run the validation before citing these results.
                  </Caveat>
                </div>
              )}
            </Panel>
          )}

          <Panel title="Counterexamples">
            {counterexamples.state === "loading" ? (
              <Skeleton rows={6} />
            ) : counterexamples.data && counterexamples.data.count > 0 ? (
              <div className="space-y-2 p-3">
                <Badge tone="bad">
                  {counterexamples.data.count} message(s) broke the rule
                </Badge>
                <ul className="space-y-2">
                  {counterexamples.data.counterexamples.map((example) => {
                    const row = example as unknown as {
                      result_id: string;
                      message_id: string;
                      start_offset: number;
                      end_offset: number;
                      violated_rule: string | null;
                      reasons: { message: string; field?: string }[];
                      alternative_explanations: string[];
                      explanation: string;
                    };
                    return (
                      <li
                        key={row.result_id}
                        className="rounded-sm border border-status-bad/30 bg-status-bad/5 p-2.5"
                      >
                        <div className="flex items-center justify-between gap-2">
                          <span className="font-mono text-2xs text-accent">
                            msg {row.message_id.slice(0, 12)}
                          </span>
                          <Badge tone="bad">{row.violated_rule ?? "rule"}</Badge>
                        </div>
                        <p className="mt-1 font-mono text-2xs text-text-muted">
                          offsets {row.start_offset}…{row.end_offset}
                        </p>
                        <ul className="mt-1 space-y-0.5">
                          {row.reasons.map((reason, index) => (
                            <li key={index} className="text-2xs text-text">
                              • {reason.message}
                            </li>
                          ))}
                        </ul>
                        <details className="mt-1.5">
                          <summary className="cursor-pointer text-2xs text-text-muted">
                            alternative explanations ({row.alternative_explanations.length})
                          </summary>
                          <ul className="mt-1 space-y-0.5">
                            {row.alternative_explanations.map((text, index) => (
                              <li key={index} className="text-2xs text-text-muted">
                                – {text}
                              </li>
                            ))}
                          </ul>
                        </details>
                      </li>
                    );
                  })}
                </ul>
                <Caveat tone="warn">{counterexamples.data.disclaimer}</Caveat>
              </div>
            ) : counterexamples.data ? (
              <EmptyState
                title="No counterexamples"
                description="Every message in this corpus satisfied the rule."
              />
            ) : (
              <EmptyState title="Run a validation to see counterexamples" />
            )}
          </Panel>

          {support.data && (
            <Panel title="What the format can express">
              <div className="space-y-2 p-3 text-2xs">
                <p className="text-text-muted">
                  <span className="text-text-faint">framing:</span>{" "}
                  {((support.data.supported_framing ?? []) as string[]).join(", ")}
                </p>
                <p className="text-text-muted">
                  <span className="text-text-faint">field kinds:</span>{" "}
                  {((support.data.supported_field_kinds ?? []) as string[]).join(", ")}
                </p>
                <div>
                  <p className="text-text-faint">explicitly unsupported:</p>
                  <ul className="mt-1 space-y-0.5">
                    {((support.data.explicitly_unsupported ?? []) as string[]).map(
                      (item, index) => (
                        <li key={index} className="text-status-warn">
                          • {item}
                        </li>
                      ),
                    )}
                  </ul>
                </div>
                <Caveat>{String(support.data.safety)}</Caveat>
              </div>
            </Panel>
          )}
        </div>
      </div>
    </div>
  );
}

function VerdictSummary({ result }: { result: Record<string, unknown> }) {
  const verdict = String(result.verdict ?? "");
  const summary = [
    ["total", result.total],
    ["matched", result.matched],
    ["partial", result.partial],
    ["failed", result.failed],
    ["unparsed", result.unparsed],
  ] as const;

  return (
    <div className="mt-2 rounded-sm border border-line bg-surface-raised p-2.5">
      <Badge tone={verdictTone(verdict)}>verdict: {verdict}</Badge>
      <dl className="mt-2 grid grid-cols-5 gap-1 text-center font-mono text-2xs">
        {summary.map(([label, value]) => (
          <div key={label}>
            <dt className="text-text-faint">{label}</dt>
            <dd
              className={cn(
                label === "failed" && Number(value) > 0
                  ? "text-status-bad"
                  : label === "matched"
                    ? "text-status-ok"
                    : "text-text",
              )}
            >
              {String(value)}
            </dd>
          </div>
        ))}
      </dl>
      {typeof result.notes === "object" && Array.isArray(result.notes) && (
        <ul className="mt-2 space-y-0.5">
          {(result.notes as string[]).map((note, index) => (
            <li key={index} className="text-2xs text-text-faint">
              {note}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

/** Choose captures by name; ids come from the capture list endpoint. */
function CorpusPicker({
  projectId,
  selected,
  onChange,
}: {
  projectId: string;
  selected: string[];
  onChange: (ids: string[]) => void;
}) {
  const captures = useAsync(async () => {
    // The capture ids for a project are obtained by exporting the project
    // listing; a dedicated lightweight endpoint is added below.
    const { api: client } = await import("@/lib/api");
    return client.projectCaptures(projectId);
  }, [projectId, selected.length]);

  return (
    <div>
      <p className="mb-1 text-2xs uppercase tracking-wider text-text-faint">
        Corpus (captures to validate against)
      </p>
      {captures.state === "loading" ? (
        <Skeleton rows={3} />
      ) : (captures.data ?? []).length === 0 ? (
        <p className="text-2xs text-text-faint">
          Import captures before validating a rule. A rule tested on no data proves nothing.
        </p>
      ) : (
        <ul className="max-h-40 space-y-0.5 overflow-auto">
          {captures.data!.map((capture) => {
            const checked = selected.includes(capture.id);
            return (
              <li key={capture.id}>
                <label className="flex items-center gap-2 px-1 py-0.5 text-2xs">
                  <input
                    type="checkbox"
                    checked={checked}
                    onChange={(event) => {
                      onChange(
                        event.target.checked
                          ? [...selected, capture.id]
                          : selected.filter((id) => id !== capture.id),
                      );
                    }}
                  />
                  <span className="truncate text-text">{capture.name}</span>
                  {capture.analysis_status === "completed" ? (
                    <Badge tone="ok">analysed</Badge>
                  ) : (
                    <Badge tone="warn">not analysed</Badge>
                  )}
                </label>
              </li>
            );
          })}
        </ul>
      )}
      {selected.length > 0 && (
        <button
          type="button"
          className="btn mt-1.5"
          onClick={() => onChange([])}
        >
          <X className="h-3 w-3" aria-hidden />
          clear corpus
        </button>
      )}
    </div>
  );
}

function Row({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex justify-between gap-2">
      <dt className="text-text-faint">{label}</dt>
      <dd className="min-w-0 truncate text-text">{value}</dd>
    </div>
  );
}

export { PlayCircle };

