"use client";

import { useSearchParams } from "next/navigation";
import { useState } from "react";
import { GitCompare } from "lucide-react";

import {
  Badge,
  Caveat,
  EmptyState,
  Panel,
  Skeleton,
} from "@/components/ui";
import { useAction, useAsync } from "@/hooks/use-async";
import { useWorkspace } from "@/hooks/use-workspace";
import { api } from "@/lib/api";

export default function DiffPage() {
  const workspace = useWorkspace();
  const params = useSearchParams();
  const projectId = params.get("project") ?? workspace.projectId;
  const [base, setBase] = useState("");
  const [compare, setCompare] = useState("");
  const [focus, setFocus] = useState("all");
  const action = useAction();

  const captures = useAsync(
    () => (projectId ? api.projectCaptures(projectId) : Promise.resolve([])),
    [projectId, workspace.revision],
  );

  const result = useAsync(
    async () => {
      if (!base || !compare) return null;
      return api.diff({
        base_capture_id: base,
        compare_capture_id: compare,
        focus,
        max_bytes: 4096,
      });
    },
    [base, compare, focus, action.error],
  );

  if (!projectId) {
    return (
      <div className="p-4">
        <EmptyState title="No project selected" />
      </div>
    );
  }

  const sessions = (result.data?.sessions ?? []) as {
    status: string;
    similarity: number;
    endpoints: string;
    reasons: string[];
    base_session_id: string | null;
    compare_session_id: string | null;
    byte_delta?: number;
    packet_delta?: number;
  }[];

  return (
    <div className="flex h-full flex-col">
      <div className="border-b border-line px-4 py-3">
        <h1 className="text-sm font-semibold tracking-tight text-text">Capture Diff</h1>
        <p className="mt-0.5 max-w-3xl text-2xs leading-relaxed text-text-muted">
          Sessions are matched on endpoints, direction, sizes and message-length shape —
          not on packet numbers, which stop corresponding as soon as behaviour changes.
        </p>
      </div>

      <div className="space-y-3 overflow-auto p-3">
        <Panel title="Comparison setup">
          <div className="grid gap-3 p-3 md:grid-cols-4">
            <label className="block">
              <span className="mb-1 block text-2xs uppercase tracking-wider text-text-faint">
                Baseline
              </span>
              <select
                className="input"
                value={base}
                onChange={(event) => setBase(event.target.value)}
              >
                <option value="">select a capture</option>
                {(captures.data ?? []).map((capture) => (
                  <option key={capture.id} value={capture.id}>
                    {capture.name}
                  </option>
                ))}
              </select>
            </label>
            <label className="block">
              <span className="mb-1 block text-2xs uppercase tracking-wider text-text-faint">
                Compare with
              </span>
              <select
                className="input"
                value={compare}
                onChange={(event) => setCompare(event.target.value)}
              >
                <option value="">select a capture</option>
                {(captures.data ?? []).map((capture) => (
                  <option key={capture.id} value={capture.id}>
                    {capture.name}
                  </option>
                ))}
              </select>
            </label>
            <label className="block">
              <span className="mb-1 block text-2xs uppercase tracking-wider text-text-faint">
                Focus
              </span>
              <select
                className="input"
                value={focus}
                onChange={(event) => setFocus(event.target.value)}
              >
                {["all", "endpoints", "sessions", "messages", "bytes", "diagnostics"].map(
                  (option) => (
                    <option key={option} value={option}>
                      {option}
                    </option>
                  ),
                )}
              </select>
            </label>
            <div className="flex items-end">
              <Badge tone={base && compare && base !== compare ? "info" : "warn"}>
                {base && compare && base !== compare
                  ? "ready"
                  : "choose two different captures"}
              </Badge>
            </div>
          </div>
          {action.error && (
            <p className="px-3 pb-3 font-mono text-2xs text-status-bad">{action.error}</p>
          )}
        </Panel>

        {!base || !compare ? (
          <Panel>
            <EmptyState
              title="Select a baseline and a comparison capture"
              description="The result is a heat map of differences. A difference is not an anomaly: it only means this recording differs from that one."
            />
          </Panel>
        ) : result.state === "loading" ? (
          <Panel>
            <Skeleton rows={10} />
          </Panel>
        ) : result.data ? (
          <>
            <Panel title="Session heat map">
              <table className="data-table">
                <thead>
                  <tr>
                    <th>Status</th>
                    <th>Endpoints</th>
                    <th>Similarity</th>
                    <th>Byte Δ</th>
                    <th>Packet Δ</th>
                    <th>Why</th>
                  </tr>
                </thead>
                <tbody>
                  {sessions.map((row, index) => (
                    <tr key={index}>
                      <td>
                        <Badge
                          tone={
                            row.status === "changed"
                              ? "warn"
                              : row.status === "added"
                                ? "info"
                                : row.status === "removed"
                                  ? "bad"
                                  : "ok"
                          }
                        >
                          {row.status}
                        </Badge>
                      </td>
                      <td className="text-text-muted">{row.endpoints}</td>
                      <td>{row.similarity.toFixed(3)}</td>
                      <td className={row.byte_delta ? "text-status-warn" : undefined}>
                        {row.byte_delta ?? 0}
                      </td>
                      <td>{row.packet_delta ?? 0}</td>
                      <td className="whitespace-normal text-text-muted">
                        {row.reasons.join("; ") || "—"}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
              <div className="p-3">
                <Caveat tone="warn">
                  {String(result.data.interpretation_note)}
                </Caveat>
              </div>
            </Panel>

            {typeof result.data.endpoints === "object" &&
              result.data.endpoints !== null && (
                <Panel title="Endpoints">
                  <div className="grid gap-3 p-3 md:grid-cols-3">
                    <EndpointList
                      title="added"
                      items={(result.data.endpoints as { added: string[] }).added}
                      tone="info"
                    />
                    <EndpointList
                      title="removed"
                      items={(result.data.endpoints as { removed: string[] }).removed}
                      tone="bad"
                    />
                    <EndpointList
                      title="common"
                      items={(result.data.endpoints as { common: string[] }).common}
                      tone="ok"
                    />
                  </div>
                </Panel>
              )}

            {Array.isArray(result.data.diagnostics) && (
              <Panel title="Message-level differences">
                <table className="data-table">
                  <thead>
                    <tr>
                      <th>Dir</th>
                      <th>#</th>
                      <th>Status</th>
                      <th>Base len</th>
                      <th>Compare len</th>
                      <th>Bytes changed</th>
                    </tr>
                  </thead>
                  <tbody>
                    {(
                      result.data.messages as {
                        direction: string;
                        index: number;
                        status: string;
                        changed_count?: number;
                        base?: { length: number };
                        compare?: { length: number };
                      }[]
                    )
                      .slice(0, 200)
                      .map((row, index) => (
                        <tr key={index}>
                          <td>{row.direction}</td>
                          <td className="text-text-faint">{row.index}</td>
                          <td>
                            <Badge
                              tone={
                                row.status === "length_changed"
                                  ? "warn"
                                  : row.status === "added"
                                    ? "info"
                                    : "bad"
                              }
                            >
                              {row.status}
                            </Badge>
                          </td>
                          <td>{row.base?.length ?? "—"}</td>
                          <td>{row.compare?.length ?? "—"}</td>
                          <td className="text-status-warn">{row.changed_count ?? 0}</td>
                        </tr>
                      ))}
                  </tbody>
                </table>
              </Panel>
            )}
          </>
        ) : null}
      </div>
    </div>
  );
}

function EndpointList({
  title,
  items,
  tone,
}: {
  title: string;
  items: string[];
  tone: "info" | "bad" | "ok";
}) {
  return (
    <div>
      <p className="mb-1">
        <Badge tone={tone}>
          {title} ({items.length})
        </Badge>
      </p>
      <ul className="space-y-0.5 font-mono text-2xs text-text-muted">
        {items.length === 0 ? (
          <li className="text-text-faint">none</li>
        ) : (
          items.map((item) => <li key={item}>{item}</li>)
        )}
      </ul>
    </div>
  );
}

export { GitCompare };

"use client";

import { useSearchParams } from "next/navigation";
import { useMemo, useState } from "react";

import {
  Badge,
  Caveat,
  EmptyState,
  ErrorState,
  Panel,
  Skeleton,
} from "@/components/ui";
import { useAsync } from "@/hooks/use-async";
import { useWorkspace } from "@/hooks/use-workspace";
import { api } from "@/lib/api";
import { cn, formatNumber } from "@/lib/format";

type Node = {
  id: string;
  kind: string;
  label: string;
  bytes_total: number;
  connections: number;
  unique_peers: number;
  degree: number;
  degree_centrality: number;
  betweenness: number | null;
  protocols: string[];
};

type Edge = {
  source: string;
  target: string;
  bytes_total: number;
  packets: number;
  protocols: string[];
  link_status: string;
};

export default function GraphPage() {
  const workspace = useWorkspace();
  const params = useSearchParams();
  const projectId = params.get("project") ?? workspace.projectId;
  const [selected, setSelected] = useState<string | null>(null);
  const [minBytes, setMinBytes] = useState(0);

  const captures = useAsync(
    () => (projectId ? api.projectCaptures(projectId) : Promise.resolve([])),
    [projectId, workspace.revision],
  );

  const graph = useAsync(
    async () => {
      const ids = (captures.data ?? [])
        .filter((c) => c.analysis_status === "completed")
        .map((c) => c.id);
      if (ids.length === 0) return null;
      return api.graph(ids);
    },
    [captures.data, projectId],
  );

  const nodes = ((graph.data?.nodes ?? []) as Node[]) ?? [];
  const edges = ((graph.data?.edges ?? []) as Edge[]) ?? [];

  const layout = useMemo(() => {
    // A deterministic circular layout: reproducible across renders, which a
    // force simulation would not be.
    const size = 420;
    const radius = size / 2 - 40;
    const positions = new Map<string, { x: number; y: number }>();
    nodes.forEach((node, index) => {
      const angle = (index / Math.max(1, nodes.length)) * Math.PI * 2 - Math.PI / 2;
      positions.set(node.id, {
        x: size / 2 + Math.cos(angle) * radius,
        y: size / 2 + Math.sin(angle) * radius,
      });
    });
    return { size, positions };
  }, [nodes]);

  const maxBytes = Math.max(1, ...nodes.map((n) => n.bytes_total));
  const centrality = (graph.data?.centrality ?? []) as {
    rank: number;
    label: string;
    node: Node;
  }[];

  const selectedNode = nodes.find((n) => n.id === selected) ?? null;
  const connectedEdges = selected
    ? edges.filter((e) => e.source === selected || e.target === selected)
    : [];

  if (!projectId) {
    return (
      <div className="p-4">
        <EmptyState title="No project selected" />
      </div>
    );
  }

  return (
    <div className="flex h-full flex-col">
      <div className="border-b border-line px-4 py-3">
        <h1 className="text-sm font-semibold tracking-tight text-text">Network Graph</h1>
        <p className="mt-0.5 max-w-3xl text-2xs leading-relaxed text-text-muted">
          Edges exist only where traffic was actually observed. Node size reflects
          observed volume; centrality is a triage aid, not an accusation.
        </p>
      </div>

      <div className="grid min-h-0 flex-1 grid-cols-1 gap-3 overflow-auto p-3 lg:grid-cols-[1fr_340px]">
        <div className="space-y-3">
          <Panel title="Interaction graph">
            {captures.state === "loading" ? (
              <Skeleton rows={8} />
            ) : graph.state === "error" ? (
              <ErrorState message={graph.error ?? ""} onRetry={graph.reload} />
            ) : graph.data ? (
              <div className="p-3">
                <svg
                  viewBox={`0 0 ${layout.size} ${layout.size}`}
                  className="mx-auto h-auto w-full max-w-[560px]"
                  role="img"
                  aria-label={`Network graph with ${nodes.length} nodes and ${edges.length} edges`}
                >
                  <g>
                    {edges.map((edge, index) => {
                      const a = layout.positions.get(edge.source);
                      const b = layout.positions.get(edge.target);
                      if (!a || !b) return null;
                      const active =
                        selected === edge.source || selected === edge.target;
                      return (
                        <line
                          key={index}
                          x1={a.x}
                          y1={a.y}
                          x2={b.x}
                          y2={b.y}
                          stroke={active ? "#3fb6c8" : "#313842"}
                          strokeWidth={1 + (edge.bytes_total / maxBytes) * 6}
                          strokeOpacity={active ? 0.9 : 0.5}
                        />
                      );
                    })}
                  </g>
                  <g>
                    {nodes.map((node) => {
                      const point = layout.positions.get(node.id);
                      if (!point) return null;
                      const r = 5 + (node.bytes_total / maxBytes) * 14;
                      const active = node.id === selected;
                      return (
                        <g
                          key={node.id}
                          onClick={() => setSelected(active ? null : node.id)}
                          className="cursor-pointer"
                          role="button"
                          tabIndex={0}
                          onKeyDown={(event) => {
                            if (event.key === "Enter" || event.key === " ") {
                              setSelected(active ? null : node.id);
                            }
                          }}
                        >
                          <circle
                            cx={point.x}
                            cy={point.y}
                            r={r}
                            fill={active ? "#3fb6c8" : "#171b21"}
                            stroke={active ? "#3fb6c8" : "#8d97a3"}
                            strokeWidth={1.5}
                          />
                          <text
                            x={point.x}
                            y={point.y + r + 11}
                            textAnchor="middle"
                            className="fill-[#8d97a3] font-mono text-[9px]"
                          >
                            {node.label}
                          </text>
                        </g>
                      );
                    })}
                  </g>
                </svg>
                <div className="mt-2 flex flex-wrap items-center gap-3 text-2xs text-text-faint">
                  <span>
                    nodes: {nodes.length} · edges: {edges.length} ·{" "}
                    {formatNumber(edges.reduce((sum, e) => sum + e.bytes_total, 0))} bytes
                    observed
                  </span>
                  {selected && (
                    <button type="button" className="btn" onClick={() => setSelected(null)}>
                      clear selection
                    </button>
                  )}
                </div>
                {(graph.data.warnings as string[] | undefined)?.map((warning, index) => (
                  <p key={index} className="mt-2 text-2xs text-status-warn">
                    {warning}
                  </p>
                ))}
              </div>
            ) : (
              <EmptyState
                title="No analysed captures"
                description="Run an analysis on at least one capture to build the graph."
              />
            )}
          </Panel>
        </div>

        <div className="space-y-3">
          {selectedNode && (
            <Panel title={`Node: ${selectedNode.label}`}>
              <div className="space-y-2 p-3">
                <dl className="grid grid-cols-2 gap-1 font-mono text-2xs">
                  <Stat label="bytes" value={formatNumber(selectedNode.bytes_total)} />
                  <Stat label="peers" value={String(selectedNode.unique_peers)} />
                  <Stat
                    label="degree"
                    value={selectedNode.degree_centrality.toFixed(3)}
                  />
                  <Stat
                    label="betweenness"
                    value={
                      selectedNode.betweenness === null
                        ? "not computed"
                        : selectedNode.betweenness.toFixed(4)
                    }
                  />
                </dl>
                <div>
                  <p className="mb-1 text-2xs uppercase tracking-wider text-text-faint">
                    Observed connections
                  </p>
                  <ul className="space-y-0.5 font-mono text-2xs">
                    {connectedEdges.map((edge, index) => (
                      <li key={index} className="flex justify-between gap-2">
                        <span className="text-text-muted">
                          {edge.source === selectedNode.id ? edge.target : edge.source}
                        </span>
                        <span className="text-text-faint">
                          {formatNumber(edge.bytes_total)} B
                        </span>
                      </li>
                    ))}
                  </ul>
                </div>
              </div>
            </Panel>
          )}

          <Panel title="Centrality ranking">
            {centrality.length === 0 ? (
              <EmptyState title="No centrality computed" />
            ) : (
              <ol className="space-y-1 p-3">
                {centrality.map((entry) => (
                  <li
                    key={entry.rank}
                    className={cn(
                      "rounded-sm border border-line px-2 py-1.5",
                      selected === entry.node.id && "border-accent-dim bg-accent-faint",
                    )}
                  >
                    <button
                      type="button"
                      className="w-full text-left"
                      onClick={() => setSelected(entry.node.id)}
                    >
                      <div className="flex items-center justify-between gap-2">
                        <span className="font-mono text-2xs text-text">
                          {entry.rank}. {entry.node.label}
                        </span>
                        <Badge tone="info">
                          deg {entry.node.degree_centrality.toFixed(2)}
                        </Badge>
                      </div>
                      <p className="mt-0.5 text-2xs text-text-faint">
                        betweenness{" "}
                        {entry.node.betweenness === null
                          ? "n/a"
                          : entry.node.betweenness.toFixed(4)}
                      </p>
                    </button>
                  </li>
                ))}
              </ol>
            )}
            {graph.data && (
              <div className="px-3 pb-3">
                <Caveat tone="warn">{String(graph.data.interpretation_note)}</Caveat>
              </div>
            )}
          </Panel>
        </div>
      </div>
    </div>
  );
}

function Stat({ label, value }: { label: string; value: string }) {
  return (
    <div>
      <dt className="text-text-faint">{label}</dt>
      <dd className="text-text">{value}</dd>
    </div>
  );
}

"use client";

import { useSearchParams } from "next/navigation";
import { useState } from "react";

import {
  Badge,
  Caveat,
  EmptyState,
  Panel,
  Skeleton,
} from "@/components/ui";
import { useAction, useAsync } from "@/hooks/use-async";
import { useWorkspace } from "@/hooks/use-workspace";
import { api } from "@/lib/api";
import { cn } from "@/lib/format";

export default function AnomaliesPage() {
  const workspace = useWorkspace();
  const params = useSearchParams();
  const projectId = params.get("project") ?? workspace.projectId;
  const [scope, setScope] = useState<"messages" | "sessions">("messages");

  const status = useAsync(() => api.anomaliesStatus(), []);
  const action = useAction();

  if (!projectId) {
    return (
      <div className="p-4">
        <EmptyState title="No project selected" />
      </div>
    );
  }

  const available = status.data?.available === true;

  return (
    <div className="flex h-full flex-col">
      <div className="border-b border-line px-4 py-3">
        <h1 className="text-sm font-semibold tracking-tight text-text">
          Anomaly Detection
        </h1>
        <p className="mt-0.5 max-w-3xl text-2xs leading-relaxed text-text-muted">
          Isolation Forest over a baseline corpus. Scores rank how unusual an entity is
          relative to that corpus; they are not probabilities and carry no severity.
        </p>
      </div>

      <div className="space-y-3 overflow-auto p-3">
        {status.state === "loading" ? (
          <Skeleton rows={4} />
        ) : !available ? (
          <Panel title="Unavailable">
            <div className="space-y-2 p-3">
              <Badge tone="warn">scikit-learn is not installed</Badge>
              <p className="text-2xs text-text-muted">
                {String(status.data?.availability_note ?? "")}
              </p>
              <pre className="overflow-x-auto rounded-sm border border-line bg-surface-sunken p-2 font-mono text-2xs">
{`python -m pip install "madrigal-protocol-lab-backend[analytics]"`}
              </pre>
              <Caveat>
                The product is fully usable without this module. Nothing else degrades
                when anomaly detection is unavailable.
              </Caveat>
            </div>
          </Panel>
        ) : (
          <>
            <Panel title="Train a baseline">
              <TrainForm
                projectId={projectId}
                scope={scope}
                onScopeChange={setScope}
                pending={action.pending}
                onTrain={async (body) => {
                  const result = await action.run(() =>
                    import("@/lib/api").then((m) =>
                      m.api.request("/api/anomalies/train", m.jsonSchema, {
                        method: "POST",
                        body: JSON.stringify(body),
                      }),
                    ),
                  );
                  return result;
                }}
              />
              {action.notice && <p className="px-3 pb-3 text-2xs text-status-ok">{action.notice}</p>}
              {action.error && (
                <p className="px-3 pb-3 font-mono text-2xs text-status-bad">{action.error}</p>
              )}
            </Panel>

            {typeof action.result === "object" && action.result !== null && (
              <Panel title="Latest model">
                <div className="space-y-2 p-3 font-mono text-2xs">
                  <pre className="overflow-x-auto rounded-sm border border-line bg-surface-sunken p-2">
                    {JSON.stringify(action.result, null, 2)}
                  </pre>
                </div>
              </Panel>
            )}
          </>
        )}
      </div>
    </div>
  );
}

function TrainForm({
  projectId,
  scope,
  onScopeChange,
  pending,
  onTrain,
}: {
  projectId: string;
  scope: "messages" | "sessions";
  onScopeChange: (scope: "messages" | "sessions") => void;
  pending: boolean;
  onTrain: (body: Record<string, unknown>) => Promise<unknown>;
}) {
  const captures = useAsync(() => api.projectCaptures(projectId), [projectId]);
  const [selected, setSelected] = useState<string[]>([]);
  const [name, setName] = useState("Baseline model");

  return (
    <div className="grid gap-3 p-3 md:grid-cols-3">
      <label className="block">
        <span className="mb-1 block text-2xs uppercase tracking-wider text-text-faint">
          Model name
        </span>
        <input
          className="input"
          value={name}
          maxLength={200}
          onChange={(event) => setName(event.target.value)}
        />
      </label>
      <label className="block">
        <span className="mb-1 block text-2xs uppercase tracking-wider text-text-faint">
          Scope
        </span>
        <select
          className="input"
          value={scope}
          onChange={(event) => onScopeChange(event.target.value as "messages" | "sessions")}
        >
          <option value="messages">messages</option>
          <option value="sessions">sessions</option>
        </select>
      </label>
      <div className="flex items-end">
        <button
          type="button"
          className="btn btn-primary"
          disabled={pending || selected.length === 0}
          onClick={() =>
            void onTrain({
              name,
              capture_ids: selected,
              scope,
              contamination: 0.05,
              n_estimators: 100,
              seed: 42,
            })
          }
        >
          {pending ? "Training…" : "Train baseline"}
        </button>
      </div>

      <div className="md:col-span-3">
        <p className="mb-1 text-2xs uppercase tracking-wider text-text-faint">
          Baseline corpus
        </p>
        {captures.state === "loading" ? (
          <Skeleton rows={2} />
        ) : (
          <ul className="max-h-40 space-y-0.5 overflow-auto">
            {(captures.data ?? []).map((capture) => (
              <li key={capture.id}>
                <label className="flex items-center gap-2 py-0.5 text-2xs">
                  <input
                    type="checkbox"
                    checked={selected.includes(capture.id)}
                    onChange={(event) =>
                      setSelected(
                        event.target.checked
                          ? [...selected, capture.id]
                          : selected.filter((id) => id !== capture.id),
                      )
                    }
                  />
                  <span className="truncate text-text">{capture.name}</span>
                  <span
                    className={cn(
                      "text-text-faint",
                      capture.analysis_status === "completed" && "text-status-ok",
                    )}
                  >
                    {capture.analysis_status}
                  </span>
                </label>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}

"use client";

import { useSearchParams } from "next/navigation";
import { useEffect, useState } from "react";
import { Search } from "lucide-react";

import {
  Badge,
  Caveat,
  EmptyState,
  Panel,
  Skeleton,
} from "@/components/ui";
import { useAction, useAsync } from "@/hooks/use-async";
import { useWorkspace } from "@/hooks/use-workspace";
import { api } from "@/lib/api";

const SUGGESTIONS = [
  "Find all TCP responses longer than 1000 bytes",
  "Show messages whose first two bytes match",
  "Find requests answered within 100 milliseconds",
  "Show streams with holes in the reconstructed bytes",
  "Find POST requests where HTTP content is visible",
];

export default function AssistantPage() {
  const workspace = useWorkspace();
  const params = useSearchParams();
  const projectId = params.get("project") ?? workspace.projectId;
  const [query, setQuery] = useState(params.get("q") ?? "");
  const [dryRun, setDryRun] = useState(true);
  const [useLlm, setUseLlm] = useState(false);
  const action = useAction();

  const capabilities = useAsync(() => api.assistantCapabilities(), []);
  const captures = useAsync(
    () => (projectId ? api.projectCaptures(projectId) : Promise.resolve([])),
    [projectId, workspace.revision],
  );
  const [corpus, setCorpus] = useState<string[]>([]);

  useEffect(() => {
    const fromUrl = params.get("q");
    if (fromUrl) setQuery(fromUrl);
  }, [params]);

  const result = action.pending ? null : (action as unknown as { result?: unknown }).result ?? null;

  return (
    <div className="flex h-full flex-col">
      <div className="border-b border-line px-4 py-3">
        <h1 className="text-sm font-semibold tracking-tight text-text">
          Investigation Assistant
        </h1>
        <p className="mt-0.5 max-w-3xl text-2xs leading-relaxed text-text-muted">
          Your question is compiled into a typed query plan, validated against a field
          allowlist, and executed through a fixed analytics API. No SQL, shell command or
          Python is ever generated from text — yours or a model's.
        </p>
      </div>

      <div className="grid min-h-0 flex-1 grid-cols-1 gap-3 overflow-auto p-3 lg:grid-cols-[1fr_360px]">
        <div className="space-y-3">
          <Panel title="Ask about the traffic">
            <div className="space-y-2 p-3">
              <textarea
                className="input h-20 resize-y"
                maxLength={1000}
                placeholder={SUGGESTIONS[0]}
                value={query}
                onChange={(event) => setQuery(event.target.value)}
                aria-label="Search request"
              />
              <div className="flex flex-wrap items-center gap-3">
                <label className="flex items-center gap-1.5 text-2xs text-text-muted">
                  <input
                    type="checkbox"
                    checked={dryRun}
                    onChange={(event) => setDryRun(event.target.checked)}
                  />
                  dry run (show the plan without executing)
                </label>
                <label className="flex items-center gap-1.5 text-2xs text-text-muted">
                  <input
                    type="checkbox"
                    checked={useLlm}
                    onChange={(event) => setUseLlm(event.target.checked)}
                  />
                  allow optional local model narration
                </label>
                <button
                  type="button"
                  className="btn btn-primary ml-auto"
                  disabled={!query.trim() || action.pending}
                  onClick={() =>
                    void action.run(() =>
                      api.assistantQuery({
                        query: query.trim(),
                        capture_ids: corpus,
                        dry_run: dryRun,
                        use_llm: useLlm,
                      }),
                    )
                  }
                >
                  <Search className="h-3 w-3" aria-hidden />
                  {action.pending ? "Working…" : "Run"}
                </button>
              </div>

              {(action.error || action.notice) && (
                <p
                  className={`font-mono text-2xs ${action.error ? "text-status-bad" : "text-status-ok"}`}
                >
                  {action.error ?? action.notice}
                </p>
              )}
            </div>
          </Panel>

          {result ? <ResultView result={result as Record<string, unknown>} /> : (
            <Panel>
              <EmptyState
                title="No result yet"
                description="Start with a dry run: you will see exactly how the request was interpreted before anything is executed."
              />
            </Panel>
          )}
        </div>

        <div className="space-y-3">
          <Panel title="Corpus">
            {captures.state === "loading" ? (
              <Skeleton rows={4} />
            ) : (
              <ul className="max-h-48 space-y-0.5 overflow-auto p-3">
                {(captures.data ?? []).map((capture) => (
                  <li key={capture.id}>
                    <label className="flex items-center gap-2 py-0.5 text-2xs">
                      <input
                        type="checkbox"
                        checked={corpus.includes(capture.id)}
                        onChange={(event) =>
                          setCorpus(
                            event.target.checked
                              ? [...corpus, capture.id]
                              : corpus.filter((id) => id !== capture.id),
                          )
                        }
                      />
                      <span className="truncate text-text">{capture.name}</span>
                    </label>
                  </li>
                ))}
                {(captures.data ?? []).length === 0 && (
                  <li className="text-2xs text-text-faint">
                    No captures imported; the search will cover the whole index.
                  </li>
                )}
              </ul>
            )}
          </Panel>

          <Panel title="What this can and cannot do">
            {capabilities.state === "loading" ? (
              <Skeleton rows={6} />
            ) : capabilities.data ? (
              <div className="space-y-2 p-3 text-2xs">
                <p className="text-text-muted">
                  {String(capabilities.data.execution_model)}
                </p>
                <div>
                  <p className="text-text-faint">queryable entities:</p>
                  <p className="font-mono text-text">
                    {((capabilities.data.entities ?? []) as string[]).join(", ")}
                  </p>
                </div>
                <div>
                  <p className="text-text-faint">external AI:</p>
                  <Badge
                    tone={
                      (capabilities.data.external_ai as { enabled?: boolean })?.enabled
                        ? "warn"
                        : "ok"
                    }
                  >
                    {String((capabilities.data.external_ai as { default?: string })?.default ?? "")}
                  </Badge>
                </div>
                <ul className="space-y-1">
                  {((capabilities.data.limitations ?? []) as string[]).map((item, index) => (
                    <li key={index} className="text-status-warn">
                      • {item}
                    </li>
                  ))}
                </ul>
              </div>
            ) : null}
          </Panel>

          <Panel title="Try one of these">
            <ul className="space-y-1 p-3">
              {SUGGESTIONS.map((suggestion) => (
                <li key={suggestion}>
                  <button
                    type="button"
                    className="link text-left text-2xs"
                    onClick={() => setQuery(suggestion)}
                  >
                    {suggestion}
                  </button>
                </li>
              ))}
            </ul>
          </Panel>
        </div>
      </div>
    </div>
  );
}

function ResultView({ result }: { result: Record<string, unknown> }) {
  const status = String(result.status ?? "");

  if (status === "needs_clarification") {
    return (
      <Panel title="The assistant refused to guess">
        <div className="space-y-2 p-3">
          <Badge tone="warn">needs clarification</Badge>
          <p className="text-2xs text-text">{String(result.question ?? "")}</p>
          <Caveat tone="warn">{String(result.note ?? "")}</Caveat>
          <ul className="space-y-1">
            {((result.suggestions ?? []) as string[]).map((item) => (
              <li key={item} className="font-mono text-2xs text-text-muted">
                {item}
              </li>
            ))}
          </ul>
        </div>
      </Panel>
    );
  }

  const plan = result.plan as Record<string, unknown> | undefined;
  const queryResult = result.result as Record<string, unknown> | undefined;

  return (
    <Panel title="Result">
      <div className="space-y-2 p-3">
        <div className="flex flex-wrap items-center gap-2">
          <Badge tone={result.executed ? "ok" : "info"}>
            {result.executed ? "executed" : "planned (dry run)"}
          </Badge>
          <span className="text-2xs text-text-muted">{String(result.interpretation ?? "")}</span>
        </div>

        {plan && (
          <div>
            <p className="mb-1 text-2xs uppercase tracking-wider text-text-faint">
              Compiled query plan
            </p>
            <pre className="overflow-x-auto rounded-sm border border-line bg-surface-sunken p-2 font-mono text-2xs">
              {JSON.stringify(plan, null, 2)}
            </pre>
          </div>
        )}

        {Array.isArray(result.warnings) && (result.warnings as string[]).length > 0 && (
          <ul className="space-y-1">
            {(result.warnings as string[]).map((warning, index) => (
              <li key={index} className="text-2xs text-status-warn">
                ! {warning}
              </li>
            ))}
          </ul>
        )}

        {queryResult && (
          <div>
            <p className="mb-1 text-2xs uppercase tracking-wider text-text-faint">
              {String(queryResult.count ?? 0)} matching{" "}
              {String(queryResult.entity ?? "records")}
            </p>
            <table className="data-table">
              <thead>
                <tr>
                  <th>id</th>
                  <th>stream</th>
                  <th>direction</th>
                  <th>range</th>
                  <th>length</th>
                  <th>entropy</th>
                </tr>
              </thead>
              <tbody>
                {((queryResult.items ?? []) as Record<string, unknown>[]).slice(0, 200).map(
                  (item, index) => (
                    <tr key={index}>
                      <td className="text-accent">{String(item.id ?? "").slice(0, 12)}</td>
                      <td className="text-text-faint">
                        {String(item.stream_id ?? "—").slice(0, 12)}
                      </td>
                      <td>{String(item.direction ?? "—")}</td>
                      <td className="text-text-muted">
                        {item.start_offset !== undefined
                          ? `${item.start_offset}…${item.end_offset}`
                          : "—"}
                      </td>
                      <td>{String(item.length ?? "—")}</td>
                      <td>
                        {item.entropy !== undefined
                          ? Number(item.entropy).toFixed(2)
                          : "—"}
                      </td>
                    </tr>
                  ),
                )}
              </tbody>
            </table>
          </div>
        )}

        {typeof result.llm === "object" && result.llm !== null && (
          <div className="rounded-sm border border-status-warn/30 bg-status-warn/5 p-2.5">
            <Badge tone="warn">model narration</Badge>
            <p className="mt-1 whitespace-pre-wrap text-2xs text-text">
              {String((result.llm as { text?: string }).text ?? "")}
            </p>
            <Caveat tone="warn">
              {String(
                (result.llm as { disclaimer?: string }).disclaimer ??
                  "Model-generated narration, not evidence.",
              )}
            </Caveat>
          </div>
        )}
      </div>
    </Panel>
  );
}

"use client";

import { useSearchParams } from "next/navigation";
import { useState } from "react";

import {
  Badge,
  Caveat,
  EmptyState,
  Panel,
  Skeleton,
} from "@/components/ui";
import { useAction, useAsync } from "@/hooks/use-async";
import { useWorkspace } from "@/hooks/use-workspace";
import { api } from "@/lib/api";

type Section = {
  number: number;
  title: string;
  body: string;
  evidence: { kind: string; id: string }[];
  notes: string[];
};

export default function ReportsPage() {
  const workspace = useWorkspace();
  const params = useSearchParams();
  const projectId = params.get("project") ?? workspace.projectId;
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const action = useAction();

  const reports = useAsync(
    () => (projectId ? api.reports(projectId) : Promise.resolve([])),
    [projectId, workspace.revision],
  );

  const current = useAsync(
    () => (selectedId ? api.report(selectedId) : Promise.resolve(null)),
    [selectedId],
  );

  if (!projectId) {
    return (
      <div className="p-4">
        <EmptyState title="No project selected" />
      </div>
    );
  }

  return (
    <div className="flex h-full flex-col">
      <div className="flex shrink-0 items-start justify-between gap-4 border-b border-line px-4 py-3">
        <div>
          <h1 className="text-sm font-semibold tracking-tight text-text">Reports</h1>
          <p className="mt-0.5 max-w-3xl text-2xs leading-relaxed text-text-muted">
            Every section is assembled from stored facts and lists the evidence it came
            from. A report can be produced entirely offline, without any language model.
          </p>
        </div>
        <button
          type="button"
          className="btn btn-primary"
          disabled={action.pending}
          onClick={async () => {
            const created = await action.run(() =>
              api.report(projectId, { title: "Investigation report" }),
            );
            if (created) {
              setSelectedId(String(created.report_id));
              workspace.invalidate();
            }
          }}
        >
          {action.pending ? "Generating…" : "Generate report"}
        </button>
      </div>

      <div className="grid min-h-0 flex-1 grid-cols-1 gap-3 overflow-hidden p-3 lg:grid-cols-[280px_1fr]">
        <Panel title="Generated reports">
          {reports.state === "loading" ? (
            <Skeleton rows={5} />
          ) : (reports.data ?? []).length === 0 ? (
            <EmptyState title="No reports yet" />
          ) : (
            <ul>
              {(reports.data as Record<string, unknown>[]).map((report) => {
                const row = report as unknown as {
                  id: string;
                  title: string;
                  created_at: string;
                  ai_used: boolean;
                };
                return (
                  <li key={row.id}>
                    <button
                      type="button"
                      onClick={() => setSelectedId(row.id)}
                      className={`w-full border-b border-line/60 px-3 py-2 text-left ${
                        selectedId === row.id ? "bg-accent-faint" : "hover:bg-surface-raised"
                      }`}
                    >
                      <span className="block truncate text-2xs text-text">{row.title}</span>
                      <span className="mt-0.5 flex items-center gap-2 text-2xs text-text-faint">
                        {new Date(row.created_at).toISOString().slice(0, 19)}
                        {row.ai_used && <Badge tone="warn">AI used</Badge>}
                      </span>
                    </button>
                  </li>
                );
              })}
            </ul>
          )}
          {action.error && (
            <p className="p-3 font-mono text-2xs text-status-bad">{action.error}</p>
          )}
        </Panel>

        <Panel
          title="Report"
          actions={
            selectedId && (
              <div className="flex gap-2">
                <a
                  className="btn"
                  href={`${api.constructor === Object ? "" : ""}`}
                  onClick={(event) => {
                    event.preventDefault();
                    window.open(
                      `${location.origin}/api/reports/${selectedId}/markdown`,
                      "_blank",
                    );
                  }}
                >
                  Markdown
                </a>
                <a
                  className="btn"
                  href="#json"
                  onClick={(event) => {
                    event.preventDefault();
                    window.open(`${location.origin}/api/reports/${selectedId}/json`, "_blank");
                  }}
                >
                  JSON
                </a>
              </div>
            )
          }
        >
          {!selectedId ? (
            <EmptyState
              title="No report selected"
              description="Generate a report to see the investigation written out with its evidence."
            />
          ) : current.state === "loading" ? (
            <Skeleton rows={14} />
          ) : current.data ? (
            <ReportView report={current.data as Record<string, unknown>} />
          ) : null}
        </Panel>
      </div>
    </div>
  );
}

function ReportView({ report }: { report: Record<string, unknown> }) {
  const sections = (report.sections ?? []) as Section[];
  const warnings = (report.ai_warnings ?? []) as string[];

  return (
    <div className="space-y-4 p-4">
      <div>
        <h2 className="text-sm font-semibold text-text">{String(report.title)}</h2>
        <p className="mt-0.5 text-2xs text-text-faint">
          generator: {String(report.generator)} · created{" "}
          {new Date(String(report.created_at)).toISOString().slice(0, 19)}
        </p>
      </div>

      {report.ai_used === true && (
        <div className="rounded-sm border border-status-warn/30 bg-status-warn/5 p-2.5">
          <Badge tone="warn">a language model contributed to this report</Badge>
          {warnings.map((warning, index) => (
            <Caveat key={index} tone="warn">
              {warning}
            </Caveat>
          ))}
        </div>
      )}
      {report.ai_used === false && warnings.length > 0 && (
        <div className="space-y-1">
          {warnings.map((warning, index) => (
            <Caveat key={index}>{warning}</Caveat>
          ))}
        </div>
      )}

      {sections.map((section) => (
        <section key={section.number}>
          <h3 className="text-xs font-semibold text-accent">
            {section.number}. {section.title}
          </h3>
          <div className="sanitized-markdown mt-1 text-2xs text-text">
            {section.body.split("\n").map((line, index) => (
              <p key={index}>{line || " "}</p>
            ))}
          </div>
          {section.evidence.length > 0 && (
            <p className="mt-1 font-mono text-2xs text-text-faint">
              evidence:{" "}
              {section.evidence
                .slice(0, 8)
                .map((item) => `${item.kind}:${item.id.slice(0, 10)}`)
                .join("  ")}
              {section.evidence.length > 8 ? `  (+${section.evidence.length - 8})` : ""}
            </p>
          )}
          {section.notes.map((note, index) => (
            <Caveat key={index}>{note}</Caveat>
          ))}
        </section>
      ))}
    </div>
  );
}

"use client";

import { useState } from "react";
import { ShieldCheck } from "lucide-react";

import {
  Badge,
  Caveat,
  EmptyState,
  Panel,
  Skeleton,
} from "@/components/ui";
import { useAction, useAsync } from "@/hooks/use-async";
import { checkTone, cn } from "@/lib/format";

type Check = {
  id: string;
  title: string;
  verdict: "pass" | "fail" | "unknown" | "na";
  detail: string;
  evidence: Record<string, unknown>;
  remediation: string | null;
};

export default function SecurityPage() {
  const report = useAsync(() => api_securityReport(), []);
  const action = useAction();
  const [tab, setTab] = useState<"checks" | "audit">("checks");

  const audit = useAsync(() => api_auditEvents(), [tab === "audit"]);
  const chain = useAsync(() => api_verifyAudit(), [tab === "audit"]);

  const data = report.data as Record<string, unknown> | null;
  const checks = ((data?.security_checks as { checks?: Check[] })?.checks ?? []) as Check[];
  const summary =
    (data?.security_checks as { summary?: Record<string, number> })?.summary ?? {};

  return (
    <div className="flex h-full flex-col">
      <div className="flex shrink-0 items-start justify-between gap-4 border-b border-line px-4 py-3">
        <div>
          <h1 className="text-sm font-semibold tracking-tight text-text">Security Center</h1>
          <p className="mt-0.5 max-w-3xl text-2xs leading-relaxed text-text-muted">
            Real local checks with honest verdicts. A check that could not be performed
            says so; nothing here is a penetration test or a certification.
          </p>
        </div>
        <button
          type="button"
          className="btn btn-primary"
          disabled={action.pending}
          onClick={async () => {
            const result = await action.run(() => api_securityCheck());
            if (result) report.setData(result);
          }}
        >
          <ShieldCheck className="h-3 w-3" aria-hidden />
          {action.pending ? "Checking…" : "Run configuration check"}
        </button>
      </div>

      <div className="flex shrink-0 gap-1 border-b border-line px-3 py-1.5">
        {(["checks", "audit"] as const).map((name) => (
          <button
            key={name}
            type="button"
            className={cn("btn", tab === name && "btn-primary")}
            onClick={() => setTab(name)}
          >
            {name === "checks" ? "Configuration checks" : "Audit log"}
          </button>
        ))}
      </div>

      <div className="min-h-0 flex-1 overflow-auto p-3">
        {action.error && (
          <p className="mb-3 rounded-sm border border-status-bad/40 bg-status-bad/5 p-2 font-mono text-2xs text-status-bad">
            {action.error}
          </p>
        )}

        {tab === "checks" ? (
          report.state === "loading" ? (
            <Skeleton rows={10} />
          ) : checks.length === 0 ? (
            <EmptyState title="No checks available" />
          ) : (
            <div className="space-y-3">
              <div className="flex flex-wrap gap-2">
                {(["pass", "fail", "unknown", "na"] as const).map((verdict) => (
                  <Badge key={verdict} tone={checkTone(verdict)}>
                    {verdict}: {summary[verdict] ?? 0}
                  </Badge>
                ))}
              </div>

              <Panel title="Runtime">
                <dl className="grid gap-2 p-3 font-mono text-2xs sm:grid-cols-3">
                  <Field label="mode" value={String(data?.mode ?? "-")} />
                  <Field
                    label="bind"
                    value={
                      ((data?.bind ?? {}) as { host: string; port: number }).host +
                      ":" +
                      ((data?.bind ?? {}) as { host: string; port: number }).port
                    }
                  />
                  <Field
                    label="platform"
                    value={String(
                      (data?.platform as { system?: string; release?: string } | undefined)
                        ?.system ?? "-",
                    )}
                  />
                </dl>
              </Panel>

              <Panel title="Checks">
                <ul className="divide-y divide-line/60">
                  {checks.map((check) => (
                    <li key={check.id} className="px-3 py-2">
                      <div className="flex flex-wrap items-center gap-2">
                        <Badge tone={checkTone(check.verdict)}>{check.verdict}</Badge>
                        <span className="text-2xs font-medium text-text">{check.title}</span>
                        <span className="ml-auto font-mono text-2xs text-text-faint">
                          {check.id}
                        </span>
                      </div>
                      <p className="mt-1 text-2xs leading-relaxed text-text-muted">
                        {check.detail}
                      </p>
                      {check.remediation && (
                        <p className="mt-1 text-2xs text-status-warn">
                          → {check.remediation}
                        </p>
                      )}
                    </li>
                  ))}
                </ul>
              </Panel>

              <Panel title="Integrations">
                <ul className="space-y-2 p-3 text-2xs">
                  {Object.entries(
                    (data?.integrations ?? {}) as Record<string, Record<string, unknown>>,
                  ).map(([name, value]) => (
                    <li key={name} className="flex flex-wrap items-center gap-2">
                      <span className="w-40 font-mono text-text-faint">{name}</span>
                      <Badge
                        tone={
                          value.available === true
                            ? "ok"
                            : value.available === false
                              ? "unknown"
                              : "neutral"
                        }
                      >
                        {String(value.available)}
                      </Badge>
                      <span className="text-text-muted">{String(value.note ?? "")}</span>
                    </li>
                  ))}
                </ul>
              </Panel>

              <Panel title="Documented limits">
                <ul className="space-y-1 p-3">
                  {((data?.documented_limits ?? []) as string[]).map((limit, index) => (
                    <li key={index} className="text-2xs text-text-muted">
                      • {limit}
                    </li>
                  ))}
                  <Caveat tone="warn">
                    {String(
                      (data?.security_checks as { scope?: string })?.scope ?? "",
                    )}
                  </Caveat>
                </ul>
              </Panel>
            </div>
          )
        ) : (
          <div className="space-y-3">
            <Panel title="Audit chain integrity">
              {chain.state === "loading" ? (
                <Skeleton rows={2} />
              ) : chain.data ? (
                <div className="space-y-1 p-3">
                  <Badge tone={chain.data.valid ? "ok" : "bad"}>
                    {chain.data.valid ? "chain verified" : "chain broken"}
                  </Badge>
                  <p className="text-2xs text-text-muted">
                    {String(chain.data.explanation ?? "")}
                  </p>
                </div>
              ) : null}
            </Panel>

            <Panel title="Security events">
              {audit.state === "loading" ? (
                <Skeleton rows={10} />
              ) : audit.data ? (
                <table className="data-table">
                  <thead>
                    <tr>
                      <th>Time</th>
                      <th>Action</th>
                      <th>Outcome</th>
                      <th>Risk</th>
                      <th>Object</th>
                    </tr>
                  </thead>
                  <tbody>
                    {(audit.data.items as Record<string, unknown>[]).map((item) => (
                      <tr key={String(item.id)}>
                        <td className="text-text-faint">
                          {String(item.timestamp).slice(0, 19)}
                        </td>
                        <td className="text-accent">{String(item.action)}</td>
                        <td>{String(item.outcome)}</td>
                        <td>
                          <Badge
                            tone={
                              item.risk === "error"
                                ? "bad"
                                : item.risk === "warning"
                                  ? "warn"
                                  : "neutral"
                            }
                          >
                            {String(item.risk)}
                          </Badge>
                        </td>
                        <td className="text-text-muted">
                          {item.object_type ? `${item.object_type}:${String(item.object_id).slice(0, 10)}` : "—"}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              ) : (
                <EmptyState title="No audit events" />
              )}
            </Panel>
          </div>
        )}
      </div>
    </div>
  );
}

function Field({ label, value }: { label: string; value: string }) {
  return (
    <div>
      <dt className="text-text-faint">{label}</dt>
      <dd className="text-text">{value}</dd>
    </div>
  );
}

function api_securityReport() {
  return import("@/lib/api").then((m) => m.api.securityReport());
}

function api_securityCheck() {
  return import("@/lib/api").then((m) => m.api.securityCheck());
}

function api_auditEvents() {
  return import("@/lib/api").then((m) => m.api.auditEvents("?limit=200"));
}

function api_verifyAudit() {
  return import("@/lib/api").then((m) => m.api.verifyAudit());
}

